// Notification ping, embedded the same way as the default avatar so the
// whole app stays a single self-contained file. Played for incoming DM/group
// DM messages, and for server messages that mention you (see playPingSound()).
const PING_SOUND_URL = 'data:audio/mpeg;base64,';
// Created the first time it's needed, so decoding the sound doesn't slow down startup.
let pingAudioEl = null;
function playPingSound() {
  try { if (!pingAudioEl) pingAudioEl = new Audio(PING_SOUND_URL); pingAudioEl.currentTime = 0; pingAudioEl.play().catch(() => {}); } catch (e) {}
}

