$('show-register').onclick = () => { $('login-view').classList.add('hidden'); $('register-view').classList.remove('hidden'); };
$('show-login').onclick = () => { $('register-view').classList.add('hidden'); $('login-view').classList.remove('hidden'); };

$('login-btn').onclick = async () => {
  const username = $('login-username').value.trim();
  const pass = $('login-password').value;
  $('login-error').textContent = '';
  if (!username || !pass) { $('login-error').textContent = 'Please fill in both fields.'; return; }
  $('login-btn').disabled = true; $('login-btn').textContent = 'Checking...';
  try {
    const snap = await db.collection('users').doc(username).get();
    if (!snap.exists || snap.data().password !== pass) {
      $('login-error').textContent = 'Incorrect username or password.';
      $('login-btn').disabled = false; $('login-btn').textContent = 'Log In'; return;
    }
    const data = snap.data();
    const ban = banStatus(data);
    if (ban.banned) {
      $('login-btn').disabled = false; $('login-btn').textContent = 'Log In';
      showBanScreen(ban, false); return;
    }
    if (ban.expired) { await db.collection('users').doc(username).update({ banned: false, banReason: '', bannedUntil: null }); data.banned = false; }
    await normalizeProfile(username, data);
    myUid = username; myProfile = data; profileCache[myUid] = data;
    setSession(username);
    enterApp();
  } catch (e) {
    $('login-error').textContent = e.message || 'Something went wrong.';
  }
  $('login-btn').disabled = false; $('login-btn').textContent = 'Log In';
};

$('register-btn').onclick = async () => {
  const username = $('reg-username').value.trim();
  const pass = $('reg-password').value;
  $('register-error').textContent = '';
  if (!username || !pass) { $('register-error').textContent = 'Please fill in both fields.'; return; }
  if (username.length < 3) { $('register-error').textContent = 'Username must be at least 3 characters.'; return; }
  if (!/^[A-Za-z0-9_]+$/.test(username)) { $('register-error').textContent = 'Letters, numbers, and underscores only.'; return; }
  if (pass.length < 4) { $('register-error').textContent = 'Password must be at least 4 characters.'; return; }
  $('register-btn').disabled = true; $('register-btn').textContent = 'Creating...';
  try {
    const existing = await db.collection('users').doc(username).get();
    if (existing.exists) {
      $('register-error').textContent = 'That username is already taken.';
      $('register-btn').disabled = false; $('register-btn').textContent = 'Continue'; return;
    }
    const color = AVATAR_COLORS[Math.floor(Math.random() * AVATAR_COLORS.length)];
    const data = {
      username, password: pass, avatarColor: color, status: 'online',
      premiumUntil: null, theme: 'dark', op: false,
      orbs: STARTING_ORBS,
      stats: { messagesSent: 0, reactionsGiven: 0, dmsStarted: 0, serversCount: 0 },
      questsDate: todayStr(),
      dailyStats: { messagesSent: 0, reactionsGiven: 0, dmsMessaged: 0, channelsMessaged: 0 },
      claimedQuestsToday: [],
      bio: '', pronouns: '', bannerColor: color,
      friends: [], incomingRequests: [], outgoingRequests: [],
      banned: false, banReason: '', bannedUntil: null,
      createdAt: FieldValue.serverTimestamp(),
    };
    await db.collection('users').doc(username).set(data);
    myUid = username; myProfile = data; profileCache[myUid] = data;
    setSession(username);
    enterApp();
  } catch (e) {
    $('register-error').textContent = e.message || 'Something went wrong.';
  }
  $('register-btn').disabled = false; $('register-btn').textContent = 'Continue';
};

$('logout-btn').onclick = async () => {
  setMobileTab('home');
  ovReset();
  musicStop();
  ggRaccoonSeen = null;
  teardownPresence();
  try { if (myUid) await db.collection('users').doc(myUid).update({ status: 'offline' }); } catch (e) {}
  clearMyTypingDoc();
  cleanupAllListeners();
  setSession(null);
  stopGameEngines();
  myUid = null; myProfile = null; profileCache = {}; isAdmin = false; isOwner = false; sfMode = false; ephemeralMsgs = []; seedBotProfiles();
  applyAdminVisibility();
  currentServerId = null; currentServerData = null; currentChannelId = null;
  currentDMId = null; currentDMOtherUid = null; currentView = 'none';
  document.body.className = '';
  closeModal('settings-modal');
  showAuthScreen();
};

function cleanupAllListeners() {
  if (unsub.servers) unsub.servers();
  if (unsub.channels) unsub.channels();
  if (unsub.categories) unsub.categories();
  if (unsub.messages) unsub.messages();
  if (unsub.dms) unsub.dms();
  if (unsub.groupDms) unsub.groupDms();
  if (unsub.self) unsub.self();
  if (unsub.typing) unsub.typing();
  unsub = { servers: null, channels: null, categories: null, messages: null, dms: null, groupDms: null, self: null, typing: null };
}

// ============================================================
// ACCOUNT TERMINATION
// An admin's Delete Account (mode 'real') or the owner's Fake Delete
// (mode 'fake') writes a `terminated` flag onto the target's user doc
// instead of deleting it. The target's own client sees the flag, plays the
// skull sequence, then either deletes its own doc (real) or just clears the
// flag (fake) and signs out. Because the flag stays on the doc, someone who
// is offline gets the sequence the next time they sign in.
// ============================================================
let terminationActive = false;
const TERM_FAKE_MAX_AGE = 30 * 60 * 1000;   // an unseen fake delete expires instead of ambushing someone days later

// The skull sprite (background already cut out). Each frame is a glitched
// copy of it: torn bands, flickering brightness and dropped pixels.
const TERM_SKULL_SRC = 'data:image/png;base64,';
let termSkullPromise = null;
function loadTerminationSkull() {
  if (!termSkullPromise) termSkullPromise = new Promise(res => {
    const img = new Image();
    img.onload = () => res(img);
    img.onerror = () => res(null);
    img.src = TERM_SKULL_SRC;
  });
  return Promise.race([termSkullPromise, new Promise(res => setTimeout(() => res(null), 2500))]);
}

function buildTerminationSkullFrames(img, count) {
  const W = img ? img.naturalWidth : 8, H = img ? img.naturalHeight : 8;
  const base = document.createElement('canvas'); base.width = W; base.height = H;
  const b = base.getContext('2d', { willReadFrequently: true });
  if (img) b.drawImage(img, 0, 0);
  const src = b.getImageData(0, 0, W, H).data;
  const frames = [];
  for (let f = 0; f < count; f++) {
    const c = document.createElement('canvas'); c.width = W; c.height = H;
    const x = c.getContext('2d'), out = x.createImageData(W, H), d = out.data;
    const shift = new Int16Array(H);
    const bands = 3 + Math.floor(Math.random() * 6);
    for (let k = 0; k < bands; k++) {
      const y0 = Math.floor(Math.random() * H), len = 1 + Math.floor(Math.random() * H * 0.045), dx = Math.round((Math.random() - 0.5) * W * 0.16);
      for (let y = y0; y < Math.min(H, y0 + len); y++) shift[y] = dx;
    }
    const hot = Math.floor(Math.random() * H);                       // one over-bright scanline per frame
    for (let y = 0; y < H; y++) {
      for (let px = 0; px < W; px++) {
        let sx = px - shift[y]; if (sx < 0 || sx >= W) sx = px;
        const si = (y * W + sx) * 4, i = (y * W + px) * 4, n = Math.random();
        const a = src[si + 3];
        if (a > 0) {
          if (a > 200 && n < 0.035) continue;                          // dropped pixel
          const k = (0.82 + n * 0.36) * (Math.abs(y - hot) < 2 ? 1.45 : 1);
          d[i] = Math.min(255, src[si] * k); d[i + 1] = Math.min(255, src[si + 1] * k); d[i + 2] = Math.min(255, src[si + 2] * k); d[i + 3] = a;
        } else if (n < 0.004) {
          d[i] = 170; d[i + 1] = 10; d[i + 2] = 10; d[i + 3] = 255;     // stray specks around it
        }
      }
    }
    x.putImageData(out, 0, 0);
    frames.push(c);
  }
  return { frames, W, H };
}

function terminationSound() {
  let ctx = null;
  try { ctx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { return { thump() {}, scream() {}, close() {} }; }
  const noiseBuf = (() => { const b = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate), a = b.getChannelData(0); for (let i = 0; i < a.length; i++) a[i] = Math.random() * 2 - 1; return b; })();
  const safe = fn => (...a) => { try { fn(...a); } catch (e) {} };
  return {
    thump: safe(level => {
      const t = ctx.currentTime, o = ctx.createOscillator(), g = ctx.createGain();
      o.type = 'sine'; o.frequency.setValueAtTime(95, t); o.frequency.exponentialRampToValueAtTime(28, t + 0.5);
      g.gain.setValueAtTime(0.25 + level * 0.6, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.55);
      o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + 0.6);
      const n = ctx.createBufferSource(), ng = ctx.createGain(), lp = ctx.createBiquadFilter();
      n.buffer = noiseBuf; lp.type = 'lowpass'; lp.frequency.value = 400 + level * 1800;
      ng.gain.setValueAtTime(0.05 + level * 0.25, t); ng.gain.exponentialRampToValueAtTime(0.001, t + 0.25);
      n.connect(lp).connect(ng).connect(ctx.destination); n.start(t); n.stop(t + 0.3);
    }),
    scream: safe(() => {
      const t = ctx.currentTime, n = ctx.createBufferSource(), g = ctx.createGain(), o = ctx.createOscillator(), og = ctx.createGain();
      n.buffer = noiseBuf; g.gain.setValueAtTime(0.7, t); g.gain.exponentialRampToValueAtTime(0.001, t + 1.4);
      n.connect(g).connect(ctx.destination); n.start(t); n.stop(t + 1.5);
      o.type = 'sawtooth'; o.frequency.setValueAtTime(220, t); o.frequency.exponentialRampToValueAtTime(34, t + 1.6);
      og.gain.setValueAtTime(0.3, t); og.gain.exponentialRampToValueAtTime(0.001, t + 1.7);
      o.connect(og).connect(ctx.destination); o.start(t); o.stop(t + 1.8);
    }),
    close: safe(() => { setTimeout(() => { try { ctx.close(); } catch (e) {} }, 2500); }),
  };
}

async function startTermination(info) {
  if (terminationActive) return;
  terminationActive = true;
  musicStop();
  const mode = info && info.mode === 'fake' ? 'fake' : 'real';
  const uid = myUid;
  const calm = !shakeAllowed();                       // Settings > Accessibility > Reduce screen shake (or the browser's reduce-motion setting, or Epilepsy mode)
  const epi = epilepsyMode();                         // Epilepsy mode: no red flashes, no static, no glitching skull

  // Nothing else should be clickable or typeable while this plays.
  document.querySelectorAll('.modal-overlay').forEach(el => el.classList.add('hidden'));
  try { stopGameEngines(); } catch (e) {}
  if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
  const blockKeys = e => { e.preventDefault(); e.stopImmediatePropagation(); };
  const KEY_EVENTS = ['keydown', 'keypress', 'keyup', 'contextmenu'];
  KEY_EVENTS.forEach(t => window.addEventListener(t, blockKeys, true));

  const old = $('terminate-screen'); if (old) old.remove();
  const el = document.createElement('div');
  el.id = 'terminate-screen';
  el.setAttribute('role', 'alert');
  el.innerHTML = `
    <div class="term-stage"><canvas class="term-skull" width="8" height="8"></canvas></div>
    <div class="term-static"></div><div class="term-scan"></div><div class="term-vignette"></div>
    <div class="term-flash"></div>
    <div class="term-end hidden"><div class="term-wall" aria-hidden="true"></div><div class="term-title" data-text="Account Terminated">Account Terminated</div></div>`;
  document.body.append(el);
  const stage = el.querySelector('.term-stage'), cv = el.querySelector('.term-skull'), cx = cv.getContext('2d');
  const flash = el.querySelector('.term-flash'), endBox = el.querySelector('.term-end');
  const sfx = terminationSound();
  el.querySelector('.term-wall').textContent = 'ACCOUNT TERMINATED   '.repeat(4500);
  const { frames, W: SW, H: SH } = buildTerminationSkullFrames(await loadTerminationSkull(), 7);
  cv.width = SW; cv.height = SH;

  // [ms, progress] -- each entry is a lurch closer; between lurches it creeps.
  const STEPS = [[0, 0], [1500, 0.13], [3000, 0.23], [4300, 0.33], [5400, 0.45], [6400, 0.57], [7200, 0.69], [7850, 0.8], [8400, 0.9], [8850, 1.28]];
  const CUT = 9350, HOLD = 4300, FADE = 700;
  const sizeAt = p => 0.1 * Math.pow(45, Math.min(p, 1.3));    // small speck -> filling the screen -> through the eyes
  let stepIdx = 0, cur = 0, last = performance.now(), shakeAt = -9999, shakeAmp = 0, frameAt = 0, frameI = 0;
  const t0 = last;
  let finished = false, cut = false, raf = 0;

  function targetP(t) {
    let i = STEPS.length - 1;
    while (i > 0 && STEPS[i][0] > t) i--;
    if (i >= STEPS.length - 1) return STEPS[STEPS.length - 1][1];
    const [ta, pa] = STEPS[i], [tb, pb] = STEPS[i + 1];
    return pa + (pb - pa) * 0.16 * Math.min(1, (t - ta) / (tb - ta));
  }

  function showEnd() {
    cut = true;
    cancelAnimationFrame(raf);
    stage.style.display = 'none';
    el.classList.add('is-end');
    endBox.classList.remove('hidden');
    if (!epi) { flash.style.opacity = 1; flash.style.transition = 'opacity .6s ease-out'; requestAnimationFrame(() => { flash.style.opacity = 0; }); }
    sfx.scream();
    if (!calm && navigator.vibrate) try { navigator.vibrate([120, 60, 220]); } catch (e) {}
  }

  async function finish() {
    if (finished) return;
    finished = true;
    cancelAnimationFrame(raf);
    el.classList.add('is-black');
    try {
      if (mode === 'real') await db.collection('users').doc(uid).delete();
      else await db.collection('users').doc(uid).update({ terminated: FieldValue.delete() });
    } catch (e) { console.warn('termination write failed', e); }
    try { await $('logout-btn').onclick(); } catch (e) {}
    KEY_EVENTS.forEach(t => window.removeEventListener(t, blockKeys, true));
    sfx.close();
    terminationActive = false;
    el.classList.add('is-out');
    setTimeout(() => el.remove(), 900);
  }

  function frame(now) {
    const t = now - t0, dt = Math.min(0.1, (now - last) / 1000); last = now;
    if (t >= CUT) { showEnd(); setTimeout(() => el.classList.add('is-fading'), HOLD); setTimeout(finish, HOLD + FADE); return; }
    while (stepIdx < STEPS.length - 1 && t >= STEPS[stepIdx + 1][0]) {
      stepIdx++;
      const p = STEPS[stepIdx][1];
      shakeAt = t; shakeAmp = 5 + Math.min(p, 1) * 26;
      sfx.thump(Math.min(p, 1));
      if (!calm && !epi) { flash.style.transition = 'none'; flash.style.opacity = 0.22 + Math.min(p, 1) * 0.3; requestAnimationFrame(() => { flash.style.transition = 'opacity .35s ease-out'; flash.style.opacity = 0; }); }
      if (!calm && navigator.vibrate) try { navigator.vibrate(30 + Math.round(p * 80)); } catch (e) {}
    }
    cur += (targetP(t) - cur) * (1 - Math.exp(-dt * 13));
    const fadeIn = Math.min(1, t / 1100);
    const decay = Math.exp(-(t - shakeAt) / 260);
    const sx = calm ? 0 : (Math.random() - 0.5) * 2 * shakeAmp * decay + (Math.random() - 0.5) * (1 + cur * 5);
    const sy = calm ? 0 : (Math.random() - 0.5) * 2 * shakeAmp * decay + (Math.random() - 0.5) * (1 + cur * 5);
    stage.style.transform = `translate(${sx}px, ${sy}px)`;
    cv.style.transform = `translateY(10%) scale(${sizeAt(cur)})`;
    cv.style.opacity = fadeIn * (0.55 + Math.min(cur, 1) * 0.45);
    el.style.setProperty('--term-p', Math.min(cur, 1).toFixed(3));
    if (!epi && now - frameAt > (calm ? 220 : 70)) {   // Epilepsy mode keeps the first, clean frame of the skull
      frameAt = now; frameI = (frameI + 1 + Math.floor(Math.random() * 3)) % frames.length;
      cx.clearRect(0, 0, SW, SH); cx.drawImage(frames[frameI], 0, 0);
    }
    raf = requestAnimationFrame(frame);
  }
  cx.drawImage(frames[0], 0, 0);
  raf = requestAnimationFrame(frame);
  // If the tab is in the background, animation frames stop; this still gets the account handled.
  setTimeout(() => { if (!finished) { if (!cut) showEnd(); finish(); } }, CUT + HOLD + FADE + 6000);
}

// ============================================================
// APP INIT
// ============================================================
function initAppForUser() {
  initPresence();
  unsub.self = db.collection('users').doc(myUid).onSnapshot(snap => {
    if (!snap.exists) return;
    myProfile = snap.data();
    profileCache[myUid] = myProfile;
    if (OVERLAY_WINDOW) {
      // Only what the overlay shows. Bans, account deletion, redirects, music and games are the main window's job.
      staffFlagsFromProfile(myProfile);
      applyTheme(myProfile.theme || 'default');
      applyShopTheme(myProfile.equippedTheme);
      ovRenderBindSetting();
      if (banStatus(myProfile).banned || myProfile.terminated) ovClose();
      return;
    }
    if (terminationActive) return;
    if (myProfile.terminated) {
      const tm = myProfile.terminated;
      if (tm.mode === 'fake' && tm.at && Date.now() - tm.at > TERM_FAKE_MAX_AGE) {
        db.collection('users').doc(myUid).update({ terminated: FieldValue.delete() }).catch(() => {});   // stale fake, never seen: drop it
      } else { startTermination(tm); return; }
    }
    syncGameState(myProfile);
    maybeShowAppPrompt();
    const liveBan = banStatus(myProfile);
    if (liveBan.banned) showBanScreen(liveBan, true);   // banned while signed in
    applyShopTheme(myProfile.equippedTheme);
    syncShakeFromProfile(myProfile);
    syncEpilepsyFromProfile(myProfile);
    syncLiquidGlassFromProfile(myProfile);
    musicSync(myProfile.equippedMusic || null);
    activityRefresh();   // Settings > Activity Status may have changed
    // Admin-triggered redirect: fires once per nonce, then best-effort
    // clears the field so a later reconnect doesn't replay it.
    if (myProfile.redirectUrl && myProfile.redirectNonce && myProfile.redirectNonce !== lastHandledRedirectNonce) {
      lastHandledRedirectNonce = myProfile.redirectNonce;
      const target = myProfile.redirectUrl;
      db.collection('users').doc(myUid).update({ redirectUrl: FieldValue.delete(), redirectNonce: FieldValue.delete() }).catch(() => {});
      // Only ever a web address: a javascript: "address" here would run code inside this page.
      if (typeof target === 'string' && /^https?:\/\//i.test(target.trim())) { window.location.href = target.trim(); return; }
    }
    const sfWas = sfMode;
    staffFlagsFromProfile(myProfile);
    applyAdminVisibility();
    if (sfWas !== sfMode && typeof renderCurrentView === 'function' && (currentView === 'channel' || currentView === 'dm' || currentView === 'groupdm')) { profileCache[myUid] = myProfile; renderCurrentView(); }
    applyTheme(myProfile.theme || 'default');
    applyCustomKeyboardSetting();
    ovRenderBindSetting();
    ggOnProfileUpdate();
    renderSelfPanel();
    renderHomeActivity();
    updateFriendReqBadge();
    if (!$('settings-modal').classList.contains('hidden')) populateSettings();
    if (currentView === 'friends') renderFriendsView();
    if (currentView === 'quests') renderQuests();
    renderCurrentView();
  });

  unsub.servers = db.collection('servers').where('members', 'array-contains', myUid).onSnapshot(snap => {
    const servers = [];
    snap.forEach(d => servers.push({ id: d.id, ...d.data() }));
    window.__myServers = servers;
    if (typeof ovOnServersChanged === 'function') ovOnServersChanged();
    renderServerRail(servers);
    if (currentServerId) {
      const cur = servers.find(s => s.id === currentServerId);
      if (cur) {
        const prev = currentServerData;
        currentServerData = cur;
        $('side-header-title').textContent = cur.name;
        // Role/permission changes (or a rename) should take effect live
        // for anyone currently looking at this server, not just after
        // they navigate away and back — both of these read straight from
        // currentServerData on every render.
        renderChannelRows(lastChannelsList);
        if (currentView === 'channel') {
          renderMemberPanel(cur.members || [], cur.ownerId, cur);
          const ch = currentChannelObj();
          if (ch && !canViewChannel(ch, cur, myUid)) {
            toast('You no longer have access to that channel.');
            if (unsub.messages) { unsub.messages(); unsub.messages = null; }
            currentChannelId = null; currentView = 'none';
            showWelcome(); setMobilePane('list');
          } else {
            refreshChannelComposerState();
            if (prev && JSON.stringify(prev.nicknames || {}) !== JSON.stringify(cur.nicknames || {})) renderMessages(lastRawMessages);
          }
        }
      } else if (servers.length || !snap.metadata.fromCache) {
        // Kicked, banned, or the server was deleted while you had it open.
        if (leavingServerId !== currentServerId) toast('You are no longer a member of that server.');
        showHomeView();
      }
    }
  }, err => console.error(err));

  subscribeDMList();
  subscribeCustomEmojis();
  subscribeCustomDecorations();
  subscribeCustomThemes();
  subscribeCustomNameplates();
  subscribeCustomBanners();
  subscribeCustomProfileEffects();
  subscribeCustomProfileFrames();
  subscribeShopOverrides();
  subscribeCustomMusic();
  subscribeMessageFilter();
  subscribeStickers();
  showHomeView();
  handleInviteFromUrl();
}

let systemThemeListenerAdded = false;
function applyTheme(themeKey) {
  const key = THEMES.some(theme => theme.key === themeKey) ? themeKey : 'dark';
  document.body.classList.remove('theme-light', 'theme-ash', 'theme-onyx');
  document.body.dataset.theme = key;
  if (key === 'sync') {
    const wantsLight = window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches;
    if (wantsLight) document.body.classList.add('theme-light');
    document.documentElement.style.colorScheme = wantsLight ? 'light' : 'dark';
    if (!systemThemeListenerAdded && window.matchMedia) {
      systemThemeListenerAdded = true;
      window.matchMedia('(prefers-color-scheme: light)').addEventListener('change', () => {
        if (myProfile && myProfile.theme === 'sync') applyTheme('sync');
      });
    }
    return;
  }
  document.documentElement.style.colorScheme = key === 'light' ? 'light' : 'dark';
  if (key !== 'dark') document.body.classList.add('theme-' + key);
}

function renderSelfPanel() {
  if (!myProfile) return;
  const inner = avatarHTML(32, myProfile.avatarColor, initials(myProfile.username), computeDisplayStatus(myUid), myProfile.avatarUrl, myProfile.equippedDecoration, myUid, myProfile.equippedMask);
  $('self-avatar').outerHTML = inner.replace('class="avatar', 'id="self-avatar" class="avatar');
  $('self-username').innerHTML = esc(displayNameOf(myProfile)) + premiumStar(myProfile) + roleTag(myProfile);
  const st = STATUSES.find(s => s.key === computeDisplayStatus(myUid));
  const myAct = computeMyActivity();
  $('self-status-label').textContent = myAct ? activityLine(myAct) : (st ? st.label : 'Online') + (st && st.key !== 'offline' ? (isOnMobile(myUid) ? ' · Mobile' : DESKTOP ? ' · App' : '') : '');
  updateMobileUserPill();
}

// ============================================================
// SERVER RAIL
// ============================================================
function renderServerRail(servers) {
  const list = $('server-rail-list');
  list.innerHTML = '';
  servers.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
  servers.forEach(s => {
    const el = document.createElement('div');
    el.className = 'rail-item' + (currentServerId === s.id ? ' active' : '');
    el.title = s.name;
    el.dataset.id = s.id;
    el.textContent = serverInitials(s.name);
    el.onclick = () => selectServer(s);
    list.appendChild(el);
  });
}

$('rail-home').onclick = () => showHomeView();
$('rail-add-server').onclick = () => openModal('server-choice-modal');

$('choice-create').onclick = () => { closeModal('server-choice-modal'); openModal('create-server-modal'); };
$('choice-join').onclick = () => { closeModal('server-choice-modal'); openModal('join-server-modal'); };

$('confirm-create-server').onclick = async () => {
  const name = $('new-server-name').value.trim();
  const code = $('new-server-code').value.trim().toLowerCase();
  $('create-server-error').textContent = '';
  if (!name) { $('create-server-error').textContent = 'Please enter a server name.'; return; }
  if (!/^[a-z0-9]{5}$/.test(code)) { $('create-server-error').textContent = 'The invite code must be exactly 5 letters or numbers.'; return; }
  try {
    if (await findServerByInvite(code)) { $('create-server-error').textContent = `The code "${code}" is already taken. Pick another one.`; return; }
    const ref = await db.collection('servers').add({
      name, ownerId: myUid, members: [myUid], inviteCode: code, createdAt: FieldValue.serverTimestamp(),
      roles: [{ id: 'everyone', name: '@everyone', color: null, permissions: DEFAULT_EVERYONE_PERMISSIONS.slice(), position: 0, permsV2: true }],
      memberRoles: {}, bannedUsers: [],
    });
    await ref.collection('channels').add({ name: 'general', categoryId: null, autoDelete: true, createdAt: FieldValue.serverTimestamp() });
    $('new-server-name').value = ''; $('new-server-code').value = ''; updateNewServerCodePreview();
    closeModal('create-server-modal');
    toast('Server created.');
    db.collection('users').doc(myUid).update({ 'stats.serversCount': FieldValue.increment(1) }).catch(() => {});
  } catch (e) { $('create-server-error').textContent = e.message; }
};

// Invite links look like https://equilibrium-incarnate.pages.dev/abc12 (new servers use a
// 5-character code; older servers keep their 6-character one). Older ?invite= links still work.
const INVITE_BASE = 'https://equilibrium-incarnate.pages.dev/';
const INVITE_CODE_RE = /^[a-z0-9]{5,6}$/i;
$('new-server-code').addEventListener('input', () => {
  const el = $('new-server-code');
  el.value = el.value.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 5);
  updateNewServerCodePreview();
});
function updateNewServerCodePreview() {
  $('new-server-code-preview').textContent = INVITE_BASE.replace('https://', '') + ($('new-server-code').value || '·····');
}

function parseInviteCode(input) {
  const v = (input || '').trim();
  const m = /[?&#]invite=([a-z0-9]+)/i.exec(v) || /\/invite\/([a-z0-9]+)/i.exec(v)
    || /^(?:https?:\/\/)?[^\/\s]+\/([a-z0-9]{5,6})\/?(?:[?#].*)?$/i.exec(v);
  return (m ? m[1] : v).toLowerCase();
}
function inviteLinkFor(code) { return INVITE_BASE + encodeURIComponent(code); }
// The invite code in the address bar, if the page was opened from an invite link.
function inviteCodeFromLocation() {
  const q = new URLSearchParams(location.search).get('invite');
  if (q) return q;
  const seg = location.pathname.replace(/^\/+|\/+$/g, '');
  return INVITE_CODE_RE.test(seg) ? seg : null;
}
async function findServerByInvite(code) {
  const q = await db.collection('servers').where('inviteCode', '==', code).limit(1).get();
  return q.empty ? null : q.docs[0];
}
async function joinServerDoc(doc) {
  const data = doc.data();
  if ((data.bannedUsers || []).includes(myUid)) throw new Error('You are banned from this server.');
  if (!(data.members || []).includes(myUid)) {
    await doc.ref.update({ members: FieldValue.arrayUnion(myUid) });
    db.collection('users').doc(myUid).update({ 'stats.serversCount': FieldValue.increment(1) }).catch(() => {});
    postServerJoinMessage(doc.id);
  }
  selectServer({ id: doc.id, ...data });
}

$('confirm-join-server').onclick = async () => {
  const code = parseInviteCode($('join-server-code').value);
  $('join-server-error').textContent = '';
  if (!code) { $('join-server-error').textContent = 'Please enter an invite code or link.'; return; }
  try {
    const doc = await findServerByInvite(code);
    if (!doc) { $('join-server-error').textContent = 'This invite is invalid or has expired.'; return; }
    await joinServerDoc(doc);
    $('join-server-code').value = '';
    closeModal('join-server-modal');
    toast('Joined server.');
  } catch (e) { $('join-server-error').textContent = e.message; }
};

let pendingInviteDoc = null;
async function openInvitePreview(code) {
  $('invite-error').textContent = '';
  try {
    const doc = await findServerByInvite(code);
    if (!doc) { toast('That invite link is invalid or has expired.', 'error'); return; }
    const data = doc.data();
    if ((data.members || []).includes(myUid)) { selectServer({ id: doc.id, ...data }); return; }
    pendingInviteDoc = doc;
    $('invite-icon').textContent = initials(data.name);
    $('invite-name').textContent = data.name;
    $('invite-desc').textContent = data.description || '';
    const n = (data.members || []).length;
    $('invite-meta').textContent = `${n} ${n === 1 ? 'Member' : 'Members'}`;
    openModal('invite-preview-modal');
  } catch (e) { toast(e.message || 'Could not load that invite.', 'error'); }
}
$('invite-accept-btn').onclick = async () => {
  if (!pendingInviteDoc) return;
  try {
    await joinServerDoc(pendingInviteDoc);
    closeModal('invite-preview-modal');
    toast('Joined server.');
    pendingInviteDoc = null;
  } catch (e) { $('invite-error').textContent = e.message; }
};
function handleInviteFromUrl() {
  const code = inviteCodeFromLocation();
  if (!code) return;
  const url = new URL(location.href);
  url.searchParams.delete('invite');
  if (INVITE_CODE_RE.test(url.pathname.replace(/^\/+|\/+$/g, ''))) url.pathname = '/';
  history.replaceState(null, '', url.pathname + url.search + url.hash);
  openInvitePreview(parseInviteCode(code));
}
// Invite links clicked inside chat open the preview instead of reloading the app.
document.addEventListener('click', (e) => {
  const a = e.target.closest && e.target.closest('a[href]');
  if (!a || !myUid) return;
  let url;
  try { url = new URL(a.href); } catch (_) { return; }
  const viaQuery = url.origin === location.origin && url.searchParams.get('invite');
  const inviteHost = url.origin === INVITE_BASE.replace(/\/$/, '');
  const viaPath = (inviteHost || url.origin === location.origin) && INVITE_CODE_RE.test(url.pathname.replace(/^\/+|\/+$/g, ''));
  if (!viaQuery && !viaPath) return;
  e.preventDefault();
  openInvitePreview(parseInviteCode(viaQuery || url.pathname));
});

// ============================================================
// MOBILE (phone-width) LAYOUT
// A phone screen shows one pane at a time: the server rail is always
// visible; the channel/DM list and the chat area slide in and out via
// a class on #app, driven by whichever navigation function is active.
// ============================================================
// Keep this in sync with the phone-layout breakpoint in style.css: short
// side of the screen (whichever axis rotation makes narrow) under 600px,
// scoped to touch devices so it doesn't also catch a small desktop window.
function isMobile() {
  const narrow = Math.min(window.innerWidth, window.innerHeight) <= 600;
  const touchMedia = window.matchMedia('(hover: none) and (pointer: coarse)').matches;
  return narrow && (touchMedia || isMobileDevice());
}
// Mirror the detection onto <body> so CSS can key off a real device check
// (body.is-mobile / body.is-touch) instead of only viewport width.
function syncDeviceClasses() {
  document.body.classList.toggle('is-mobile', isMobile());
  document.body.classList.toggle('is-touch', isTouchDevice() || isMobileDevice());
}
syncDeviceClasses();
window.addEventListener('resize', syncDeviceClasses);
window.addEventListener('orientationchange', syncDeviceClasses);
// Touch device of ANY size — phone or tablet (iPad included). Used only
// for the on-screen-keyboard docking fix below, which a tablet needs just
// as much as a phone does. isMobile() above stays phone-only on purpose:
// an iPad should still get the roomy desktop-style layout (grid columns,
// title bar, etc.), just with the keyboard handled correctly.
function isTouchDevice() {
  return window.matchMedia('(hover: none) and (pointer: coarse)').matches;
}
function setMobilePane(pane) {
  $('app').classList.toggle('mobile-show-chat', pane === 'chat');
  // Anything the keyboard floated over the chat (quick text, the keyboard itself)
  // has no business staying on screen once the chat slides away.
  closeCkQuickTextPopover();
  if (pane === 'list') {
    hideCustomKeyboard();
    // Going back to the list (back button, swipe, or leaving a chat) also puts away everything that was open
    // on top of that chat: the member list overlay, the pickers, the + menu and reaction pop-ups. Before, the
    // member list stayed on screen over the DM list after a swipe.
    if (isMobile()) closeMemberPanel(true);
    try { closeEmojiPickerPanel(); } catch (e) {}
    ['sticker-picker-panel', 'gif-picker-panel', 'composer-action-menu'].forEach(id => { const el = $(id); if (el) el.classList.add('hidden'); });
    try { closeReactPopover(); } catch (e) {}
  }
}
// Closes the full-screen member list on a phone. It slides off to the right (from wherever a swipe left it).
function closeMemberPanel(animated) {
  const app = $('app'), panel = $('member-panel');
  if (isMobile()) memberListManualOverride = null;   // on a phone the list is never reopened on its own
  if (!app.classList.contains('member-list-open')) return;
  const done = () => { app.classList.remove('member-list-open'); panel.style.transition = ''; panel.style.transform = ''; panel.classList.remove('is-closing'); };
  if (!animated || !isMobile() || window.matchMedia('(prefers-reduced-motion: reduce)').matches) { done(); return; }
  panel.classList.add('is-closing');
  panel.style.transition = 'transform .23s cubic-bezier(.4,0,.8,.4)';
  panel.style.transform = 'translateX(100%)';
  setTimeout(done, 240);
}
// Applied whenever a channel or group DM is opened. Respects a manual
// toggle made earlier this session; otherwise defaults to open, but never
// auto-opens on mobile (there it's a full-screen overlay, not a column).
function applyDefaultMemberListState() {
  const open = isMobile() ? false : (memberListManualOverride !== null ? memberListManualOverride : true);   // a phone never opens it by itself
  $('app').classList.toggle('member-list-open', open);
}
$('back-to-list-btn').onclick = () => setMobilePane('list');

// On iOS and some Android webviews, the layout viewport keeps its original
// height while the software keyboard overlays the page. Use the visual
// viewport when it is available so the flex layout ends at the keyboard.
//
// That alone isn't quite enough on iOS: focusing a field pans the visual
// viewport up rather than resizing the layout viewport in place, so even
// with the height corrected, the page can still be scrolled such that the
// bottom of our now-shorter layout sits above the keyboard instead of
// right on top of it — a gap the size of that pan. Shifting #app up by
// visualViewport.offsetTop cancels that out so the composer actually
// docks against the keyboard instead of floating above it. This runs for
// any touch device (phone or tablet), not just phones, so an iPad's
// keyboard docks the same way — it just keeps its own desktop-style
// layout otherwise, since isMobile() (unlike isTouchDevice()) is unchanged.
//
// Cross-browser notes, since this API is handled a bit differently
// everywhere:
// - iOS: every browser (Safari, Chrome, Firefox, Edge, in-app browsers)
//   is required by Apple to use Safari's WebKit engine under the hood, so
//   whatever works in Safari here works identically in all of them.
// - Android Chrome/Edge/Samsung Internet (Chromium): the
//   interactive-widget=resizes-content viewport meta tag in index.html
//   asks the browser to resize the actual layout viewport for the
//   keyboard, which — where it's honored — makes visualViewport.height
//   equal window.innerHeight and offsetTop naturally 0, so the code below
//   just becomes a no-op confirming what the browser already did right.
// - Android Firefox and anything else without visualViewport support:
//   falls back to window.innerHeight, which has reflected the on-screen
//   keyboard via the resize event since long before visualViewport
//   existed, so height-tracking still works even if the offsetTop
//   compensation (an iOS-specific quirk) never applies.
function syncMobileViewport() {
  const root = document.documentElement;
  const appEl = $('app');
  if (appEl) appEl.style.transform = '';
  if (!isTouchDevice()) {
    root.style.removeProperty('--mobile-viewport-height');
    document.body.style.transform = '';
    return;
  }
  const vv = window.visualViewport;
  const visibleHeight = vv ? vv.height : window.innerHeight;
  root.style.setProperty('--mobile-viewport-height', `${Math.round(visibleHeight)}px`);
  // Shift <body> itself (not #app inside it). Body has overflow:hidden and
  // is only visibleHeight tall, so translating a CHILD of body pushed the
  // composer and newest messages outside body's clip box — that's why the
  // DM went blank and the text box vanished while the iOS keyboard was up.
  document.body.style.transform = (vv && vv.offsetTop > 0) ? `translateY(${Math.round(vv.offsetTop)}px)` : '';
  document.body.classList.toggle('keyboard-open', !!vv && (window.innerHeight - vv.height) > 120);
}
// Keep the newest messages in view when the keyboard (or anything else)
// shrinks the message list: preserve the distance from the bottom instead
// of the distance from the top.
(function keepMessagesAnchored() {
  const wrap = $('messages');
  if (!wrap || typeof ResizeObserver === 'undefined') return;
  let distFromBottom = 0;
  wrap.addEventListener('scroll', () => {
    distFromBottom = wrap.scrollHeight - wrap.scrollTop - wrap.clientHeight;
  }, { passive: true });
  new ResizeObserver(() => {
    wrap.scrollTop = wrap.scrollHeight - wrap.clientHeight - (distFromBottom < 80 ? 0 : distFromBottom);
  }).observe(wrap);
})();
window.addEventListener('resize', syncMobileViewport);
if (window.visualViewport) {
  window.visualViewport.addEventListener('resize', syncMobileViewport);
  window.visualViewport.addEventListener('scroll', syncMobileViewport);
}
// Belt-and-suspenders for browsers/webviews that fire the events above
// late, or not at all, relative to the keyboard's own show/hide animation:
// re-check shortly after any text field gains or loses focus too. Two
// delays cover both a fast keyboard and a slower ~250-300ms animation.
document.addEventListener('focusin', (e) => {
  if (e.target.matches && e.target.matches('input, textarea')) {
    setTimeout(syncMobileViewport, 60);
    setTimeout(syncMobileViewport, 350);
  }
});
document.addEventListener('focusout', (e) => {
  if (e.target.matches && e.target.matches('input, textarea')) {
    setTimeout(syncMobileViewport, 60);
    setTimeout(syncMobileViewport, 350);
  }
});
syncMobileViewport();

// ---- block browser/OS zoom (pinch, ctrl+scroll, ctrl+plus/minus) ----
// The viewport meta tag + touch-action:pan-x pan-y in CSS handle most of
// this already; the listeners below catch the cases those two can't:
// trackpad/ctrl+wheel zoom and Safari's gesture events on desktop.
window.addEventListener('wheel', (e) => {
  if (e.ctrlKey) e.preventDefault();
}, { passive: false });
['gesturestart', 'gesturechange', 'gestureend'].forEach((evt) => {
  document.addEventListener(evt, (e) => e.preventDefault());
});
document.addEventListener('keydown', (e) => {
  if ((e.ctrlKey || e.metaKey) && ['=', '+', '-', '_', '0'].includes(e.key)) {
    e.preventDefault();
  }
});

// ---- swipe to open/close, DMs only (not servers) ----
// Right = close the open DM (back to the list). Left = reopen whatever
// DM/group/tab you last had open. Dragging follows your finger in real
// time; the CSS transition only takes back over once you lift your
// finger, same trick used for the tap-driven pane switches above.
(function setupDMSwipe() {
  const zone = $('page-body');
  let tracking = false, dragging = false, startX = 0, startY = 0, dx = 0;

  function eligible() {
    return isMobile() && !currentServerId && currentView !== 'none';
  }

  zone.addEventListener('touchstart', (e) => {
    if (e.touches.length !== 1 || !eligible()) { tracking = false; return; }
    if (e.target.closest('.modal-overlay:not(.hidden)') || e.target.closest('textarea, input') || e.target.closest('#member-panel')) { tracking = false; return; }   // the member list has its own swipe
    startX = e.touches[0].clientX;
    startY = e.touches[0].clientY;
    tracking = true;
    dragging = false;
    dx = 0;
  }, { passive: true });

  zone.addEventListener('touchmove', (e) => {
    if (!tracking) return;
    const x = e.touches[0].clientX, y = e.touches[0].clientY;
    dx = x - startX;
    const dy = y - startY;
    if (!dragging) {
      if (Math.abs(dx) < 12 && Math.abs(dy) < 12) return;
      if (Math.abs(dy) > Math.abs(dx)) { tracking = false; return; }
      dragging = true;
      $('app').classList.add('mobile-dragging');
    }
    const list = $('side-panel'), chat = $('main-col');
    const width = window.innerWidth;
    const showingChat = $('app').classList.contains('mobile-show-chat');
    if (showingChat) {
      const t = Math.max(0, Math.min(dx, width));
      chat.style.transform = `translateX(${t}px)`;
      list.style.transform = `translateX(${t - width}px)`;
    } else {
      const t = Math.min(0, Math.max(dx, -width));
      list.style.transform = `translateX(${t}px)`;
      chat.style.transform = `translateX(${t + width}px)`;
    }
    e.preventDefault();
  }, { passive: false });

  zone.addEventListener('touchend', () => {
    if (!dragging) { tracking = false; return; }
    tracking = false; dragging = false;
    const width = window.innerWidth;
    const showingChat = $('app').classList.contains('mobile-show-chat');
    const toChat = showingChat ? !(dx > width * 0.28) : (dx < -width * 0.28);
    $('app').classList.remove('mobile-dragging');
    requestAnimationFrame(() => {
      $('side-panel').style.transform = '';
      $('main-col').style.transform = '';
      setMobilePane(toChat ? 'chat' : 'list');
    });
  });
  zone.addEventListener('touchcancel', () => {
    if (!dragging) { tracking = false; return; }
    tracking = false; dragging = false;
    $('app').classList.remove('mobile-dragging');
    requestAnimationFrame(() => {
      $('side-panel').style.transform = '';
      $('main-col').style.transform = '';
    });
  });
})();

// ============================================================
// HOME VIEW (DMs)
// ============================================================
function hideMainPageViews() {
  $('friends-view').classList.add('hidden');
  $('quests-view').classList.add('hidden');
  $('codes-view').classList.add('hidden');
  $('shop-view').classList.add('hidden');
}

function showHomeView() {
  currentServerId = null; currentServerData = null; currentChannelId = null;
  currentView = 'none'; currentDMId = null; currentDMOtherUid = null; currentGroupDMId = null;
  if (unsub.channels) { unsub.channels(); unsub.channels = null; }
  if (unsub.categories) { unsub.categories(); unsub.categories = null; }
  if (unsub.messages) { unsub.messages(); unsub.messages = null; }
  if (unsub.typing) { unsub.typing(); unsub.typing = null; }
  clearMyTypingDoc();
  renderTypingIndicator([]);
  $('rail-home').classList.add('active');
  document.querySelectorAll('#server-rail-list .rail-item').forEach(e => e.classList.remove('active'));
  $('side-header-title').textContent = 'Direct Messages';
  $('side-header-chevron').classList.add('hidden');
  closeServerMenu();
  $('dm-list').classList.remove('hidden');
  $('channel-list').classList.add('hidden');
  $('members-toggle').classList.add('hidden');
  $('app').classList.remove('member-list-open');
  hideHeaderActions();
  document.querySelectorAll('.home-nav-item').forEach(i => i.classList.remove('active'));
  document.querySelector('.home-nav-item[data-home-view="friends"]').classList.add('active');
  openHomeMainView('friends');
  setMobilePane('list');
  renderDMRows();
}

function clearHomeNavActive() {
  document.querySelectorAll('.home-nav-item').forEach(i => i.classList.remove('active'));
}

document.querySelectorAll('.home-nav-item[data-home-view]').forEach(item => {
  item.onclick = () => {
    clearHomeNavActive();
    item.classList.add('active');
    // Deselect any DM row so only one thing in the sidebar is highlighted.
    document.querySelectorAll('#dm-rows .dm-row.active').forEach(r => r.classList.remove('active'));
    openHomeMainView(item.dataset.homeView);
  };
});

function openHomeMainView(which) {
  currentServerId = null; currentServerData = null; currentChannelId = null;
  currentDMId = null; currentDMOtherUid = null; currentGroupDMId = null;
  if (unsub.messages) { unsub.messages(); unsub.messages = null; }
  if (unsub.typing) { unsub.typing(); unsub.typing = null; }
  clearMyTypingDoc();
  renderTypingIndicator([]);
  $('welcome-view').classList.add('hidden');
  $('chat-view').classList.add('hidden');
  hideHeaderActions();
  hideMainPageViews();
  setChatHeaderHash('');
  if (which === 'friends') { currentView = 'friends'; $('chat-header-title').textContent = 'Friends'; $('friends-view').classList.remove('hidden'); renderFriendsView(); }
  else if (which === 'quests') { currentView = 'quests'; $('chat-header-title').textContent = 'Quests'; $('quests-view').classList.remove('hidden'); renderQuests(); }
  else if (which === 'codes') { currentView = 'codes'; $('chat-header-title').textContent = 'Codes'; $('codes-view').classList.remove('hidden'); }
  else if (which === 'shop') { currentView = 'shop'; $('chat-header-title').textContent = 'Shop'; $('shop-view').classList.remove('hidden'); openShop(); }
  setMobilePane('chat');
  renderDMRows();
}

// Tracks the last message timestamp we've already pinged for, per DM/group
// DM, so a conversation doc changing for some unrelated reason (a setting
// toggle, etc.) never replays a sound for a message already seen.
const conversationLastNotifiedAt = {};
function maybePingForConversationSnapshot(snap, isFirstSync, kind) {
  snap.forEach(d => {
    const data = d.data();
    const lm = data.lastMessage;
    if (!lm || !lm.username || lm.username === myUid) return;
    const millis = data.updatedAt && data.updatedAt.toMillis ? data.updatedAt.toMillis() : Date.now();
    const prev = conversationLastNotifiedAt[d.id];
    if (prev !== undefined && millis <= prev) return;
    conversationLastNotifiedAt[d.id] = millis;
    // Establish the baseline on first sync without retroactively pinging
    // for every DM/group that already existed when the app loaded.
    if (!isFirstSync && !isConversationMuted(kind, d.id)) playPingSound();
  });
}
function subscribeDMList() {
  let dmsFirstSync = true;
  if (unsub.dms) unsub.dms();
  unsub.dms = db.collection('dms').where('participants', 'array-contains', myUid).onSnapshot(async snap => {
    maybePingForConversationSnapshot(snap, dmsFirstSync, 'dm');
    dmsFirstSync = false;
    const dms = [];
    snap.forEach(d => dms.push({ id: d.id, ...d.data({ serverTimestamps: 'estimate' }) }));
    window.__myDMs = dms;
    if (currentView !== 'channel') renderDMRows();    // draw the list straight away (names are the usernames); avatars fill in as profiles arrive
    await Promise.all(dms.map(dm => getProfile(dm.participants.find(p => p !== myUid))));
    hydrateConversationPreviews('dms', dms);
    ovRenderLists();
    if (currentView !== 'channel') renderDMRows();
  });
  let groupDmsFirstSync = true;
  if (unsub.groupDms) unsub.groupDms();
  unsub.groupDms = db.collection('groupDMs').where('participants', 'array-contains', myUid).onSnapshot(async snap => {
    maybePingForConversationSnapshot(snap, groupDmsFirstSync, 'gdm');
    groupDmsFirstSync = false;
    const gs = [];
    snap.forEach(d => gs.push({ id: d.id, ...d.data({ serverTimestamps: 'estimate' }) }));
    window.__myGroupDMs = gs;
    await Promise.all(gs.flatMap(g => g.participants.filter(p => p !== myUid).map(p => getProfile(p))));
    hydrateConversationPreviews('groupDMs', gs);
    if (currentView !== 'channel') renderDMRows();
    if (currentView === 'groupdm') {
      const cg = gs.find(x => x.id === currentGroupDMId);
      if (cg) { renderMemberPanel(cg.participants || [], cg.ownerId); $('chat-header-title').textContent = groupDMDisplayName(cg); }
    }
  });
}

function groupDMDisplayName(g) {
  if (g.name) return g.name;
  const others = withoutVanished(g.participants, g).filter(p => p !== myUid);
  return others.map(u => (profileCache[u] || { username: u }).username).join(', ') || 'Group';
}

function previewForMessage(message, includeAuthor = false) {
  if (!message) return 'No messages yet';
  if (typeof message === 'string') return message;
  let text = (message.text || '').replace(MASKED_LINK_RE, '$1').trim();
  if (!text && message.attachments && message.attachments.length) {
    text = message.attachments.length > 1
      ? `Sent ${message.attachments.length} photos`
      : (message.attachments[0].type === 'image' ? 'Sent a photo' : `Sent ${message.attachments[0].name || 'a file'}`);
  }
  if (!text && message.attachment) text = message.attachment.type === 'image' ? 'Sent a photo' : `Sent ${message.attachment.name || 'a file'}`;
  if (!text && message.gifUrl) text = 'Sent a GIF';
  if (!text && message.sticker) text = `Sent a sticker${message.sticker.name ? `: ${message.sticker.name}` : ''}`;
  if (!text && message.poll) text = `📊 Poll: ${message.poll.question}`;
  if (!text && message.system) text = systemPlainText(message);
  if (!text && message.purgeResult) text = `Deleted ${message.purgeResult.count} messages`;
  if (!text && message.wordle) text = '🟩 Started a game of Wordle';
  if (!text) text = 'New message';
  return includeAuthor && message.username ? `${message.username}: ${text}` : text;
}

function timeValue(timestamp) {
  if (!timestamp) return 0;
  if (typeof timestamp.toMillis === 'function') return timestamp.toMillis();
  if (timestamp instanceof Date) return timestamp.getTime();
  return typeof timestamp === 'number' ? timestamp : 0;
}

const conversationPreviewCache = new Map();
async function hydrateConversationPreviews(collection, conversations) {
  const missing = conversations.filter(conversation => !conversation.lastMessage && !conversationPreviewCache.has(`${collection}:${conversation.id}`));
  if (!missing.length) return;
  await Promise.all(missing.map(async conversation => {
    const key = `${collection}:${conversation.id}`;
    try {
      const snap = await db.collection(collection).doc(conversation.id).collection('messages')
        .orderBy('createdAt', 'desc').limit(1).get();
      conversationPreviewCache.set(key, snap.empty ? null : snap.docs[0].data());
    } catch (e) {
      conversationPreviewCache.set(key, null);
    }
  }));
  renderDMRows();
}

// "now", "5m", "3h", "2d", or a short date: the little time on the right of each message row on a phone.
function shortAgo(ms) {
  if (!ms) return '';
  const m = Math.floor((Date.now() - ms) / 60000);
  if (m < 1) return 'now';
  if (m < 60) return m + 'm';
  if (m < 1440) return Math.floor(m / 60) + 'h';
  if (m < 10080) return Math.floor(m / 1440) + 'd';
  return new Date(ms).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}
// Which conversations have something new since you last opened them, kept in this browser. The phone layout shows
// those rows in white and the rest in grey, like Discord. Conversations never opened here count from when this
// browser first started keeping track, so nothing old suddenly looks unread.
let lastRead = null, lastReadFor = null;
const lastReadKey = () => 'frixion.lastRead.' + myUid;
function loadLastRead() {
  if (lastReadFor === myUid && lastRead) return lastRead;
  lastReadFor = myUid;
  try { lastRead = JSON.parse(localStorage.getItem(lastReadKey()) || 'null'); } catch (e) { lastRead = null; }
  if (!lastRead || typeof lastRead !== 'object') { lastRead = { _since: Date.now() }; saveLastRead(); }
  return lastRead;
}
function saveLastRead() { try { localStorage.setItem(lastReadKey(), JSON.stringify(lastRead)); } catch (e) {} }
function markConversationRead(id) { if (!myUid || !id) return; loadLastRead()[id] = Date.now(); saveLastRead(); }
function isConversationUnread(conv) {
  if (!myUid || !conv) return false;
  if (conv.id === currentDMId || conv.id === currentGroupDMId) { markConversationRead(conv.id); return false; }   // open right now
  const read = loadLastRead();
  const from = conv.lastMessage && conv.lastMessage.username;
  return !!from && from !== (myProfile && myProfile.username) && timeValue(conv.updatedAt) > (read[conv.id] || read._since || 0);
}
function renderDMRows() {
  const wrap = $('dm-rows');
  wrap.innerHTML = '';
  const dms = [...(window.__myDMs || [])].sort((a, b) => timeValue(b.updatedAt) - timeValue(a.updatedAt));
  dms.forEach(dm => {
    const otherUid = dm.participants.find(p => p !== myUid);
    const p = profileCache[otherUid] || { username: otherUid, avatarColor: '#5865f2', status: 'offline' };
    const row = document.createElement('div');
    const nameplate = nameplateById(p.equippedNameplate);
    row.className = 'dm-row' + (currentDMId === dm.id ? ' active' : '') + (isConversationUnread(dm) ? ' unread' : '') + (nameplate ? ' has-nameplate' : '');
    row.innerHTML = nameplateBgHTML(nameplate) +
      avatarHTML(32, p.avatarColor, initials(p.username), computeDisplayStatus(otherUid), p.avatarUrl, p.equippedDecoration, otherUid, p.equippedMask) +
      `<div class="dm-copy"><span class="dm-name">${esc(displayNameOf(p))}${premiumStar(p)}${roleTag(p)}${botTag(p)}</span><span class="dm-preview">${esc(previewForMessage(dm.lastMessage || conversationPreviewCache.get(`dms:${dm.id}`)))}</span></div><span class="dm-time">${esc(shortAgo(timeValue(dm.updatedAt) || timeValue((dm.lastMessage || {}).createdAt)))}</span>`;
    row.onclick = () => selectDM(dm.id, otherUid);
    wrap.appendChild(row);
  });
  const groups = [...(window.__myGroupDMs || [])].sort((a, b) => timeValue(b.updatedAt) - timeValue(a.updatedAt));
  groups.forEach(g => {
    const name = groupDMDisplayName(g);
    const row = document.createElement('div');
    row.className = 'dm-row' + (currentGroupDMId === g.id ? ' active' : '') + (isConversationUnread(g) ? ' unread' : '');
    row.innerHTML = `<div class="avatar group-avatar" style="width:32px;height:32px;">${icon('people')}</div><div class="dm-copy"><span class="dm-name">${esc(name)}</span><span class="dm-preview">${esc(previewForMessage(g.lastMessage || conversationPreviewCache.get(`groupDMs:${g.id}`), true))}</span></div><span class="dm-time">${esc(shortAgo(timeValue(g.updatedAt)))}</span>`;
    row.onclick = () => selectGroupDM(g.id);
    wrap.appendChild(row);
  });
  applyDmFilter();
}

// ---------- Phone home screen: the Messages header above the DM list ----------
// (The markup is #mobile-home-top in index.html; style.css only shows it on phones.)
let dmFilterQuery = '';
function applyDmFilter() {
  const q = dmFilterQuery.trim().toLowerCase();
  document.querySelectorAll('#dm-rows .dm-row').forEach(r => { r.hidden = !!q && !r.textContent.toLowerCase().includes(q); });
}
(function wireMobileHome() {
  const search = $('mht-search'); if (!search) return;
  const row = $('mht-search-row'), input = $('mht-search-input'), menu = $('mht-menu'), plus = $('mht-new');
  const setSearch = on => {
    row.hidden = !on;
    row.classList.toggle('is-open', on);
    if (on) { input.focus(); } else { input.value = ''; dmFilterQuery = ''; applyDmFilter(); }
  };
  const setMenu = on => { menu.hidden = !on; plus.setAttribute('aria-expanded', String(on)); };
  search.onclick = () => { setMenu(false); setSearch(row.hidden); };
  $('mht-search-clear').onclick = () => setSearch(false);
  input.oninput = () => { dmFilterQuery = input.value; applyDmFilter(); };
  plus.onclick = e => { e.stopPropagation(); setMenu(menu.hidden); };
  document.addEventListener('click', e => { if (!menu.hidden && !menu.contains(e.target)) setMenu(false); });
  $('mht-new-dm').onclick = () => { setMenu(false); $('dm-add-btn').click(); };
  $('mht-new-group').onclick = () => { setMenu(false); $('new-group-dm-btn').click(); };
  // Add Friends goes straight to the Add Friend tab of the Friends page.
  $('mht-add-friends').onclick = () => {
    setMenu(false);
    clearHomeNavActive();
    document.querySelector('.home-nav-item[data-home-view="friends"]').classList.add('active');
    openHomeMainView('friends');
    const tab = document.querySelector('.friends-tab[data-friends-tab="add"]'); if (tab) tab.click();
  };
  // Tells the stylesheet whether the Direct Messages list (and not a server's channel list) is showing.
  const dmList = $('dm-list'), appEl = $('app');
  const sync = () => appEl.classList.toggle('is-home', !dmList.classList.contains('hidden'));
  new MutationObserver(sync).observe(dmList, { attributes: true, attributeFilter: ['class'] });
  sync();
})();

$('dm-add-btn').onclick = () => { $('new-dm-username').value = ''; $('new-dm-error').textContent = ''; openModal('new-dm-modal'); };

async function startDMWith(uname) {
  if (uname === myUid) return;
  const snap = await db.collection('users').doc(uname).get();
  if (!snap.exists) { toast('No user found with that username.', 'error'); return; }
  profileCache[uname] = snap.data();
  const id = dmIdFor(myUid, uname);
  const ref = db.collection('dms').doc(id);
  const dsnap = await ref.get();
  if (!dsnap.exists) {
    await ref.set({ participants: [myUid, uname], autoDelete: true, createdAt: FieldValue.serverTimestamp() });
    db.collection('users').doc(myUid).update({ 'stats.dmsStarted': FieldValue.increment(1) }).catch(() => {});
  }
  selectDM(id, uname);
}

$('confirm-new-dm').onclick = async () => {
  const uname = $('new-dm-username').value.trim();
  $('new-dm-error').textContent = '';
  if (!uname) { $('new-dm-error').textContent = 'Enter a username.'; return; }
  if (uname === myProfile.username) { $('new-dm-error').textContent = "That's you!"; return; }
  try {
    await startDMWith(uname);
    closeModal('new-dm-modal');
  } catch (e) { $('new-dm-error').textContent = e.message; }
};

// The chat header: '#' for a channel, '@' for a DM. On a phone a DM shows the person's picture there instead (like
// Discord's app), and tapping the name opens their profile, or the member list in a channel or group.
function setChatHeaderHash(text, kind) {
  $('chat-header-hash').textContent = text;
  const header = $('chat-header');
  if (kind) header.dataset.kind = kind; else delete header.dataset.kind;
  renderChatHeaderAvatar();
}
function renderChatHeaderAvatar() {
  const uid = $('chat-header').dataset.kind === 'dm' ? currentDMOtherUid : null;
  const p = uid && profileCache[uid];
  $('chat-header-avatar').innerHTML = p ? avatarHTML(28, p.avatarColor, initials(p.username), computeDisplayStatus(uid), p.avatarUrl, null, uid) : '';
}
['chat-header-avatar', 'chat-header-hash', 'chat-header-title', 'chat-header-chev'].forEach(id => $(id).addEventListener('click', () => {
  const kind = $('chat-header').dataset.kind;
  if (!isMobile() || !kind) return;
  if (kind === 'dm') { if (currentDMOtherUid) openProfileModal(currentDMOtherUid); }
  else openConversationSheet(kind);
}));
// Phone: a channel or group shows only search and members in its header; the rest (pins, mute, add friends, leave) are in
// this sheet, like Discord's channel details. Each row presses the matching header button, so they behave the same.
function openConversationSheet(kind) {
  closeActionSheet();
  const rows = [['members-toggle', 'Members'], ['add-member-toggle', 'Add Friends'], ['pins-toggle', 'Pinned Messages'],
    ['mute-toggle', isMuted() ? 'Unmute' : 'Mute'], ['search-toggle', 'Search'], ['leave-group-toggle', 'Leave Group']]
    .filter(([id]) => !$(id).classList.contains('hidden'));
  const title = (kind === 'channel' ? '#' : '') + $('chat-header-title').textContent;
  const backdrop = document.createElement('div');
  backdrop.className = 'action-sheet-backdrop';
  backdrop.innerHTML = `<div class="action-sheet"><div class="as-title">${esc(title)}</div><div class="as-actions">${rows.map(([id, label]) => {
    const svg = $(id).querySelector('svg:not(.hidden)') || $(id).querySelector('svg');
    return `<button type="button" class="as-item${id === 'leave-group-toggle' ? ' as-danger' : ''}" data-btn="${id}">${svg ? svg.outerHTML : ''}<span>${esc(label)}</span></button>`;
  }).join('')}</div></div>`;
  document.body.appendChild(backdrop);
  document.body.classList.add('action-sheet-open');
  backdrop.addEventListener('click', e => { if (e.target === backdrop) closeActionSheet(); });
  backdrop.querySelectorAll('.as-item').forEach(b => { b.onclick = () => { closeActionSheet(); $(b.dataset.btn).click(); }; });
  openActionSheet = backdrop;
}

async function selectDM(id, otherUid) {
  clearReplyTarget();
  clearMyTypingDoc();
  currentServerId = null; currentServerData = null; currentChannelId = null; currentGroupDMId = null;
  exitCommandMode();
  currentView = 'dm'; currentDMId = id; currentDMOtherUid = otherUid;
  markConversationRead(id);
  clearHomeNavActive();
  subscribeTyping();
  document.querySelectorAll('#server-rail-list .rail-item').forEach(e => e.classList.remove('active'));
  $('rail-home').classList.add('active');
  $('members-toggle').classList.add('hidden');
  $('app').classList.remove('member-list-open');
  hideMainPageViews();
  const p = await getProfile(otherUid);
  setChatHeaderHash('@', 'dm');
  $('chat-header-title').textContent = p.username;
  $('composer-input').placeholder = `Message @${p.username}`;
  refreshChannelComposerState();
  $('gift-btn').classList.remove('hidden');
  showHeaderActions();
  renderDMRows();
  showChat();
  setMobilePane('chat');
  scheduleMsgLoading();
  const dmDoc = (window.__myDMs || []).find(d => d.id === id);
  if (!dmDoc || dmDoc.autoDelete !== false) sweepOldMessages(db.collection('dms').doc(id).collection('messages'));
  listenToMessages(db.collection('dms').doc(id).collection('messages'), snap => {
    const msgs = [];
    snap.forEach(d => msgs.push({ id: d.id, ...d.data() }));
    onMessagesUpdate(msgs);
  });
}

async function selectGroupDM(id) {
  clearReplyTarget();
  clearMyTypingDoc();
  currentServerId = null; currentServerData = null; currentChannelId = null;
  currentDMId = null; currentDMOtherUid = null;
  exitCommandMode();
  currentView = 'groupdm'; currentGroupDMId = id;
  markConversationRead(id);
  clearHomeNavActive();
  subscribeTyping();
  document.querySelectorAll('#server-rail-list .rail-item').forEach(e => e.classList.remove('active'));
  $('rail-home').classList.add('active');
  hideMainPageViews();
  const g = (window.__myGroupDMs || []).find(x => x.id === id);
  const name = g ? groupDMDisplayName(g) : 'Group';
  setChatHeaderHash('', 'group');
  $('chat-header-title').textContent = name;
  $('composer-input').placeholder = `Message ${name}`;
  refreshChannelComposerState();
  $('gift-btn').classList.add('hidden');
  $('members-toggle').classList.remove('hidden');
  applyDefaultMemberListState();
  showHeaderActions();
  $('pins-toggle').classList.remove('hidden');
  renderMemberPanel(g ? g.participants : [], g ? g.ownerId : null);
  renderDMRows();
  showChat();
  setMobilePane('chat');
  scheduleMsgLoading();
  if (!g || g.autoDelete !== false) sweepOldMessages(db.collection('groupDMs').doc(id).collection('messages'));
  listenToMessages(db.collection('groupDMs').doc(id).collection('messages'), snap => {
    const msgs = [];
    snap.forEach(d => msgs.push({ id: d.id, ...d.data() }));
    onMessagesUpdate(msgs);
  });
}

let groupDmPickerSelection = [];
function renderFriendPicker(containerId, excludeUids) {
  const wrap = $(containerId);
  const friends = (myProfile.friends || []).filter(u => !excludeUids.includes(u));
  groupDmPickerSelection = [];
  if (!friends.length) { wrap.innerHTML = '<div class="empty">Add some friends first.</div>'; return; }
  wrap.innerHTML = friends.map(u => `<label class="friend-pick-row"><input type="checkbox" value="${esc(u)}"><span>${esc(u)}</span></label>`).join('');
}

$('dm-add-btn').addEventListener('contextmenu', (e) => e.preventDefault());

document.querySelectorAll('.home-nav-item').forEach(() => {}); // (nav wiring above)

$('new-group-dm-btn').onclick = () => {
  renderFriendPicker('group-dm-friend-picker', []);
  $('new-group-dm-name').value = '';
  openModal('new-group-dm-modal');
};
$('add-member-toggle').onclick = () => {
  if (!currentGroupDMId) return;
  const g = (window.__myGroupDMs || []).find(x => x.id === currentGroupDMId);
  renderFriendPicker('add-to-group-friend-picker', g ? g.participants : [myUid]);
  openModal('add-to-group-modal');
};

$('leave-group-toggle').onclick = () => {
  const g = groupById(currentGroupDMId);
  if (!g) return;
  const name = groupDMDisplayName(g);
  confirmAction({
    title: `Leave '${name}'`, body: `Are you sure you want to leave ${name}? Someone in the group has to add you back if you change your mind.`, confirmLabel: 'Leave Group',
    onConfirm: async () => {
      try {
        const id = g.id, wasVanished = vanishedListFor(g).includes(myUid);
        if (!wasVanished) await postSystemMessage(db.collection('groupDMs').doc(id).collection('messages'), { system: 'leave', place: 'group', uid: myUid, username: myProfile.username });
        const upd = { participants: FieldValue.arrayRemove(myUid) };
        if (wasVanished) upd.vanished = FieldValue.arrayRemove(myUid);
        if (g.ownerId === myUid) {
          const next = (g.participants || []).find(u => u !== myUid);
          if (next) upd.ownerId = next;
        }
        await db.collection('groupDMs').doc(id).update(upd);
        if (currentGroupDMId === id) showHomeView();
        toast(`You left ${name}.`);
      } catch (e) { toast(e.message || 'Could not leave the group.', 'error'); }
    },
  });
};
$('confirm-new-group-dm').onclick = async () => {
  const checks = [...$('group-dm-friend-picker').querySelectorAll('input:checked')].map(i => i.value);
  if (checks.length < 2) { toast('Pick at least 2 friends for a group.'); return; }
  const name = $('new-group-dm-name').value.trim();
  try {
    const participants = [myUid, ...checks];
    const ref = await db.collection('groupDMs').add({
      name: name || null, participants, ownerId: myUid, autoDelete: true, createdAt: FieldValue.serverTimestamp(),
    });
    postSystemMessage(db.collection('groupDMs').doc(ref.id).collection('messages'), { system: 'add', place: 'group', uid: myUid, username: myProfile.username, targets: checks });
    closeModal('new-group-dm-modal');
    toast('Group created.');
    selectGroupDM(ref.id);
  } catch (e) { toast('Could not create group.', 'error'); }
};

$('confirm-add-to-group').onclick = async () => {
  const checks = [...$('add-to-group-friend-picker').querySelectorAll('input:checked')].map(i => i.value);
  if (!checks.length || !currentGroupDMId) { toast('Pick at least one friend.'); return; }
  try {
    await db.collection('groupDMs').doc(currentGroupDMId).update({ participants: FieldValue.arrayUnion(...checks) });
    postSystemMessage(db.collection('groupDMs').doc(currentGroupDMId).collection('messages'), { system: 'add', place: 'group', uid: myUid, username: myProfile.username, targets: checks });
    closeModal('add-to-group-modal');
    toast('Added to group.');
  } catch (e) { toast('Could not add to group.', 'error'); }
};

