const smIcon = (name) => `<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${SM_ICONS[name]}</svg>`;

function updateChannelManageButtons() {
  const canManage = !!(currentServerData && hasServerPerm(currentServerData, myUid, 'manageChannels'));
  $('category-add-btn').classList.toggle('hidden', !canManage);
  $('channel-add-btn').classList.toggle('hidden', !canManage);
}

function closeServerMenu() {
  $('server-menu').classList.add('hidden');
  $('side-header').setAttribute('aria-expanded', 'false');
}

async function copyText(text, okMsg) {
  try { await navigator.clipboard.writeText(text); toast(okMsg); }
  catch (e) { toast('Could not copy. ' + text); }
}

function buildServerMenuItems(server) {
  const can = (p) => hasServerPerm(server, myUid, p);
  const isOwnerHere = server.ownerId === myUid;
  const groups = [
    [
      can('createInvite') && { id: 'invite', icon: 'invite', label: 'Invite to Server' },
      (can('manageServer') || can('manageRoles')) && { id: 'settings', icon: 'settings', label: 'Server Settings' },
      can('manageRoles') && { id: 'roles', icon: 'roles', label: 'Manage Roles' },
      can('manageChannels') && { id: 'channel', icon: 'channel', label: 'Create Channel' },
      can('manageChannels') && { id: 'category', icon: 'category', label: 'Create Category' },
      can('manageChannels') && currentChannelId && { id: 'edit-channel', icon: 'settings', label: 'Edit Current Channel' },
      canOpenAddApp(server) && { id: 'add-app', icon: 'app', label: 'Add App' },
    ],
    [
      can('changeNickname') && { id: 'nickname', icon: 'edit', label: 'Change Nickname' },
      can('viewAuditLog') && { id: 'audit', icon: 'audit', label: 'Audit Log' },
      can('viewServerInsights') && { id: 'insights', icon: 'insights', label: 'Server Insights' },
    ],
    [{ id: 'copy-id', icon: 'copy', label: 'Copy Server ID' }],
    [!isOwnerHere && { id: 'leave', icon: 'leave', label: 'Leave Server', danger: true }],
  ].map(g => g.filter(Boolean)).filter(g => g.length);
  return groups.map(g => g.map(it =>
    `<button type="button" role="menuitem" class="server-menu-item${it.danger ? ' danger' : ''}" data-sm="${it.id}"><span>${it.label}</span>${smIcon(it.icon)}</button>`
  ).join('')).join('<div class="server-menu-sep" role="separator"></div>');
}

function openServerMenu() {
  const server = currentServerData;
  if (!server) return;
  const menu = $('server-menu');
  menu.innerHTML = buildServerMenuItems(server);
  menu.classList.remove('hidden');
  $('side-header').setAttribute('aria-expanded', 'true');
  const first = menu.querySelector('.server-menu-item');
  if (first) first.focus({ preventScroll: true });
  menu.querySelectorAll('[data-sm]').forEach(btn => { btn.onclick = () => runServerMenuAction(btn.dataset.sm, server); });
}

function runServerMenuAction(action, server) {
  closeServerMenu();
  if (action === 'invite') copyText(inviteLinkFor(server.inviteCode), 'Invite link copied. Anyone with it can join.');
  else if (action === 'settings') openServerSettings();
  else if (action === 'roles') openServerSettings('roles');
  else if (action === 'channel') $('channel-add-btn').click();
  else if (action === 'category') $('category-add-btn').click();
  else if (action === 'add-app') openAddAppModal(server);
  else if (action === 'edit-channel') { const ch = currentChannelObj(); if (ch) openChannelSettings(ch); }
  else if (action === 'copy-id') copyText(server.id, 'Server ID copied.');
  else if (action === 'leave') {
    confirmAction({
      title: `Leave '${server.name}'`, body: `Are you sure you want to leave ${server.name}? You won't be able to rejoin unless you are re-invited.`, confirmLabel: 'Leave Server',
      onConfirm: async () => {
        try {
          leavingServerId = server.id;
          if (!vanishedListFor(server).includes(myUid)) await postServerLeaveMessage(server.id);   // already vanished = already announced
          await db.collection('servers').doc(server.id).update({ members: FieldValue.arrayRemove(myUid), vanished: FieldValue.arrayRemove(myUid) });
          if (currentServerId === server.id) showHomeView();
          toast(`You left ${server.name}.`);
        } catch (e) { toast(e.message || 'Could not leave the server.', 'error'); }
        finally { leavingServerId = null; }
      },
    });
  }
  else if (action === 'nickname') openNicknameEditor(server, myUid);
  else if (action === 'audit') openAuditLog(server);
  else if (action === 'insights') openServerInsights(server);
}
let leavingServerId = null;

// ---- generic lightweight modal (audit log, insights, nickname) ----
function openInfoModal(title, bodyHTML) {
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay frx-info-modal';
  overlay.innerHTML = `<div class="modal-box" role="dialog" aria-modal="true" aria-label="${esc(title)}">
    <div class="modal-header-row"><h2>${esc(title)}</h2><span class="x" role="button" tabindex="0" aria-label="Close">✕</span></div>
    <div class="frx-info-body">${bodyHTML}</div></div>`;
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onKey); };
  const onKey = (e) => { if (e.key === 'Escape') close(); };
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
  overlay.querySelector('.x').onclick = close;
  document.addEventListener('keydown', onKey);
  document.body.appendChild(overlay);
  return { overlay, close };
}
function openNicknameEditor(server, uid) {
  const self = uid === myUid;
  if (self ? !hasServerPerm(server, myUid, 'changeNickname') : !hasServerPerm(server, myUid, 'manageNicknames')) {
    toast('You do not have permission to change that nickname.', 'error'); return;
  }
  const p = profileCache[uid] || { username: uid };
  const { overlay, close } = openInfoModal(self ? 'Change Nickname' : `Nickname for ${displayNameOf(p)}`, `
    <div class="field"><label for="frx-nick-input">Nickname</label>
      <input type="text" id="frx-nick-input" maxlength="${NICKNAME_MAX}" placeholder="${esc(displayNameOf(p))}" value="${esc(serverNickFor(uid, server))}"></div>
    <p class="desc">Only shows in ${esc(server.name)}. Leave empty to reset.</p>
    <div class="modal-actions"><button class="btn-secondary" data-act="reset">Reset</button><button class="btn-accent-inline" data-act="save">Save</button></div>`);
  const input = overlay.querySelector('#frx-nick-input');
  input.focus();
  const save = async (value) => {
    const nick = value.trim().slice(0, NICKNAME_MAX);
    try {
      await db.collection('servers').doc(server.id).update({ [`nicknames.${uid}`]: nick ? nick : FieldValue.delete() });
      if (!self) logAudit(server.id, `changed ${p.username}'s nickname to ${nick || '(reset)'}`);
      toast(nick ? 'Nickname updated.' : 'Nickname reset.');
      close();
    } catch (e) { toast(e.message || 'Could not update nickname.', 'error'); }
  };
  overlay.querySelector('[data-act="save"]').onclick = () => save(input.value);
  overlay.querySelector('[data-act="reset"]').onclick = () => save('');
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.isComposing && e.keyCode !== 229) save(input.value); });
}
async function openAuditLog(server) {
  if (!hasServerPerm(server, myUid, 'viewAuditLog')) { toast('You do not have permission to view the audit log.', 'error'); return; }
  const log = [...(server.auditLog || [])].reverse();
  await Promise.all([...new Set(log.map(e => e.by))].map(u => getProfile(u)));
  openInfoModal('Audit Log', log.length
    ? `<ul class="frx-audit-list">${log.map(e => `<li><b>${esc(displayNameOf(profileCache[e.by] || { username: e.by }))}</b> ${esc(e.action)}<time>${esc(new Date(e.at).toLocaleString())}</time></li>`).join('')}</ul>`
    : '<div class="empty">Nothing here yet. Kicks, bans, timeouts, nickname and channel changes show up here.</div>');
}
function openServerInsights(server) {
  if (!hasServerPerm(server, myUid, 'viewServerInsights')) { toast('You do not have permission to view insights.', 'error'); return; }
  const members = server.members || [];
  const online = members.filter(u => computeDisplayStatus(u) !== 'offline').length;
  const mobile = members.filter(u => computeDisplayStatus(u) !== 'offline' && isOnMobile(u)).length;
  const timedOut = Object.keys(server.timeouts || {}).filter(u => timeoutUntil(server, u)).length;
  const stat = (n, l) => `<div class="frx-stat"><div class="frx-stat-n">${n}</div><div class="frx-stat-l">${l}</div></div>`;
  openInfoModal('Server Insights', `<div class="frx-stats">
    ${stat(members.length, 'Members')}${stat(online, 'Online now')}${stat(mobile, 'On mobile')}
    ${stat(lastChannelsList.length, 'Channels')}${stat(lastCategoriesList.length, 'Categories')}
    ${stat(serverRoles(server).filter(r => r.id !== 'everyone').length, 'Roles')}
    ${stat((server.bannedUsers || []).length, 'Banned')}${stat(timedOut, 'Timed out')}
  </div>`);
}

$('side-header').onclick = (e) => {
  if (!currentServerId || !currentServerData) return;
  e.stopPropagation();
  if ($('server-menu').classList.contains('hidden')) openServerMenu(); else closeServerMenu();
};
document.addEventListener('click', (e) => {
  if (!$('server-menu').classList.contains('hidden') && !e.target.closest('#server-menu')) closeServerMenu();
});
$('server-menu').addEventListener('keydown', (e) => {
  const items = [...$('server-menu').querySelectorAll('.server-menu-item')];
  const i = items.indexOf(document.activeElement);
  if (e.key === 'Escape') { e.stopPropagation(); closeServerMenu(); $('side-header').focus(); }
  else if (e.key === 'ArrowDown') { e.preventDefault(); items[(i + 1) % items.length].focus(); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); items[(i - 1 + items.length) % items.length].focus(); }
});

function openServerSettings(tab) {
  if (!currentServerId || !currentServerData) return;
  const can = (p) => hasServerPerm(currentServerData, myUid, p);
  const canManage = can('manageServer') || can('manageRoles') || can('banMembers');
  if (!canManage) { toast('You need Manage Server, Manage Roles, or Ban Members permission to open Server Settings.'); return; }
  const tabPerm = { overview: 'manageServer', roles: 'manageRoles', invites: 'manageServer', bans: 'banMembers' };
  document.querySelectorAll('.ss-tab').forEach(t => t.classList.toggle('hidden', !can(tabPerm[t.dataset.ssTab])));
  document.querySelector('.ss-nav-mod').classList.toggle('hidden', !can('manageServer') && !can('banMembers'));
  $('edit-server-desc').value = currentServerData.description || '';
  $('edit-server-desc').disabled = !can('manageServer');
  $('server-invite-code').textContent = currentServerData.inviteCode;
  $('server-settings-title').textContent = currentServerData.name;
  $('edit-server-name').value = currentServerData.name;
  $('edit-server-name').disabled = !hasServerPerm(currentServerData, myUid, 'manageServer');
  $('save-server-btn').classList.toggle('hidden', !hasServerPerm(currentServerData, myUid, 'manageServer'));
  $('server-invite-display').value = inviteLinkFor(currentServerData.inviteCode);
  $('ss-icon-preview').textContent = initials(currentServerData.name);
  // Only the server's owner (or the Frixion owner) ever sees Delete Server —
  // Manage Server / Administrator alone can't erase it out from under its owner.
  $('delete-server-btn').classList.toggle('hidden', !isServerOwnerLevel(currentServerData, myUid));
  openServerSettingsTab(tab || (can('manageServer') ? 'overview' : can('manageRoles') ? 'roles' : 'bans'));
  openModal('server-settings-modal');
}

async function renderBansList() {
  const list = $('bans-list');
  const server = currentServerData || {};
  const banned = server.bannedUsers || [];
  const info = server.banInfo || {};
  const q = $('bans-search').value.trim().toLowerCase();
  $('bans-count').textContent = `${banned.length} banned`;
  $('bans-count').classList.toggle('none', !banned.length);
  const empty = (title, text) => `<div class="bans-empty"><div class="bans-empty-icon"><svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l7 3v5c0 4.4-2.9 8.3-7 10-4.1-1.7-7-5.6-7-10V6z"/><path d="M9 12l2 2 4-4"/></svg></div><b>${title}</b><span>${text}</span></div>`;
  if (!banned.length) { list.innerHTML = empty('No bans', 'Nobody has been banned from this server yet.'); return; }
  const people = [...new Set([...banned, ...banned.map(u => info[u] && info[u].by).filter(Boolean)])];
  const profiles = {};
  await Promise.all(people.map(async u => { profiles[u] = await getProfile(u).catch(() => null) || { username: u }; }));
  const rows = banned.map(uid => ({ uid, p: profiles[uid], i: info[uid] || {} }))
    .filter(({ p }) => !q || (p.username || '').toLowerCase().includes(q) || displayNameOf(p).toLowerCase().includes(q))
    .sort((a, b) => (b.i.at || 0) - (a.i.at || 0));
  if (!rows.length) { list.innerHTML = empty('No matches', 'No banned member matches your search.'); return; }
  list.innerHTML = rows.map(({ uid, p, i }) => {
    const when = i.at ? new Date(i.at).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : null;
    const by = i.by && profiles[i.by] ? displayNameOf(profiles[i.by]) : null;
    const meta = [by ? `Banned by ${esc(by)}` : 'Banned', when].filter(Boolean).join(' · ');
    return `<div class="ban-row">
      ${avatarHTML(44, p.avatarColor, initials(p.username || uid), null, p.avatarUrl, null, uid)}
      <div class="ban-info">
        <div class="ban-name">${esc(displayNameOf(p) || uid)}<span class="ban-handle">@${esc(p.username || uid)}</span></div>
        <div class="ban-meta">${meta}</div>
        ${i.reason ? `<div class="ban-reason"><span>Reason</span>${esc(i.reason)}</div>` : ''}
      </div>
      <button type="button" class="ban-revoke" data-unban="${esc(uid)}">Revoke ban</button>
    </div>`;
  }).join('');
  list.querySelectorAll('[data-unban]').forEach(b => { b.onclick = async () => {
    const uid = b.dataset.unban;
    b.disabled = true;
    try {
      await db.collection('servers').doc(currentServerId).update({ bannedUsers: FieldValue.arrayRemove(uid), [`banInfo.${uid}`]: FieldValue.delete() });
      if (currentServerData.bannedUsers) currentServerData.bannedUsers = currentServerData.bannedUsers.filter(u => u !== uid);
      if (currentServerData.banInfo) delete currentServerData.banInfo[uid];
      toast('Ban revoked.');
      renderBansList();
    } catch (e) { b.disabled = false; toast(e.message || 'Could not revoke the ban.', 'error'); }
  }; });
}
$('bans-search').addEventListener('input', () => renderBansList());

$('edit-server-name').addEventListener('input', () => {
  $('ss-icon-preview').textContent = initials($('edit-server-name').value || '?');
});
$('copy-invite-btn').onclick = async () => {
  const code = $('server-invite-display').value;
  try { await navigator.clipboard.writeText(code); toast('Invite link copied.'); }
  catch (e) { $('server-invite-display').select(); toast('Press Ctrl+C to copy.'); }
};
document.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape') return;
  if (!$('confirm-modal').classList.contains('hidden')) { closeModal('confirm-modal'); return; }
  if (!$('channel-settings-modal').classList.contains('hidden')) { closeModal('channel-settings-modal'); return; }
  if (!$('server-settings-modal').classList.contains('hidden')) {
    if (roleFormIsDirty(roleEditorPending, roleEditorSnapshot)) { flashUnsavedBar(); return; }
    closeModal('server-settings-modal');
  }
});

$('save-server-btn').onclick = async () => {
  const name = $('edit-server-name').value.trim();
  if (!name || !currentServerId || !currentServerData) return;
  if (!hasServerPerm(currentServerData, myUid, 'manageServer')) { toast('You need Manage Server permission to do that.', 'error'); return; }
  await db.collection('servers').doc(currentServerId).update({ name, description: $('edit-server-desc').value.trim().slice(0, 300) });
  closeModal('server-settings-modal');
  toast('Server updated.');
};

$('delete-server-btn').onclick = async () => {
  if (!currentServerId || !currentServerData) return;
  // Deleting (as opposed to editing) is reserved for the actual owner,
  // same as Discord — Manage Server lets you run the place day-to-day,
  // but it doesn't let you erase it out from under its owner.
  if (!isServerOwnerLevel(currentServerData, myUid)) { toast('Only the server owner can delete this server.', 'error'); return; }
  const sid = currentServerId;
  const name = currentServerData.name;
  confirmAction({
    title: 'Delete Server', body: `Delete "${name}" permanently? This cannot be undone.`, confirmLabel: 'Delete Server',
    onConfirm: async () => {
      try {
        const chSnap = await db.collection('servers').doc(sid).collection('channels').get();
        for (const ch of chSnap.docs) {
          const msgSnap = await ch.ref.collection('messages').get();
          await Promise.all(msgSnap.docs.map(m => m.ref.delete()));
          await ch.ref.delete();
        }
        await db.collection('servers').doc(sid).delete();
        closeModal('server-settings-modal');
        showHomeView();
        toast('Server deleted.');
      } catch (e) { toast('Failed to delete server: ' + e.message, 'error'); }
    },
  });
};

// ============================================================
// SERVER SETTINGS: ROLES TAB
// ============================================================
document.querySelectorAll('.ss-tab').forEach(btn => {
  btn.onclick = () => {
    if (roleFormIsDirty(roleEditorPending, roleEditorSnapshot)) { flashUnsavedBar(); return; }
    openServerSettingsTab(btn.dataset.ssTab);
  };
});
function openServerSettingsTab(tab) {
  if (tab === 'overview' && currentServerData && !hasServerPerm(currentServerData, myUid, 'manageServer')) { toast('You need Manage Server permission to view this.'); return; }
  document.querySelectorAll('.ss-tab').forEach(t => t.classList.toggle('on', t.dataset.ssTab === tab));
  ['overview', 'roles', 'invites', 'bans'].forEach(p => $('ss-pane-' + p).classList.toggle('hidden', tab !== p));
  if (tab === 'bans') { $('bans-search').value = ''; renderBansList(); }
  if (tab === 'roles') {
    rolesView = 'list'; selectedRoleId = null; roleListSearch = '';
    resetRoleEditorState();
    renderRolesPane();
  }
}

// ---- Discord-parity roles editor state ----
let rolesView = 'list';          // 'list' (roles table) | 'edit' (single role editor)
let selectedRoleId = null;
let roleEditorTab = 'display';   // 'display' | 'permissions' | 'members'
let roleEditorSnapshot = null;   // role as last saved, for dirty-checking and Reset
let roleEditorPending = null;    // in-progress edits, survives tab switches
let roleEditorPendingRoleId = null;
let roleListSearch = '';
let rolePermSearch = '';
let roleMemberSearch = '';
let roleAddMembersOpen = false;

const ROLE_DEFAULT_COLOR = '#99aab5';
const ROLE_COLOR_PALETTE = [
  '#1abc9c', '#2ecc71', '#3498db', '#9b59b6', '#e91e63', '#f1c40f', '#e67e22', '#e74c3c', '#95a5a6', '#607d8b',
  '#11806a', '#1f8b4c', '#206694', '#71368a', '#ad1457', '#c27c0e', '#a84300', '#992d22', '#979c9f', '#546e7a',
];
const ROLE_ICONS = {
  shield: '<svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor" aria-hidden="true"><path d="M12 2 4 5v6c0 5 3.4 9.5 8 11 4.6-1.5 8-6 8-11V5l-8-3z"/></svg>',
  person: '<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.6-6.5 8-6.5s8 2.5 8 6.5z"/></svg>',
  people: '<svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor" aria-hidden="true"><circle cx="9" cy="8" r="3.5"/><path d="M2 20c0-3.6 3.1-6 7-6s7 2.4 7 6z"/><circle cx="17" cy="9" r="2.8"/><path d="M17.5 13.5c2.7.3 4.5 2.4 4.5 5.5h-4.2c0-2.3-.8-4.1-2.2-5.3.6-.1 1.2-.2 1.9-.2z"/></svg>',
  search: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3"/></svg>',
  pencil: '<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" aria-hidden="true"><path d="M16.3 3.3a2.4 2.4 0 0 1 3.4 3.4L8.4 18l-4.9 1.4L5 14.6z"/></svg>',
  drag: '<svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true"><circle cx="9" cy="6" r="1.6"/><circle cx="15" cy="6" r="1.6"/><circle cx="9" cy="12" r="1.6"/><circle cx="15" cy="12" r="1.6"/><circle cx="9" cy="18" r="1.6"/><circle cx="15" cy="18" r="1.6"/></svg>',
  chevronRight: '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg>',
  chevronLeft: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 6l-6 6 6 6"/></svg>',
  plus: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>',
  x: '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>',
  check: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>',
  dropper: '<svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true"><path d="M19.4 4.6a2.8 2.8 0 0 0-4 0l-2 2-1.2-1.2-1.4 1.4 1.2 1.2-7 7V19h3.4l7-7 1.2 1.2 1.4-1.4-1.2-1.2 2-2a2.8 2.8 0 0 0 0-4z"/></svg>',
};

function resetRoleEditorState() { roleEditorPending = null; roleEditorSnapshot = null; roleEditorPendingRoleId = null; }
function roleSnapshotOf(role) { return { name: role.name, color: role.color || null, hoist: !!role.hoist, permissions: (role.permissions || []).slice() }; }
function roleFormIsDirty(pending, original) {
  if (!pending || !original) return false;
  return pending.name !== original.name || (pending.color || null) !== (original.color || null) ||
    !!pending.hoist !== !!original.hoist ||
    pending.permissions.slice().sort().join(',') !== (original.permissions || []).slice().sort().join(',');
}
function updateRoleUnsavedBar() {
  const bar = $('re-unsaved-bar');
  if (bar) bar.classList.toggle('hidden', !roleFormIsDirty(roleEditorPending, roleEditorSnapshot));
}
// Discord blocks navigation while there are unsaved changes and shakes the bar.
function flashUnsavedBar() {
  const bar = $('re-unsaved-bar');
  if (!bar) return;
  bar.classList.remove('hidden', 'shake');
  void bar.offsetWidth;
  bar.classList.add('shake');
}
function sortedServerRoles() { return serverRoles(currentServerData).slice().sort((a, b) => b.position - a.position); }
function findServerRole(id) {
  return serverRoles(currentServerData).find(r => r.id === id) || (id === 'everyone' ? everyoneRole(currentServerData) : null);
}
function roleMemberIds(roleId) {
  const members = currentServerData.members || [];
  if (roleId === 'everyone') return members.slice();
  const map = currentServerData.memberRoles || {};
  return members.filter(uid => (map[uid] || []).includes(roleId));
}
// Owner-level can edit anything; Manage Roles can edit only roles ranked
// strictly below their own highest role — same ceiling as Discord.
function canEditRole(role) {
  if (!currentServerData || !role) return false;
  if (isServerOwnerLevel(currentServerData, myUid)) return true;
  if (!hasServerPerm(currentServerData, myUid, 'manageRoles')) return false;
  return topRoleOf(currentServerData, myUid).position > role.position;
}

function renderRolesPane() {
  if (!currentServerData) return;
  const root = $('roles-pane-root');
  if (!root) return;
  if (rolesView === 'edit' && selectedRoleId && findServerRole(selectedRoleId)) renderRoleEditView(root);
  else { rolesView = 'list'; renderRolesListView(root); }
}

function renderRolesListView(root) {
  const canManage = hasServerPerm(currentServerData, myUid, 'manageRoles');
  const roles = sortedServerRoles().filter(r => r.id !== 'everyone');
  root.innerHTML = `
    <h2 class="ss-h2">Roles</h2>
    <p class="ss-desc">Use roles to group your server members and assign permissions.</p>
    <button type="button" class="dr-default-card" id="dr-everyone-card">
      <span class="dr-default-icon">${ROLE_ICONS.people}</span>
      <span class="dr-default-text"><b>Default Permissions</b><small>@everyone &bull; applies to all server members</small></span>
      <span class="dr-chevron">${ROLE_ICONS.chevronRight}</span>
    </button>
    <div class="dr-toolbar">
      <label class="dr-search dr-grow"><span class="sr-only">Search roles</span><input type="text" id="dr-role-search" placeholder="Search Roles" value="${esc(roleListSearch)}" autocomplete="off"><span class="dr-search-icon">${ROLE_ICONS.search}</span></label>
      ${canManage ? '<button type="button" class="ds-btn ds-btn-brand" id="dr-create-role">Create Role</button>' : ''}
    </div>
    <p class="ss-hint">Members use the color of the highest role they have on this list.${canManage ? ' Drag roles to reorder them.' : ''}</p>
    <div class="dr-table" role="table" aria-label="Roles">
      <div class="dr-thead" role="row"><span role="columnheader">Roles &mdash; ${roles.length}</span><span role="columnheader">Members</span><span aria-hidden="true"></span></div>
      ${roles.map(r => `
        <div class="dr-row" role="row" tabindex="0" data-id="${esc(r.id)}" data-name="${esc(r.name.toLowerCase())}" ${canManage && canEditRole(r) ? 'draggable="true"' : ''}>
          <span class="dr-cell-name" role="cell">
            <span class="dr-drag">${canManage && canEditRole(r) ? ROLE_ICONS.drag : ''}</span>
            <span class="dr-shield" style="color:${esc(cssColor(r.color, ROLE_DEFAULT_COLOR))}">${ROLE_ICONS.shield}</span>
            <span class="dr-name">${esc(r.name)}</span>
          </span>
          <span class="dr-cell-members" role="cell">${roleMemberIds(r.id).length}${ROLE_ICONS.person}</span>
          <span class="dr-cell-actions" role="cell"><span class="dr-icon-btn" title="Edit role">${ROLE_ICONS.pencil}</span></span>
        </div>`).join('')}
      <div class="dr-empty${roles.length ? ' hidden' : ''}" id="dr-roles-empty">${roles.length ? 'No roles match your search.' : 'No roles yet. Create one to organize your members.'}</div>
    </div>`;

  const applyFilter = () => {
    const q = roleListSearch.trim().toLowerCase();
    let visible = 0;
    root.querySelectorAll('.dr-row').forEach(row => {
      const show = !q || row.dataset.name.includes(q);
      row.classList.toggle('hidden', !show);
      if (show) visible++;
    });
    if (roles.length) $('dr-roles-empty').classList.toggle('hidden', visible > 0);
  };
  $('dr-role-search').oninput = (e) => { roleListSearch = e.target.value; applyFilter(); };
  applyFilter();
  $('dr-everyone-card').onclick = () => openRoleEditor('everyone');
  if ($('dr-create-role')) $('dr-create-role').onclick = createServerRole;
  root.querySelectorAll('.dr-row').forEach(row => {
    row.onclick = () => openRoleEditor(row.dataset.id);
    row.onkeydown = (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openRoleEditor(row.dataset.id); } };
  });
  wireRoleDrag(root.querySelectorAll('.dr-row[draggable]'));
}

function openRoleEditor(roleId) {
  selectedRoleId = roleId;
  rolesView = 'edit';
  roleEditorTab = roleId === 'everyone' ? 'permissions' : 'display';
  resetRoleEditorState();
  rolePermSearch = ''; roleMemberSearch = ''; roleAddMembersOpen = false;
  renderRolesPane();
}

function wireRoleDrag(rows) {
  let dragId = null;
  rows.forEach(row => {
    row.addEventListener('dragstart', (e) => {
      dragId = row.dataset.id;
      row.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
      try { e.dataTransfer.setData('text/plain', dragId); } catch (err) {}
    });
    row.addEventListener('dragend', () => row.classList.remove('dragging'));
    row.addEventListener('dragover', (e) => { e.preventDefault(); row.classList.add('drag-over'); });
    row.addEventListener('dragleave', () => row.classList.remove('drag-over'));
    row.addEventListener('drop', (e) => {
      e.preventDefault();
      row.classList.remove('drag-over');
      if (dragId && dragId !== row.dataset.id) reorderRolesByDrag(dragId, row.dataset.id);
    });
  });
}

// Reinserts the dragged role at the drop target's spot and renumbers every
// non-@everyone role sequentially so the visual order is unambiguous.
async function reorderRolesByDrag(draggedId, targetId) {
  if (!currentServerData) return;
  const ordered = sortedServerRoles().filter(r => r.id !== 'everyone');
  const dragged = ordered.find(r => r.id === draggedId);
  const target = ordered.find(r => r.id === targetId);
  if (!dragged || !target) return;
  if (!isServerOwnerLevel(currentServerData, myUid)) {
    const myTopPos = topRoleOf(currentServerData, myUid).position;
    if (dragged.position >= myTopPos || target.position >= myTopPos) { toast("You can't move roles at or above your highest role.", 'error'); return; }
  }
  const movingDown = ordered.indexOf(dragged) < ordered.indexOf(target);
  ordered.splice(ordered.indexOf(dragged), 1);
  ordered.splice(ordered.indexOf(target) + (movingDown ? 1 : 0), 0, dragged);
  const newRoles = serverRoles(currentServerData).map(r => {
    if (r.id === 'everyone') return r;
    return { ...r, position: ordered.length - ordered.findIndex(x => x.id === r.id) };
  });
  try {
    await db.collection('servers').doc(currentServerId).update({ roles: newRoles });
    currentServerData = { ...currentServerData, roles: newRoles };
    renderRolesPane();
  } catch (e) { toast(e.message || 'Could not reorder roles.', 'error'); }
}

function renderRoleEditView(root) {
  const role = findServerRole(selectedRoleId);
  const isEveryone = role.id === 'everyone';
  const canEdit = canEditRole(role);
  const canManage = hasServerPerm(currentServerData, myUid, 'manageRoles');
  if (roleEditorPendingRoleId !== role.id) { roleEditorPending = roleSnapshotOf(role); roleEditorPendingRoleId = role.id; }
  roleEditorSnapshot = roleSnapshotOf(role);
  if (isEveryone) roleEditorTab = 'permissions';
  const v = roleEditorPending;
  const memberIds = isEveryone ? [] : roleMemberIds(role.id);
  const sideRoles = sortedServerRoles().filter(r => r.id !== 'everyone');
  const isCustomColor = !!v.color && !ROLE_COLOR_PALETTE.includes(v.color);
  const tabBtn = (key, label) => `<button type="button" role="tab" aria-selected="${roleEditorTab === key}" class="dr-tab${roleEditorTab === key ? ' on' : ''}" data-tab="${key}">${label}</button>`;

  const displayPane = `
    <div class="field"><label for="role-name-input">Role Name <span class="dr-req">*</span></label><input type="text" id="role-name-input" maxlength="30" value="${esc(v.name)}"></div>
    <div class="ss-divider"></div>
    <div class="dr-section-title">Role Color <span class="dr-req">*</span></div>
    <p class="ss-hint">Members use the color of the highest role they have on the roles list.</p>
    <div class="dr-color-picker">
      <button type="button" class="dr-color-big${!v.color ? ' on' : ''}" data-color="" style="background:${ROLE_DEFAULT_COLOR}" aria-label="Default color" title="Default">${!v.color ? ROLE_ICONS.check : ''}</button>
      <label class="dr-color-big dr-color-custom${isCustomColor ? ' on' : ''}" id="dr-custom-swatch" style="background:${esc(isCustomColor ? v.color : '#4e5058')}" title="Custom color">
        ${isCustomColor ? ROLE_ICONS.check : ''}<span class="dr-dropper">${ROLE_ICONS.dropper}</span>
        <input type="color" id="role-color-input" value="${esc(v.color || ROLE_DEFAULT_COLOR)}" aria-label="Custom color">
      </label>
      <div class="dr-color-grid">${ROLE_COLOR_PALETTE.map(c => `<button type="button" class="dr-color-sm${v.color === c ? ' on' : ''}" data-color="${c}" style="background:${c}" aria-label="Color ${c}">${v.color === c ? ROLE_ICONS.check : ''}</button>`).join('')}</div>
    </div>
    <div class="ss-divider"></div>
    <div class="dr-toggle-row">
      <div class="dr-toggle-title">Display role members separately from online members</div>
      <label class="toggle-switch"><input type="checkbox" id="role-hoist-input" ${v.hoist ? 'checked' : ''} aria-label="Display role members separately"><span class="toggle-slider"></span></label>
    </div>
    <div class="ss-divider"></div>
    <button type="button" class="ds-btn ds-btn-danger-outline" id="delete-role-btn">Delete Role</button>`;

  const permissionsPane = `
    ${isEveryone ? '<p class="ss-hint dr-everyone-note">This will change the permissions for <b>everyone</b> in this server.</p>' : ''}
    <div class="dr-perm-toolbar">
      <label class="dr-search dr-grow"><span class="sr-only">Search permissions</span><input type="text" id="dr-perm-search" placeholder="Search permissions" value="${esc(rolePermSearch)}" autocomplete="off"><span class="dr-search-icon">${ROLE_ICONS.search}</span></label>
      <button type="button" class="ds-link-btn" id="dr-clear-perms">Clear permissions</button>
    </div>
    ${SERVER_PERMISSION_GROUPS.map(g => `
      <div class="dr-perm-group" data-group="${g.key}">
        <div class="dr-section-title">${esc(g.label)}</div>
        ${SERVER_PERMISSIONS.filter(p => p.group === g.key).map(p => `
          <div class="dr-perm-row" data-search="${esc((p.label + ' ' + p.desc).toLowerCase())}">
            <div class="dr-toggle-row">
              <div class="dr-toggle-title">${esc(p.label)}${UNUSED_PERMISSIONS.has(p.key) ? ' <span class="perm-soon-tag" title="Saved now, takes effect once this feature exists in Frixion">Coming soon</span>' : ''}</div>
              <label class="toggle-switch"><input type="checkbox" data-perm="${p.key}" ${v.permissions.includes(p.key) ? 'checked' : ''} aria-label="${esc(p.label)}"><span class="toggle-slider"></span></label>
            </div>
            <p class="dr-perm-desc">${esc(p.desc)}</p>
          </div>`).join('')}
      </div>`).join('')}
    <div class="dr-empty hidden" id="dr-perm-empty">No permissions match your search.</div>`;

  const membersPane = `
    <div class="dr-perm-toolbar">
      <label class="dr-search dr-grow"><span class="sr-only">Search members</span><input type="text" id="dr-member-search" placeholder="Search Members" value="${esc(roleMemberSearch)}" autocomplete="off"><span class="dr-search-icon">${ROLE_ICONS.search}</span></label>
      ${canEdit ? `<button type="button" class="ds-btn ds-btn-brand" id="dr-add-members-btn">${roleAddMembersOpen ? 'Done' : 'Add Members'}</button>` : ''}
    </div>
    <div class="dr-add-panel${roleAddMembersOpen ? '' : ' hidden'}" id="re-members-add"></div>
    <div class="dr-member-list" id="re-members-current"><div class="dr-empty">Loading members&hellip;</div></div>`;

  const paneHTML = roleEditorTab === 'display' ? displayPane : roleEditorTab === 'members' ? membersPane : permissionsPane;

  root.innerHTML = `
    <div class="dr-edit">
      <aside class="dr-edit-side" aria-label="Roles">
        <div class="dr-edit-side-head">
          <button type="button" class="dr-back" id="dr-back">${ROLE_ICONS.chevronLeft}<span>Back</span></button>
          ${canManage ? `<button type="button" class="dr-icon-btn" id="dr-side-create" title="Create Role" aria-label="Create Role">${ROLE_ICONS.plus}</button>` : ''}
        </div>
        <div class="dr-side-list">
          ${sideRoles.map(r => `<button type="button" class="dr-side-row${r.id === role.id ? ' on' : ''}" data-id="${esc(r.id)}" ${canManage && canEditRole(r) ? 'draggable="true"' : ''}><span class="dr-dot" style="background:${esc(cssColor((r.id === role.id ? v.color : r.color) || ROLE_DEFAULT_COLOR, ROLE_DEFAULT_COLOR))}"></span><span class="dr-side-name">${esc(r.id === role.id ? (v.name || r.name) : r.name)}</span></button>`).join('')}
          <button type="button" class="dr-side-row${isEveryone ? ' on' : ''}" data-id="everyone"><span class="dr-dot" style="background:${ROLE_DEFAULT_COLOR}"></span><span class="dr-side-name">@everyone</span></button>
        </div>
      </aside>
      <section class="dr-edit-main">
        <div class="dr-edit-head"><h3>Edit Role &mdash; <span id="dr-edit-title-name">${esc(isEveryone ? '@everyone' : v.name)}</span></h3></div>
        ${!canEdit ? '<div class="dr-locked">You can only edit roles ranked below your highest role.</div>' : ''}
        <div class="dr-tabs" role="tablist">
          ${!isEveryone ? tabBtn('display', 'Display') : ''}
          ${tabBtn('permissions', 'Permissions')}
          ${!isEveryone ? tabBtn('members', `Manage Members (${memberIds.length})`) : ''}
        </div>
        <div class="dr-pane" id="dr-pane" role="tabpanel">${paneHTML}</div>
      </section>
    </div>
    <div class="ds-unsaved hidden" id="re-unsaved-bar" role="status">
      <span>Careful &mdash; you have unsaved changes!</span>
      <div class="ds-unsaved-actions">
        <button type="button" class="ds-link-btn" id="re-reset-btn">Reset</button>
        <button type="button" class="ds-btn ds-btn-green" id="re-save-btn">Save Changes</button>
      </div>
    </div>`;

  const pending = () => { updateRoleUnsavedBar(); };

  root.querySelectorAll('.dr-tab').forEach(btn => {
    btn.onclick = () => { roleEditorTab = btn.dataset.tab; renderRolesPane(); };
  });
  $('dr-back').onclick = () => {
    if (roleFormIsDirty(roleEditorPending, roleEditorSnapshot)) { flashUnsavedBar(); return; }
    rolesView = 'list'; selectedRoleId = null; resetRoleEditorState(); renderRolesPane();
  };
  if ($('dr-side-create')) $('dr-side-create').onclick = createServerRole;
  root.querySelectorAll('.dr-side-row').forEach(row => {
    row.onclick = () => {
      if (row.dataset.id === role.id) return;
      if (roleFormIsDirty(roleEditorPending, roleEditorSnapshot)) { flashUnsavedBar(); return; }
      openRoleEditor(row.dataset.id);
    };
  });
  wireRoleDrag(root.querySelectorAll('.dr-side-row[draggable]'));

  if (roleEditorTab === 'display' && !isEveryone) {
    $('role-name-input').addEventListener('input', (e) => {
      v.name = e.target.value;
      $('dr-edit-title-name').textContent = v.name;
      const sideName = root.querySelector(`.dr-side-row[data-id="${CSS.escape(role.id)}"] .dr-side-name`);
      if (sideName) sideName.textContent = v.name || role.name;
      pending();
    });
    root.querySelectorAll('.dr-color-sm, .dr-color-big[data-color]').forEach(sw => {
      sw.onclick = () => { if (!canEdit) return; v.color = sw.dataset.color || null; renderRolesPane(); };
    });
    const colorInput = $('role-color-input');
    colorInput.addEventListener('input', () => {
      v.color = colorInput.value;
      $('dr-custom-swatch').style.background = colorInput.value;
      const dot = root.querySelector(`.dr-side-row[data-id="${CSS.escape(role.id)}"] .dr-dot`);
      if (dot) dot.style.background = colorInput.value;
      pending();
    });
    colorInput.addEventListener('change', () => renderRolesPane());
    $('role-hoist-input').onchange = (e) => { v.hoist = e.target.checked; pending(); };
    $('delete-role-btn').onclick = () => {
      confirmAction({
        title: `Delete '${role.name}'`, body: `Are you sure you want to delete the ${role.name} role? This cannot be undone.`, confirmLabel: 'Okay',
        onConfirm: async () => {
          const roles = serverRoles(currentServerData).filter(r => r.id !== role.id);
          const memberRoles = { ...(currentServerData.memberRoles || {}) };
          Object.keys(memberRoles).forEach(uid => { memberRoles[uid] = (memberRoles[uid] || []).filter(id => id !== role.id); });
          try {
            await db.collection('servers').doc(currentServerId).update({ roles, memberRoles });
            currentServerData = { ...currentServerData, roles, memberRoles };
            rolesView = 'list'; selectedRoleId = null; resetRoleEditorState();
            renderRolesPane();
            toast('Role deleted.');
          } catch (e) { toast(e.message || 'Could not delete role.', 'error'); }
        },
      });
    };
  }

  if (roleEditorTab === 'permissions') {
    const applyPermFilter = () => {
      const q = rolePermSearch.trim().toLowerCase();
      let visible = 0;
      root.querySelectorAll('.dr-perm-group').forEach(group => {
        let groupVisible = 0;
        group.querySelectorAll('.dr-perm-row').forEach(row => {
          const show = !q || row.dataset.search.includes(q);
          row.classList.toggle('hidden', !show);
          if (show) groupVisible++;
        });
        group.classList.toggle('hidden', groupVisible === 0);
        visible += groupVisible;
      });
      $('dr-perm-empty').classList.toggle('hidden', visible > 0);
    };
    $('dr-perm-search').oninput = (e) => { rolePermSearch = e.target.value; applyPermFilter(); };
    applyPermFilter();
    root.querySelectorAll('[data-perm]').forEach(cb => {
      cb.onchange = () => {
        const set = new Set(v.permissions);
        if (cb.checked) set.add(cb.dataset.perm); else set.delete(cb.dataset.perm);
        v.permissions = [...set];
        pending();
      };
    });
    $('dr-clear-perms').onclick = () => { if (!canEdit) return; v.permissions = []; renderRolesPane(); };
  }

  if (roleEditorTab === 'members' && !isEveryone) {
    $('dr-member-search').oninput = (e) => { roleMemberSearch = e.target.value; renderRoleMembersTab(role, memberIds, canEdit); };
    if ($('dr-add-members-btn')) $('dr-add-members-btn').onclick = () => { roleAddMembersOpen = !roleAddMembersOpen; renderRolesPane(); };
    renderRoleMembersTab(role, memberIds, canEdit);
  }

  $('re-save-btn').onclick = () => saveRoleEdits(role);
  $('re-reset-btn').onclick = () => { resetRoleEditorState(); renderRolesPane(); };
  updateRoleUnsavedBar();

  if (!canEdit) $('dr-pane').querySelectorAll('input:not([type="text"]), button, #role-name-input').forEach(el => { el.disabled = true; });
}

async function saveRoleEdits(role) {
  if (!currentServerData || !roleEditorPending) return;
  const isEveryone = role.id === 'everyone';
  const state = { ...roleEditorPending, name: isEveryone ? '@everyone' : (roleEditorPending.name || '').trim() };
  if (!state.name) { toast('Enter a role name.'); flashUnsavedBar(); return; }
  if (!canEditRole(role)) { toast('You can only edit roles ranked below your highest role.', 'error'); return; }
  // No privilege escalation: a non-owner can only hand out permissions they hold themselves.
  const mine = serverPermissionsFor(currentServerData, myUid);
  const escalated = state.permissions.filter(p => !mine.has(p) && !(role.permissions || []).includes(p));
  if (escalated.length) { toast("You can't grant permissions you don't have yourself.", 'error'); return; }
  let roles = serverRoles(currentServerData);
  if (!roles.find(r => r.id === role.id)) roles = [...roles, { ...role }];
  roles = roles.map(r => r.id === role.id ? { ...r, ...state } : r);
  try {
    await db.collection('servers').doc(currentServerId).update({ roles });
    currentServerData = { ...currentServerData, roles };
    resetRoleEditorState();
    renderRolesPane();
    toast('Role saved.');
  } catch (e) { toast(e.message || 'Could not save role.', 'error'); }
}

async function renderRoleMembersTab(role, memberIds, canEdit) {
  await Promise.all((currentServerData.members || []).map(uid => getProfile(uid)));
  const currentWrap = $('re-members-current');
  const addWrap = $('re-members-add');
  if (!currentWrap || !addWrap) return;
  const q = roleMemberSearch.trim().toLowerCase();
  const matches = (uid) => {
    const p = profileCache[uid] || { username: uid };
    return !q || displayNameOf(p).toLowerCase().includes(q) || String(p.username || uid).toLowerCase().includes(q);
  };
  const rowHTML = (uid, action) => {
    const p = profileCache[uid] || { username: uid };
    return `<div class="dr-member-row" data-u="${esc(uid)}">
      ${avatarHTML(32, p.avatarColor, initials(p.username || uid), null, p.avatarUrl)}
      <span class="dr-member-names"><b>${esc(displayNameOf(p) || uid)}</b><small>${esc(p.username || uid)}</small></span>
      ${action}
    </div>`;
  };
  const holders = memberIds.filter(matches);
  currentWrap.innerHTML = holders.length
    ? holders.map(uid => rowHTML(uid, canEdit ? `<button type="button" class="dr-member-remove" data-remove-uid="${esc(uid)}" title="Remove member" aria-label="Remove member">${ROLE_ICONS.x}</button>` : '')).join('')
    : `<div class="dr-empty">${memberIds.length ? 'No members match your search.' : 'No members were found. Add members to this role.'}</div>`;
  const others = (currentServerData.members || []).filter(uid => !memberIds.includes(uid) && matches(uid));
  addWrap.innerHTML = `<div class="dr-section-title">Add Members</div>` + (others.length
    ? others.map(uid => rowHTML(uid, `<button type="button" class="ds-btn ds-btn-brand ds-btn-sm" data-add-uid="${esc(uid)}">Add</button>`)).join('')
    : '<div class="dr-empty">Everyone already has this role.</div>');
  if (!canEdit) return;
  currentWrap.querySelectorAll('[data-remove-uid]').forEach(btn => { btn.onclick = () => setMemberRole(btn.dataset.removeUid, role.id, false); });
  addWrap.querySelectorAll('[data-add-uid]').forEach(btn => { btn.onclick = () => setMemberRole(btn.dataset.addUid, role.id, true); });
}

async function setMemberRole(uid, roleId, add) {
  const memberRoles = { ...(currentServerData.memberRoles || {}) };
  const current = memberRoles[uid] || [];
  memberRoles[uid] = add ? [...new Set([...current, roleId])] : current.filter(id => id !== roleId);
  try {
    await db.collection('servers').doc(currentServerId).update({ memberRoles });
    currentServerData = { ...currentServerData, memberRoles };
    renderRolesPane();
  } catch (e) { toast(e.message || 'Could not update roles.', 'error'); }
}

// New roles are created at the bottom of the list (just above @everyone),
// named "new role", and opened straight into the editor — same as Discord.
async function createServerRole() {
  if (!currentServerData) return;
  if (!hasServerPerm(currentServerData, myUid, 'manageRoles')) { toast('You need Manage Roles permission to do that.'); return; }
  if (roleFormIsDirty(roleEditorPending, roleEditorSnapshot)) { flashUnsavedBar(); return; }
  const shifted = serverRoles(currentServerData).map(r => r.id === 'everyone' ? r : { ...r, position: (r.position || 0) + 1 });
  const newRole = {
    id: 'role_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    name: 'new role', color: null, hoist: false, permissions: [], position: 1,
  };
  const roles = [...shifted, newRole];
  try {
    await db.collection('servers').doc(currentServerId).update({ roles });
    currentServerData = { ...currentServerData, roles };
    openRoleEditor(newRole.id);
  } catch (e) { toast(e.message || 'Could not create role.', 'error'); }
}

// ============================================================
// MANAGE MEMBER MODAL (assign roles, kick, ban)
// ============================================================
function openManageMemberModal(uid, server) {
  const p = profileCache[uid] || { username: uid };
  $('manage-member-title').textContent = 'Manage ' + displayNameOf(p);
  const myTop = topRoleOf(server, myUid);
  const canManageRoles = hasServerPerm(server, myUid, 'manageRoles');
  const canKick = hasServerPerm(server, myUid, 'kickMembers');
  const canBan = hasServerPerm(server, myUid, 'banMembers');
  const targetIsOwner = server.ownerId === uid;
  const canTimeout = hasServerPerm(server, myUid, 'timeoutMembers') && uid !== myUid && !targetIsOwner && topRoleOf(server, uid).position < myTop.position;
  const canNick = uid === myUid ? hasServerPerm(server, myUid, 'changeNickname') : hasServerPerm(server, myUid, 'manageNicknames') && !targetIsOwner;
  const tUntil = timeoutUntil(server, uid);
  const assignedIds = (server.memberRoles && server.memberRoles[uid]) || [];
  const assignableRoles = serverRoles(server).filter(r => r.id !== 'everyone').sort((a, b) => b.position - a.position);
  const body = $('manage-member-body');
  body.innerHTML = `
    ${canManageRoles ? `
      <div class="field"><label>Roles</label>
        <div class="role-assign-list">
          ${assignableRoles.map(r => {
            // Can't grant or revoke a role ranked at or above your own —
            // shown but locked, rather than hidden, so it's clear why.
            const locked = r.position >= myTop.position;
            return `<label class="role-perm-row${locked ? ' locked' : ''}">
              <input type="checkbox" data-role-id="${esc(r.id)}" ${assignedIds.includes(r.id) ? 'checked' : ''} ${locked ? 'disabled' : ''}>
              ${roleChipHTML(r)}
            </label>`;
          }).join('') || '<div class="empty">No roles yet — create one in Server Settings → Roles.</div>'}
        </div>
      </div>` : ''}
    ${canTimeout ? `
      <div class="field"><label>Mute${tUntil ? ' <span class="mm-timeout-left">(muted)</span>' : ''}</label>
        <div class="mm-inline-row">
          <button class="btn-secondary" id="mm-timeout-btn">${tUntil ? 'Unmute' : 'Mute'}</button>
        </div>
      </div>` : ''}
    <div class="modal-actions">
      ${canNick ? '<button class="btn-secondary" id="mm-nick-btn">Nickname</button>' : ''}
      ${canKick ? '<button class="btn-secondary" id="mm-kick-btn">Kick</button>' : ''}
      ${canBan ? '<button class="btn-danger" id="mm-ban-btn">Ban</button>' : ''}
      ${canManageRoles ? '<button class="btn-accent-inline" id="mm-save-roles-btn">Save Roles</button>' : ''}
    </div>`;
  if (canManageRoles) {
    $('mm-save-roles-btn').onclick = async () => {
      const checked = [...body.querySelectorAll('[data-role-id]:checked')].map(el => el.dataset.roleId);
      // Roles at/above your own rank that they already held stay put —
      // this dialog can't touch those either way, so it shouldn't be able
      // to silently strip them.
      const untouchable = assignedIds.filter(id => {
        const r = serverRoles(server).find(x => x.id === id);
        return r && r.position >= myTop.position;
      });
      const finalRoles = [...new Set([...checked, ...untouchable])];
      try {
        await db.collection('servers').doc(server.id).update({ memberRoles: { ...(server.memberRoles || {}), [uid]: finalRoles } });
        toast('Roles updated.');
        closeModal('manage-member-modal');
      } catch (e) { toast(e.message || 'Could not update roles.', 'error'); }
    };
  }
  if (canKick) {
    $('mm-kick-btn').onclick = () => {
      confirmAction({
        title: 'Kick Member', body: `Kick ${displayNameOf(p)} from the server? They can rejoin with an invite.`, confirmLabel: 'Kick',
        onConfirm: async () => {
          try {
            await db.collection('servers').doc(server.id).update({ members: FieldValue.arrayRemove(uid) });
            logAudit(server.id, `kicked ${p.username || uid}`);
            toast('Member kicked.');
            closeModal('manage-member-modal');
          } catch (e) { toast(e.message || 'Could not kick member.', 'error'); }
        },
      });
    };
  }
  if (canBan) {
    $('mm-ban-btn').onclick = () => {
      confirmAction({
        title: 'Ban Member', body: `Ban ${displayNameOf(p)} from the server? They won't be able to rejoin with an invite.`, confirmLabel: 'Ban',
        input: { placeholder: 'Reason (optional)', maxLength: 120 },
        onConfirm: async (reason) => {
          try {
            await db.collection('servers').doc(server.id).update({
              members: FieldValue.arrayRemove(uid), bannedUsers: FieldValue.arrayUnion(uid),
              [`banInfo.${uid}`]: { by: myUid, at: Date.now(), reason: reason || '' },
            });
            logAudit(server.id, `banned ${p.username || uid}`);
            toast('Member banned.');
            closeModal('manage-member-modal');
          } catch (e) { toast(e.message || 'Could not ban member.', 'error'); }
        },
      });
    };
  }
  if (canNick) $('mm-nick-btn').onclick = () => { closeModal('manage-member-modal'); openNicknameEditor(server, uid); };
  if (canTimeout) {
    // Mute / Unmute with no timer, the same as /mute and /unmute.
    $('mm-timeout-btn').onclick = async () => {
      try {
        if (tUntil) {
          await db.collection('servers').doc(server.id).update({ [`timeouts.${uid}`]: FieldValue.delete() });
          logAudit(server.id, `unmuted ${p.username || uid}`);
          toast(`${displayNameOf(p)} is unmuted.`);
        } else {
          await db.collection('servers').doc(server.id).update({ [`timeouts.${uid}`]: INDEFINITE_MUTE_UNTIL });
          logAudit(server.id, `muted ${p.username || uid} until unmuted`);
          toast(`${displayNameOf(p)} is muted.`);
        }
        closeModal('manage-member-modal');
      } catch (e) { toast(e.message || 'Could not update the mute.', 'error'); }
    };
  }
  openModal('manage-member-modal');
}

let lastCategoriesList = [];
let collapsedCategories = {};

function subscribeChannels(serverId) {
  if (unsub.channels) unsub.channels();
  if (unsub.categories) unsub.categories();
  unsub.channels = db.collection('servers').doc(serverId).collection('channels').orderBy('createdAt', 'asc')
    .onSnapshot(snap => {
      const channels = [];
      snap.forEach(d => channels.push({ id: d.id, ...d.data() }));
      lastChannelsList = channels;
      renderChannelRows(channels);
      // PC jumps straight into the first channel you can see; on a phone
      // you stay on the channel list and pick one yourself, like Discord.
      const firstVisible = channels.find(c => canViewChannel(c, currentServerData, myUid));
      if (!currentChannelId && firstVisible && !isMobile()) selectChannel(firstVisible);
      else if (!currentChannelId) showWelcome();
      else if (!channels.some(c => c.id === currentChannelId)) {
        if (unsub.messages) { unsub.messages(); unsub.messages = null; }
        currentChannelId = null;
        currentView = 'none';
        showWelcome();
        setMobilePane('list');
        if (firstVisible && !isMobile()) selectChannel(firstVisible);
      } else if (currentView === 'channel') refreshChannelComposerState();
    });
  unsub.categories = db.collection('servers').doc(serverId).collection('categories').orderBy('createdAt', 'asc')
    .onSnapshot(snap => {
      const cats = [];
      snap.forEach(d => cats.push({ id: d.id, ...d.data() }));
      lastCategoriesList = cats;
      renderChannelRows(lastChannelsList);
      populateCategorySelect();
    });
}
function populateCategorySelect() {
  const sel = $('new-channel-category');
  sel.innerHTML = '<option value="">No Category</option>' + lastCategoriesList.map(c => `<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');
}

function renderChannelRows(channels) {
  const wrap = $('channel-rows');
  wrap.innerHTML = '';
  const canManage = currentServerData && hasServerPerm(currentServerData, myUid, 'manageChannels');
  updateChannelManageButtons();
  // Non-managers never even see a restricted channel in the list — for
  // anyone who can manage channels, restricted ones still show (with a
  // lock) so they can actually administer them.
  const visible = canManage ? channels : channels.filter(c => canViewChannel(c, currentServerData, myUid));

  const buildChannelRow = (c) => {
    const restricted = isChannelPrivate(c);
    const row = document.createElement('div');
    row.className = 'channel-row' + (currentChannelId === c.id ? ' active' : '');
    row.innerHTML = `<span class="hash">#</span><span class="cname">${esc(c.name)}</span>` +
      (restricted ? `<span class="i channel-lock-icon" title="Restricted to certain roles">${icon('shield')}</span>` : '') +
      (canManage ? `<span class="channel-perms-btn" title="Channel Permissions">${icon('gear')}</span><span class="del-channel" title="Delete channel">${icon('trash')}</span>` : '');
    row.onclick = () => selectChannel(c);
    if (canManage) {
      row.querySelector('.channel-perms-btn').onclick = (e) => { e.stopPropagation(); openChannelSettings(c); };
      row.querySelector('.del-channel').onclick = (e) => {
        e.stopPropagation();
        confirmAction({
          title: 'Delete Channel', body: `Delete #${c.name}? This cannot be undone.`, confirmLabel: 'Delete Channel',
          onConfirm: async () => {
            const msgSnap = await db.collection('servers').doc(currentServerId).collection('channels').doc(c.id).collection('messages').get();
            await Promise.all(msgSnap.docs.map(m => m.ref.delete()));
            const sid = currentServerId;
            if (currentChannelId === c.id) {
              if (unsub.messages) { unsub.messages(); unsub.messages = null; }
              currentChannelId = null; currentView = 'none'; showWelcome(); setMobilePane('list');
            }
            await db.collection('servers').doc(sid).collection('channels').doc(c.id).delete();
            logAudit(sid, `deleted #${c.name}`);
          },
        });
      };
    }
    return row;
  };

  const uncategorized = visible.filter(c => !c.categoryId);
  uncategorized.forEach(c => wrap.appendChild(buildChannelRow(c)));

  lastCategoriesList.forEach(cat => {
    const inCat = visible.filter(c => c.categoryId === cat.id);
    // An empty category is hidden from regular members, but people who manage channels still see it
    // (otherwise a brand-new category would vanish the moment it was created).
    if (!inCat.length && !canManage) return;
    const header = document.createElement('div');
    const collapsed = !!collapsedCategories[cat.id];
    header.className = 'category-header';
    header.innerHTML = `<svg class="cat-chevron${collapsed ? ' collapsed' : ''}" viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" stroke-width="3"><path d="M6 9l6 6 6-6"/></svg><span class="cat-name">${esc(cat.name)}</span>` +
      (canManage ? `<span class="cat-actions"><span class="cat-add" title="Create channel in ${esc(cat.name)}">+</span><span class="cat-del" title="Delete category">${icon('trash')}</span></span>` : '');
    header.onclick = () => { collapsedCategories[cat.id] = !collapsedCategories[cat.id]; renderChannelRows(lastChannelsList); };
    if (canManage) {
      header.querySelector('.cat-add').onclick = (e) => { e.stopPropagation(); openCreateChannelModal(cat.id); };
      header.querySelector('.cat-del').onclick = (e) => {
        e.stopPropagation();
        confirmAction({
          title: 'Delete Category', body: `Delete the category "${cat.name}"? Its channels are kept and move out of the category.`, confirmLabel: 'Delete Category',
          onConfirm: async () => {
            try {
              const sid = currentServerId;
              const batch = db.batch();
              channels.filter(ch => ch.categoryId === cat.id).forEach(ch => batch.update(db.collection('servers').doc(sid).collection('channels').doc(ch.id), { categoryId: null }));
              batch.delete(db.collection('servers').doc(sid).collection('categories').doc(cat.id));
              await batch.commit();
              logAudit(sid, `deleted category ${cat.name}`);
            } catch (err) { toast(err.message || 'Could not delete the category.', 'error'); }
          },
        });
      };
    }
    wrap.appendChild(header);
    if (!collapsed) inCat.forEach(c => wrap.appendChild(buildChannelRow(c)));
  });
  refreshChannelComposerState();
}

// ---- composer: send permission + slowmode ----
const SLOWMODE_STEPS = [0, 5, 10, 15, 30, 60, 120, 300, 600, 900, 1800, 3600, 7200, 21600];
function formatSlowmode(sec) {
  if (!sec) return 'Off';
  if (sec < 60) return sec + 's';
  if (sec < 3600) return (sec / 60) + 'm';
  return (sec / 3600) + 'h';
}
// Client-side only, like the rest of the app's permission checks; Firestore
// rules are what would make it tamper-proof.
const lastChannelSendAt = {};
let slowmodeTimer = null;
function currentChannelObj() { return lastChannelsList.find(c => c.id === currentChannelId) || null; }
function slowmodeBypass(channel) {
  return ['bypassSlowmode', 'manageChannels', 'manageMessages'].some(p => hasChannelPerm(channel, currentServerData, myUid, p));
}
function slowmodeRemaining(channel) {
  if (!channel || !channel.slowmode || slowmodeBypass(channel)) return 0;
  const last = lastChannelSendAt[channel.id] || 0;
  return Math.max(0, Math.ceil((last + channel.slowmode * 1000 - Date.now()) / 1000));
}
function renderSlowmodeIndicator() {
  const el = $('slowmode-indicator');
  const channel = currentView === 'channel' ? currentChannelObj() : null;
  clearInterval(slowmodeTimer);
  if (!channel || !channel.slowmode) { el.classList.add('hidden'); return; }
  const tick = () => {
    const left = slowmodeRemaining(channel);
    el.classList.remove('hidden');
    el.classList.toggle('active', left > 0);
    el.textContent = slowmodeBypass(channel) ? `Slowmode is ${formatSlowmode(channel.slowmode)} (you are immune)`
      : left > 0 ? `Slowmode: wait ${left}s` : `Slowmode is enabled (${formatSlowmode(channel.slowmode)})`;
    if (left <= 0) clearInterval(slowmodeTimer);
  };
  tick();
  slowmodeTimer = setInterval(tick, 1000);
}
function refreshChannelComposerState() {
  const input = $('composer-input');
  if (currentView !== 'channel') {
    input.disabled = false;
    $('attach-btn').classList.remove('hidden');
    $('sticker-btn').classList.remove('hidden');
    $('gif-btn').classList.remove('hidden');
    $('slowmode-indicator').classList.add('hidden'); $('chat-header-topic').classList.add('hidden');
    updateComposerSendBtn();
    return;
  }
  const channel = currentChannelObj();
  if (!channel) return;
  const canSend = hasChannelPerm(channel, currentServerData, myUid, 'sendMessages');
  const tUntil = isTimedOutHere() ? timeoutUntil(currentServerData, myUid) : 0;
  const muted = isSiteMuted();
  input.disabled = !canSend || !!tUntil || muted;
  input.placeholder = muted ? siteMuteText() : tUntil ? `You are timed out for ${timeoutLeftText(tUntil)}.`
    : canSend ? `Message #${channel.name}` : 'You do not have permission to send messages in this channel.';
  $('attach-btn').classList.toggle('hidden', !canSend || !!tUntil || muted);
  $('sticker-btn').classList.toggle('hidden', !canHere('useExternalStickers'));
  $('gif-btn').classList.toggle('hidden', !canHere('embedLinks'));
  $('chat-header-title').textContent = channel.name;
  $('chat-header-topic').textContent = channel.topic || '';
  $('chat-header-topic').title = channel.topic || '';
  $('chat-header-topic').classList.toggle('hidden', !channel.topic);
  renderSlowmodeIndicator();
  updateComposerSendBtn();
}

// ---- channel settings (Discord-style overview + permission overrides) ----
let csChannel = null;
let csOverwrites = {};
let csTarget = 'everyone';
const csClone = (o) => JSON.parse(JSON.stringify(o || {}));

function openChannelSettings(channel) {
  if (!currentServerData) return;
  if (!hasChannelPerm(channel, currentServerData, myUid, 'manageChannels') && !hasServerPerm(currentServerData, myUid, 'manageChannels')) {
    toast('You need Manage Channels permission to edit this channel.'); return;
  }
  csChannel = channel;
  csOverwrites = csClone(channel.overwrites);
  // Carry the old role-restriction setting over into real overrides.
  if (channel.visibleToRoles && channel.visibleToRoles.length) {
    csOverwrites.everyone = csOverwrites.everyone || { allow: [], deny: [] };
    if (!csOverwrites.everyone.deny.includes('viewChannels')) csOverwrites.everyone.deny.push('viewChannels');
    channel.visibleToRoles.forEach(rid => {
      const o = csOverwrites[rid] = csOverwrites[rid] || { allow: [], deny: [] };
      if (!o.allow.includes('viewChannels')) o.allow.push('viewChannels');
    });
  }
  csTarget = 'everyone';
  $('cs-title').textContent = '# ' + channel.name;
  $('cs-name').value = channel.name;
  $('cs-topic').value = channel.topic || '';
  const idx = Math.max(0, SLOWMODE_STEPS.indexOf(channel.slowmode || 0));
  $('cs-slowmode').value = idx;
  $('cs-slowmode-val').textContent = formatSlowmode(SLOWMODE_STEPS[idx]);
  const canPerms = hasServerPerm(currentServerData, myUid, 'manageRoles') || hasChannelPerm(channel, currentServerData, myUid, 'manageRoles');
  document.querySelector('[data-cs-tab="permissions"]').classList.toggle('hidden', !canPerms);
  openChannelSettingsTab('overview');
  openModal('channel-settings-modal');
}
function openChannelSettingsTab(tab) {
  document.querySelectorAll('.cs-tab').forEach(t => t.classList.toggle('on', t.dataset.csTab === tab));
  $('cs-pane-overview').classList.toggle('hidden', tab !== 'overview');
  $('cs-pane-permissions').classList.toggle('hidden', tab !== 'permissions');
  if (tab === 'permissions') renderChannelPermsPane();
}
document.querySelectorAll('.cs-tab').forEach(t => { t.onclick = () => openChannelSettingsTab(t.dataset.csTab); });
$('cs-slowmode').addEventListener('input', () => { $('cs-slowmode-val').textContent = formatSlowmode(SLOWMODE_STEPS[+$('cs-slowmode').value]); });

function renderChannelPermsPane() {
  const roles = serverRoles(currentServerData);
  const roleById = (id) => id === 'everyone' ? everyoneRole(currentServerData) : roles.find(r => r.id === id);
  Object.keys(csOverwrites).forEach(id => { if (!roleById(id)) delete csOverwrites[id]; });
  const ev = csOverwrites.everyone;
  $('cs-private-toggle').checked = !!(ev && (ev.deny || []).includes('viewChannels'));

  const targets = ['everyone', ...Object.keys(csOverwrites).filter(id => id !== 'everyone')
    .sort((a, b) => (roleById(b).position || 0) - (roleById(a).position || 0))];
  $('cs-target-list').innerHTML = targets.map(id => {
    const r = roleById(id);
    return `<button type="button" role="option" aria-selected="${id === csTarget}" class="cs-target${id === csTarget ? ' on' : ''}" data-target="${esc(id)}">
      <span class="cs-dot" style="background:${esc(cssColor(r.color, '#99aab5'))}"></span><span class="cs-tname">${esc(r.name)}</span>
      ${id !== 'everyone' ? `<span class="cs-rm" data-rm="${esc(id)}" title="Remove override" aria-label="Remove ${esc(r.name)} override">✕</span>` : ''}</button>`;
  }).join('');
  $('cs-target-list').querySelectorAll('[data-target]').forEach(b => { b.onclick = (e) => {
    if (e.target.dataset.rm) { delete csOverwrites[e.target.dataset.rm]; if (csTarget === e.target.dataset.rm) csTarget = 'everyone'; }
    else csTarget = b.dataset.target;
    renderChannelPermsPane();
  }; });

  const addable = roles.filter(r => r.id !== 'everyone' && !csOverwrites[r.id]).sort((a, b) => b.position - a.position);
  $('cs-add-target').innerHTML = `<option value="">+ Add a role</option>` + addable.map(r => `<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');
  $('cs-add-target').classList.toggle('hidden', !addable.length);

  const o = csOverwrites[csTarget] || { allow: [], deny: [] };
  const byGroup = {};
  SERVER_PERMISSIONS.filter(p => CHANNEL_PERMISSION_KEYS.includes(p.key)).forEach(p => { (byGroup[p.group] = byGroup[p.group] || []).push(p); });
  const labels = { general: 'General Channel Permissions', membership: 'Membership Permissions', text: 'Text Channel Permissions', apps: 'Apps Permissions' };
  $('cs-perm-list').innerHTML = Object.keys(byGroup).map(g => `<div class="cs-group-label">${labels[g] || g}</div>` + byGroup[g].map(p => {
    const state = (o.allow || []).includes(p.key) ? 'allow' : (o.deny || []).includes(p.key) ? 'deny' : 'inherit';
    const btn = (v, sym, lbl) => `<button type="button" data-perm="${p.key}" data-v="${v}" class="${state === v ? 'on' : ''}" aria-pressed="${state === v}" aria-label="${lbl} ${esc(CHANNEL_PERM_LABELS[p.key] || p.label)}">${sym}</button>`;
    return `<div class="cs-perm-row"><div class="cs-perm-text"><div class="cs-perm-name">${esc(CHANNEL_PERM_LABELS[p.key] || p.label)}</div><div class="cs-perm-desc">${esc(p.desc)}</div></div>
      <div class="tri">${btn('deny', '✕', 'Deny')}${btn('inherit', '/', 'Inherit')}${btn('allow', '✓', 'Allow')}</div></div>`;
  }).join('')).join('');
  $('cs-perm-list').querySelectorAll('[data-perm]').forEach(b => { b.onclick = () => {
    const cur = csOverwrites[csTarget] = csOverwrites[csTarget] || { allow: [], deny: [] };
    const k = b.dataset.perm;
    cur.allow = (cur.allow || []).filter(x => x !== k);
    cur.deny = (cur.deny || []).filter(x => x !== k);
    if (b.dataset.v === 'allow') cur.allow.push(k);
    if (b.dataset.v === 'deny') cur.deny.push(k);
    renderChannelPermsPane();
  }; });
}
$('cs-add-target').onchange = () => {
  const id = $('cs-add-target').value;
  if (!id) return;
  csOverwrites[id] = { allow: [], deny: [] };
  csTarget = id;
  renderChannelPermsPane();
};
$('cs-private-toggle').onchange = () => {
  const ev = csOverwrites.everyone = csOverwrites.everyone || { allow: [], deny: [] };
  ev.allow = (ev.allow || []).filter(x => x !== 'viewChannels');
  ev.deny = (ev.deny || []).filter(x => x !== 'viewChannels');
  if ($('cs-private-toggle').checked) ev.deny.push('viewChannels');
  renderChannelPermsPane();
};
function channelRef(id) { return db.collection('servers').doc(currentServerId).collection('channels').doc(id); }
$('cs-save-overview').onclick = async () => {
  if (!csChannel) return;
  const name = sanitizeChannelName($('cs-name').value || '');
  if (!name) { toast('Enter a channel name.'); return; }
  try {
    await channelRef(csChannel.id).update({ name, topic: $('cs-topic').value.trim().slice(0, 1024), slowmode: SLOWMODE_STEPS[+$('cs-slowmode').value] });
    $('cs-title').textContent = '# ' + name;
    toast('Channel updated.');
  } catch (e) { toast(e.message || 'Could not save the channel.', 'error'); }
};
$('cs-save-perms').onclick = async () => {
  if (!csChannel) return;
  const clean = {};
  Object.entries(csOverwrites).forEach(([id, o]) => { if ((o.allow || []).length || (o.deny || []).length || id !== 'everyone') clean[id] = { allow: o.allow || [], deny: o.deny || [] }; });
  try {
    await channelRef(csChannel.id).update({ overwrites: clean, visibleToRoles: [] });
    toast('Channel permissions saved.');
  } catch (e) { toast(e.message || 'Could not save channel permissions.', 'error'); }
};
$('cs-delete-btn').onclick = () => {
  if (!csChannel) return;
  const c = csChannel;
  confirmAction({
    title: 'Delete Channel', body: `Delete #${c.name}? This cannot be undone.`, confirmLabel: 'Delete Channel',
    onConfirm: async () => {
      const msgSnap = await channelRef(c.id).collection('messages').get();
      await Promise.all(msgSnap.docs.map(m => m.ref.delete()));
      await channelRef(c.id).delete();
      closeModal('channel-settings-modal');
      if (currentChannelId === c.id) { currentChannelId = null; showWelcome(); }
    },
  });
};

// ---- channel permissions (visibility by role) ----
function openChannelPermsModal(channel) {
  if (!currentServerData) return;
  const roles = serverRoles(currentServerData).filter(r => r.id !== 'everyone').sort((a, b) => b.position - a.position);
  const restrictedTo = channel.visibleToRoles || [];
  $('channel-perms-title').textContent = 'Permissions — #' + channel.name;
  $('channel-perms-body').innerHTML = `
    <p class="desc">Leave everything unchecked for a channel everyone can see. Check one or more roles to hide #${esc(channel.name)} from everyone except those roles (and the server owner).</p>
    <div class="role-assign-list">
      ${roles.map(r => `<label class="role-perm-row">
        <input type="checkbox" data-role-id="${esc(r.id)}" ${restrictedTo.includes(r.id) ? 'checked' : ''}>
        ${roleChipHTML(r)}
      </label>`).join('') || '<div class="empty">No roles yet — create one in Server Settings → Roles.</div>'}
    </div>
    <div class="modal-actions"><button class="btn-accent-inline" id="save-channel-perms-btn">Save</button></div>`;
  $('save-channel-perms-btn').onclick = async () => {
    const checked = [...$('channel-perms-body').querySelectorAll('[data-role-id]:checked')].map(el => el.dataset.roleId);
    try {
      await db.collection('servers').doc(currentServerId).collection('channels').doc(channel.id).update({ visibleToRoles: checked });
      toast('Channel permissions saved.');
      closeModal('channel-perms-modal');
    } catch (e) { toast(e.message || 'Could not save channel permissions.', 'error'); }
  };
  openModal('channel-perms-modal');
}

function openCreateChannelModal(categoryId) {
  if (!currentServerId) return;
  if (!hasServerPerm(currentServerData, myUid, 'manageChannels')) { toast('You need Manage Channels permission to do that.'); return; }
  $('new-channel-name').value = '';
  populateCategorySelect();
  $('new-channel-category').value = categoryId || '';
  openModal('create-channel-modal');
  setTimeout(() => $('new-channel-name').focus(), 30);
}
$('channel-add-btn').onclick = () => openCreateChannelModal(null);

async function createChannelFromModal() {
  const rawName = ($('new-channel-name').value || '').trim();
  if (!rawName) { toast('Enter a channel name.'); return; }
  const name = sanitizeChannelName(rawName);
  const categoryId = $('new-channel-category').value || null;
  if (!currentServerId) return;
  if (!hasServerPerm(currentServerData, myUid, 'manageChannels')) { toast('You need Manage Channels permission to do that.', 'error'); return; }
  const btn = $('confirm-create-channel');
  btn.disabled = true;
  try {
    await db.collection('servers').doc(currentServerId).collection('channels').add({ name, categoryId, autoDelete: true, createdAt: FieldValue.serverTimestamp() });
    logAudit(currentServerId, `created #${name}`);
    closeModal('create-channel-modal');
    toast(`Created #${name}.`);
  } catch (e) { toast(e.message || 'Could not create the channel.', 'error'); }
  finally { btn.disabled = false; }
}
$('confirm-create-channel').onclick = createChannelFromModal;
$('new-channel-name').addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); createChannelFromModal(); } });

$('category-add-btn').onclick = () => {
  if (!currentServerId) return;
  if (!hasServerPerm(currentServerData, myUid, 'manageChannels')) { toast('You need Manage Channels permission to do that.'); return; }
  $('new-category-name').value = '';
  openModal('create-category-modal');
};
async function createCategoryFromModal() {
  const name = ($('new-category-name').value || '').trim().toUpperCase().slice(0, 24);
  if (!name || !currentServerId) { toast('Enter a category name.'); return; }
  if (!hasServerPerm(currentServerData, myUid, 'manageChannels')) { toast('You need Manage Channels permission to do that.', 'error'); return; }
  const btn = $('confirm-create-category');
  btn.disabled = true;
  try {
    await db.collection('servers').doc(currentServerId).collection('categories').add({ name, createdAt: FieldValue.serverTimestamp() });
    logAudit(currentServerId, `created category ${name}`);
    closeModal('create-category-modal');
    toast(`Created category ${name}.`);
  } catch (e) { toast(e.message || 'Could not create the category.', 'error'); }
  finally { btn.disabled = false; }
}
$('confirm-create-category').onclick = createCategoryFromModal;
$('new-category-name').addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); createCategoryFromModal(); } });

function selectChannel(channel) {
  if (!canViewChannel(channel, currentServerData, myUid)) { toast("You don't have access to that channel."); return; }
  clearReplyTarget();
  clearMyTypingDoc();
  exitCommandMode();
  currentChannelId = channel.id;
  currentView = 'channel';
  channelOpenedAt = Date.now();
  subscribeTyping();
  setChatHeaderHash('#', 'channel');
  $('chat-header-title').textContent = channel.name;
  $('composer-input').placeholder = `Message #${channel.name}`;
  refreshChannelComposerState();
  $('members-toggle').classList.remove('hidden');
  applyDefaultMemberListState();
  $('gift-btn').classList.add('hidden');
  showHeaderActions();
  renderChannelRows(lastChannelsList);
  showChat();
  setMobilePane('chat');
  scheduleMsgLoading();
  if (channel.autoDelete !== false) sweepOldMessages(db.collection('servers').doc(currentServerId).collection('channels').doc(channel.id).collection('messages'));
  listenToMessages(db.collection('servers').doc(currentServerId).collection('channels').doc(channel.id).collection('messages'), (snap, first) => {
    if (!first) {
      snap.docChanges().forEach(change => {
        if (change.type !== 'added') return;
        const m = change.doc.data();
        if (m.uid === myUid || isConversationMuted('ch', channel.id)) return;
        // Only brand-new messages ping. An older one can re-enter the window when a newer one is deleted.
        const sentAt = m.createdAt && m.createdAt.toMillis ? m.createdAt.toMillis() : Date.now();
        if (Date.now() - sentAt > 60000) return;
        if (messageTextMentionsMe(m.text || '', m.everyoneBlocked !== true)) playPingSound();
        if (m.tts && m.text && 'speechSynthesis' in window) {
          try { speechSynthesis.speak(new SpeechSynthesisUtterance(`${m.username || 'Someone'} said ${m.text.slice(0, 300)}`)); } catch (e) {}
        }
      });
    }
    const msgs = [];
    snap.forEach(d => msgs.push({ id: d.id, ...d.data() }));
    onMessagesUpdate(msgs);
  });
}

// ============================================================
// CHAT HEADER ACTIONS (mute / pins / search)
// ============================================================
function muteKey() { return currentView === 'channel' ? `frixion_mute:ch:${currentChannelId}` : `frixion_mute:dm:${currentDMId}`; }
function isMuted() { return localStorage.getItem(muteKey()) === '1'; }
// Same underlying localStorage scheme as isMuted() above, but for any
// conversation (not just whichever one is currently open) — needed since
// ping sounds can fire for DMs/servers you aren't actively viewing.
function isConversationMuted(kind, id) { return localStorage.getItem(`frixion_mute:${kind}:${id}`) === '1'; }
function updateMuteIcon() {
  const muted = isMuted();
  $('mute-toggle').querySelector('.i-unmuted').classList.toggle('hidden', muted);
  $('mute-toggle').querySelector('.i-muted').classList.toggle('hidden', !muted);
  $('mute-toggle').classList.toggle('on', muted);
}
$('mute-toggle').onclick = () => {
  const key = muteKey();
  const wasMuted = localStorage.getItem(key) === '1';
  if (wasMuted) localStorage.removeItem(key); else localStorage.setItem(key, '1');
  updateMuteIcon();
  toast(wasMuted ? 'Unmuted.' : 'Muted. You can still open it manually.');
};

function canPin() {
  if (currentView === 'dm' || currentView === 'groupdm') return true;
  return !!(currentServerData && (canHere('pinMessages') || canHere('manageMessages')));
}
$('pins-toggle').onclick = () => {
  renderPinnedList(lastRawMessages.filter(m => m.pinned));
  openModal('pinned-modal');
  refreshPinnedList();
};
function renderPinnedList(pinned) {
  const wrap = $('pinned-list');
  if (!pinned.length) { wrap.innerHTML = '<div class="empty">No pinned messages yet — hover a message and pin it.</div>'; return; }
  wrap.innerHTML = pinned.map(m => {
    const p = profileCache[m.uid] || { username: m.username || 'Unknown User', avatarColor: '#5865f2' };
    return `<div class="pinned-row" data-mid="${esc(m.id)}">
      ${avatarHTML(34, p.avatarColor, initials(p.username), null, p.avatarUrl, p.equippedDecoration, undefined, p.equippedMask)}
      <div class="pr-body">
        <div class="pr-head"><span class="pr-author">${esc(p.username)}</span><span class="pr-time">${timeStr(m.createdAt)}</span></div>
        <div class="pr-text">${m.poll ? `📊 ${esc(m.poll.question)}` : renderMessageText(m.text)}</div>
      </div>
      ${canPin() ? `<span class="pr-unpin" title="Unpin">${icon('trash')}</span>` : ''}
    </div>`;
  }).join('');
  wrap.querySelectorAll('.pr-unpin').forEach(btn => {
    btn.onclick = () => togglePin(btn.closest('.pinned-row').dataset.mid, true);
  });
}
function msgRef(msgId) {
  if (currentView === 'channel') return db.collection('servers').doc(currentServerId).collection('channels').doc(currentChannelId).collection('messages').doc(msgId);
  if (currentView === 'dm') return db.collection('dms').doc(currentDMId).collection('messages').doc(msgId);
  if (currentView === 'groupdm') return db.collection('groupDMs').doc(currentGroupDMId).collection('messages').doc(msgId);
  return null;
}
function msgCollectionRef() {
  if (currentView === 'channel') return db.collection('servers').doc(currentServerId).collection('channels').doc(currentChannelId).collection('messages');
  if (currentView === 'dm') return db.collection('dms').doc(currentDMId).collection('messages');
  if (currentView === 'groupdm') return db.collection('groupDMs').doc(currentGroupDMId).collection('messages');
  return null;
}
// Best-effort, client-triggered cleanup — there's no server/cron here, so a
// conversation's old messages only actually get swept the next time someone
// with auto-delete turned on for it opens the conversation.
const MESSAGE_TTL_MS = 7 * 24 * 60 * 60 * 1000;
async function sweepOldMessages(ref) {
  if (!ref) return;
  try {
    const cutoff = firebase.firestore.Timestamp.fromMillis(Date.now() - MESSAGE_TTL_MS);
    const snap = await ref.where('createdAt', '<', cutoff).get();
    if (snap.empty) return;
    const batch = db.batch();
    snap.forEach(d => batch.delete(d.ref));
    await batch.commit();
  } catch (e) { console.warn('Auto-delete sweep failed', e); }
}
async function togglePin(msgId, forceUnpin) {
  const msg = lastRawMessages.find(m => m.id === msgId);
  const newVal = forceUnpin ? false : !(msg && msg.pinned);
  const ref = msgRef(msgId);
  if (!ref) return;
  try { await ref.update({ pinned: newVal }); } catch (e) { toast('Could not update pin.', 'error'); }
}

let searchActive = false;
$('search-toggle').onclick = () => {
  searchActive = !searchActive;
  $('search-toggle').classList.toggle('on', searchActive);
  $('search-bar').classList.toggle('hidden', !searchActive);
  if (searchActive) { $('search-input').value = ''; $('search-input').focus(); }
  // Search looks through more history than the normal view keeps loaded.
  const SEARCH_WINDOW = 500;
  if (searchActive && hasOlderMessages() && msgLimit < SEARCH_WINDOW) { msgLimit = SEARCH_WINDOW; listenToMessages(msgListen.coll, msgListen.onSnap); }
  renderMessages(lastRawMessages);
};
$('search-close').onclick = () => {
  searchActive = false;
  $('search-toggle').classList.remove('on');
  $('search-bar').classList.add('hidden');
  renderMessages(lastRawMessages);
};
$('search-input').addEventListener('input', () => renderMessages(lastRawMessages));
$('search-input').addEventListener('keydown', (e) => { if (e.key === 'Escape') $('search-close').click(); });

function showHeaderActions() {
  $('mute-toggle').classList.remove('hidden');
  $('pins-toggle').classList.remove('hidden');
  $('search-toggle').classList.remove('hidden');
  $('add-member-toggle').classList.toggle('hidden', currentView !== 'groupdm');
  $('leave-group-toggle').classList.toggle('hidden', currentView !== 'groupdm');
  updateMuteIcon();
  searchActive = false;
  $('search-toggle').classList.remove('on');
  $('search-bar').classList.add('hidden');
}
function hideHeaderActions() {
  $('mute-toggle').classList.add('hidden');
  $('pins-toggle').classList.add('hidden');
  $('search-toggle').classList.add('hidden');
  $('add-member-toggle').classList.add('hidden');
  $('leave-group-toggle').classList.add('hidden');
  $('gift-btn').classList.add('hidden');
  $('search-bar').classList.add('hidden');
}

// Without Read Message History you only see messages sent after you
// opened the channel (plus your own pending ones), same as Discord.
let channelOpenedAt = 0;
function onMessagesUpdate(msgs) {
  if (currentView === 'channel' && !canHere('readMessageHistory')) {
    msgs = msgs.filter(m => {
      if (!m.createdAt) return true;
      const t = m.createdAt.toMillis ? m.createdAt.toMillis() : new Date(m.createdAt).getTime();
      return t >= channelOpenedAt - 2000;
    });
  }
  cancelMsgLoading();
  msgLoadingOlder = false;
  lastRawMessages = msgs;
  renderMessages(msgs);
  if (!$('pinned-modal').classList.contains('hidden')) refreshPinnedList();
}

// ---------- message paging ----------
// A conversation opens with its newest MSG_PAGE messages and scrolling to the top loads MSG_PAGE more. Before, every
// message ever sent was loaded (and read from the database) each time a conversation was opened.
const MSG_PAGE = 100;
let msgLimit = MSG_PAGE;
let msgListen = null;          // { coll, onSnap } for the open conversation, so it can be re-subscribed with a bigger window
let msgKeepFromBottom = null;  // { dist, count }: keeps the view still while older messages are added above it
let msgLoadingOlder = false;
// onSnap(snap, first): `first` is true for the listener's first snapshot (what was already there, not new messages).
function listenToMessages(coll, onSnap) {
  if (!msgListen || msgListen.coll.path !== coll.path) { msgLimit = MSG_PAGE; msgKeepFromBottom = null; msgLoadingOlder = false; }
  if (unsub.messages) unsub.messages();
  msgListen = { coll, onSnap };
  let first = true;
  unsub.messages = coll.orderBy('createdAt', 'asc').limitToLast(msgLimit).onSnapshot(snap => {
    const wasFirst = first;
    first = false;
    onSnap(snap, wasFirst);
  }, err => console.warn('Messages listener stopped.', err));
}
function hasOlderMessages() { return !!msgListen && !!unsub.messages && lastRawMessages.length >= msgLimit; }
function loadOlderMessages(minimum) {
  if (!hasOlderMessages() || msgLoadingOlder) return;
  const wrap = $('messages');
  msgLoadingOlder = true;
  msgKeepFromBottom = { dist: wrap.scrollHeight - wrap.scrollTop, count: lastRawMessages.length };
  msgLimit = Math.max(msgLimit + MSG_PAGE, minimum || 0);
  listenToMessages(msgListen.coll, msgListen.onSnap);
}
$('messages').addEventListener('scroll', () => { if (!searchActive && $('messages').scrollTop < 80) loadOlderMessages(); }, { passive: true });

// Pinned messages can be older than the loaded window, so they are fetched on their own.
async function refreshPinnedList() {
  const coll = msgCollectionRef();
  let pinned = lastRawMessages.filter(m => m.pinned);
  if (coll) {
    try {
      const snap = await coll.where('pinned', '==', true).get();
      pinned = [];
      snap.forEach(d => pinned.push({ id: d.id, ...d.data() }));
      const ms = m => (m.createdAt && m.createdAt.toMillis ? m.createdAt.toMillis() : 0);
      if (currentView === 'channel' && !canHere('readMessageHistory')) pinned = pinned.filter(m => ms(m) >= channelOpenedAt - 2000);
      pinned.sort((a, b) => ms(a) - ms(b));
      await Promise.all([...new Set(pinned.map(m => m.uid).filter(Boolean))].map(u => getProfile(u)));
    } catch (e) { console.warn('Could not load pinned messages.', e); }
  }
  const now = msgCollectionRef();
  if (!coll || (now && now.path === coll.path)) renderPinnedList(pinned);   // skip if you switched conversations meanwhile
}

// ============================================================
// MOBILE MESSAGE ACTION SHEET — hold down a message (like Discord
// mobile) to bring up a quick-react row plus a list of actions,
// instead of relying on hover icons that don't really work on touch.
// ============================================================
const QUICK_REACT_EMOJIS = REACT_EMOJIS.slice(0, 6);
let openActionSheet = null;
function closeActionSheet() {
  if (!openActionSheet) return;
  openActionSheet.remove();
  openActionSheet = null;
  document.body.classList.remove('action-sheet-open');
}
function openMessageActionSheet(msgId) {
  const m = lastRawMessages.find(x => x.id === msgId);
  if (!m) return;
  closeActionSheet();
  closeReactPopover();

  const canDel = m.uid === myUid;
  const canEditThis = m.uid === myUid && !m.sticker;
  const pinnable = canPin();

  const backdrop = document.createElement('div');
  backdrop.className = 'action-sheet-backdrop';
  backdrop.innerHTML = `
    <div class="action-sheet">
      <div class="as-quick-react">
        ${QUICK_REACT_EMOJIS.map(e => `<button type="button" class="as-quick-emoji" data-e="${e}">${e}</button>`).join('')}
        <button type="button" class="as-quick-emoji as-more-react" title="More reactions">${icon('plus')}</button>
      </div>
      <div class="as-actions">
        ${canEditThis ? `<button type="button" class="as-item" data-act="edit">${icon('edit')}<span>Edit Message</span></button>` : ''}
        <button type="button" class="as-item" data-act="reply">${icon('reply')}<span>Reply</span></button>
        ${m.text ? `<button type="button" class="as-item" data-act="copy">${icon('copy')}<span>Copy Text</span></button>` : ''}
        ${pinnable ? `<button type="button" class="as-item" data-act="pin">${icon('pin')}<span>${m.pinned ? 'Unpin Message' : 'Pin Message'}</span></button>` : ''}
        ${canDel ? `<button type="button" class="as-item as-danger" data-act="delete">${icon('trash')}<span>Delete Message</span></button>` : ''}
      </div>
    </div>`;
  document.body.appendChild(backdrop);
  document.body.classList.add('action-sheet-open');

  backdrop.addEventListener('click', (e) => { if (e.target === backdrop) closeActionSheet(); });
  backdrop.querySelectorAll('.as-quick-emoji[data-e]').forEach(btn => {
    btn.onclick = () => { toggleReaction(msgId, btn.dataset.e); closeActionSheet(); };
  });
  backdrop.querySelector('.as-more-react').onclick = () => {
    closeActionSheet();
    const anchor = document.querySelector(`.msg-line[data-mid="${CSS.escape(msgId)}"] .react-btn`) || backdrop;
    toggleReactPopover(anchor, msgId);
  };
  backdrop.querySelectorAll('.as-item').forEach(btn => {
    btn.onclick = () => {
      const act = btn.dataset.act;
      closeActionSheet();
      if (act === 'edit') startEditMessage(msgId);
      else if (act === 'reply') setReplyTarget(msgId);
      else if (act === 'copy') copyMessageText(m);
      else if (act === 'pin') togglePin(msgId);
      else if (act === 'delete') deleteMessage(msgId);
    };
  });

  openActionSheet = backdrop;
}
// Long-press detection (touch only) — a firm ~450ms hold on a message
// opens the sheet; moving your finger more than a few px cancels it,
// so it doesn't fire while scrolling.
(function setupMessageLongPress() {
  const wrap = $('messages');
  let timer = null, startX = 0, startY = 0, targetId = null;
  const HOLD_MS = 450, MOVE_TOLERANCE = 10;
  const cancel = () => { if (timer) { clearTimeout(timer); timer = null; } targetId = null; };
  wrap.addEventListener('touchstart', (e) => {
    if (!isMobile() || e.touches.length !== 1) return;
    const line = e.target.closest('.msg-line');
    if (!line || !line.dataset.mid) return;
    targetId = line.dataset.mid;
    startX = e.touches[0].clientX; startY = e.touches[0].clientY;
    timer = setTimeout(() => {
      timer = null;
      if (navigator.vibrate) navigator.vibrate(10);
      openMessageActionSheet(targetId);
    }, HOLD_MS);
  }, { passive: true });
  wrap.addEventListener('touchmove', (e) => {
    if (!timer) return;
    const dx = Math.abs(e.touches[0].clientX - startX), dy = Math.abs(e.touches[0].clientY - startY);
    if (dx > MOVE_TOLERANCE || dy > MOVE_TOLERANCE) cancel();
  }, { passive: true });
  wrap.addEventListener('touchend', cancel);
  wrap.addEventListener('touchcancel', cancel);
})();

// Double-click (PC) / double-tap (phone) a message: your own opens the
// editor, anyone else's starts a reply. Ignored on links, buttons,
// reactions, attachments, and while already editing.
function handleMessageDoubleActivate(line) {
  const mid = line && line.dataset.mid;
  if (!mid || !['channel', 'dm', 'groupdm'].includes(currentView)) return;
  const m = lastRawMessages.find(x => x.id === mid);
  if (!m || m.system) return;
  try { window.getSelection().removeAllRanges(); } catch (e) {}
  if (m.uid === myUid && m.text && !m.sticker && !m.poll) startEditMessage(mid);
  else setReplyTarget(mid);
}
const DOUBLE_ACTIVATE_IGNORE = 'a, button, input, textarea, .reaction, .reactions, .msg-hover-actions, .msg-attachment, .poll-card, .msg-edit-box, .avatar, .author';
(function setupMessageDoubleActivate() {
  const wrap = $('messages');
  wrap.addEventListener('dblclick', (e) => {
    if (e.target.closest(DOUBLE_ACTIVATE_IGNORE)) return;
    handleMessageDoubleActivate(e.target.closest('.msg-line'));
  });
  let lastTapAt = 0, lastTapMid = null, tapX = 0, tapY = 0, moved = false;
  wrap.addEventListener('touchstart', (e) => {
    if (e.touches.length !== 1) return;
    tapX = e.touches[0].clientX; tapY = e.touches[0].clientY; moved = false;
  }, { passive: true });
  wrap.addEventListener('touchmove', (e) => {
    if (Math.abs(e.touches[0].clientX - tapX) > 10 || Math.abs(e.touches[0].clientY - tapY) > 10) moved = true;
  }, { passive: true });
  wrap.addEventListener('touchend', (e) => {
    if (moved || openActionSheet || e.target.closest(DOUBLE_ACTIVATE_IGNORE)) { lastTapAt = 0; return; }
    const line = e.target.closest('.msg-line');
    const mid = line && line.dataset.mid;
    const now = Date.now();
    if (mid && mid === lastTapMid && now - lastTapAt < 320) {
      e.preventDefault();
      lastTapAt = 0; lastTapMid = null;
      handleMessageDoubleActivate(line);
      return;
    }
    lastTapAt = now; lastTapMid = mid;
  });
})();

// Quick delete (PC): press Backspace/Delete while not typing, then click a
// message you're allowed to delete. Stays armed while the key is held and
// for 3s after release; Esc or clicking elsewhere disarms.
let quickDeleteArmed = false, quickDeleteTimer = null;
function setQuickDelete(on) {
  quickDeleteArmed = on;
  clearTimeout(quickDeleteTimer);
  document.body.classList.toggle('quick-delete-armed', on);
}
function isTypingTarget(el) {
  return !!el && (el.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName));
}
document.addEventListener('keydown', (e) => {
  if ((e.key === 'Backspace' || e.key === 'Delete') && !isTypingTarget(document.activeElement)
      && ['channel', 'dm', 'groupdm'].includes(currentView) && !document.querySelector('.modal-overlay:not(.hidden)')) {
    e.preventDefault();
    setQuickDelete(true);
  } else if (e.key === 'Escape' && quickDeleteArmed) setQuickDelete(false);
});
document.addEventListener('keyup', (e) => {
  if ((e.key === 'Backspace' || e.key === 'Delete') && quickDeleteArmed) {
    clearTimeout(quickDeleteTimer);
    quickDeleteTimer = setTimeout(() => setQuickDelete(false), 3000);
  }
});
$('messages').addEventListener('click', (e) => {
  if (!quickDeleteArmed) return;
  const line = e.target.closest('.msg-line');
  const m = line && lastRawMessages.find(x => x.id === line.dataset.mid);
  if (!m) { setQuickDelete(false); return; }
  e.preventDefault(); e.stopPropagation();
  const canDelete = m.uid === myUid || (currentView === 'channel' && currentServerData && canHere('manageMessages'));
  if (!canDelete) { toast("You can't delete that message.", 'error'); return; }
  deleteMessage(m.id);
}, true);

// Keyboard shortcuts in the composer: ↑ on an empty box edits your last
// message, Esc cancels a reply.
$('composer-input').addEventListener('keydown', (e) => {
  if (mentionState || e.isComposing || e.keyCode === 229) return;
  if (e.key === 'ArrowUp' && !e.target.value && ['channel', 'dm', 'groupdm'].includes(currentView)) {
    const mine = [...lastRawMessages].reverse().find(m => m.uid === myUid && m.text && !m.sticker && !m.poll);
    if (mine) { e.preventDefault(); startEditMessage(mine.id); }
  } else if (e.key === 'Escape' && replyTarget) {
    e.preventDefault();
    clearReplyTarget();
  }
});

// ============================================================
// MEMBER PANEL
// ============================================================
$('members-toggle').onclick = () => {
  const willOpen = !$('app').classList.contains('member-list-open');
  if (!willOpen) { closeMemberPanel(true); if (!isMobile()) memberListManualOverride = false; return; }
  memberListManualOverride = isMobile() ? null : true;   // on a phone it is only open while you are looking at it
  $('app').classList.add('member-list-open');
};
$('member-panel-back').onclick = () => closeMemberPanel(true);
// Phone: drag the member list to the right to put it away. It follows the finger and slides off, or snaps back.
(function setupMemberPanelSwipe() {
  const panel = $('member-panel');
  let startX = 0, startY = 0, dx = 0, mode = '';
  panel.addEventListener('touchstart', e => {
    if (!isMobile() || e.touches.length !== 1) { mode = ''; return; }
    startX = e.touches[0].clientX; startY = e.touches[0].clientY; dx = 0; mode = 'wait';
  }, { passive: true });
  panel.addEventListener('touchmove', e => {
    if (!mode) return;
    dx = e.touches[0].clientX - startX;
    const dy = e.touches[0].clientY - startY;
    if (mode === 'wait') {
      if (Math.abs(dx) < 12 && Math.abs(dy) < 12) return;
      if (Math.abs(dy) > Math.abs(dx) || dx < 0) { mode = ''; return; }   // scrolling the list, or swiping the wrong way
      mode = 'drag'; panel.style.transition = 'none';
    }
    panel.style.transform = `translateX(${Math.max(0, dx)}px)`;
    e.preventDefault();
  }, { passive: false });
  const end = () => {
    if (mode !== 'drag') { mode = ''; return; }
    mode = '';
    if (dx > window.innerWidth * 0.25) closeMemberPanel(true);
    else { panel.style.transition = 'transform .22s cubic-bezier(.22,.8,.3,1)'; panel.style.transform = ''; setTimeout(() => { panel.style.transition = ''; }, 240); }
  };
  panel.addEventListener('touchend', end);
  panel.addEventListener('touchcancel', end);
})();

async function renderMemberPanel(members, ownerId, server) {
  const vanishData = server || (currentView === 'groupdm' ? groupById(currentGroupDMId) : null);
  const iAmVanished = vanishedListFor(vanishData).includes(myUid);
  members = withoutVanished(members || [], vanishData);
  await Promise.all(members.map(uid => getProfile(uid)));
  const canManageMembers = server && ['manageRoles', 'kickMembers', 'banMembers', 'timeoutMembers', 'manageNicknames'].some(k => hasServerPerm(server, myUid, k));
  const online = [], offline = [];
  members.forEach(uid => {
    const p = profileCache[uid] || { username: uid, avatarColor: '#5865f2' };
    const disp = computeDisplayStatus(uid);
    (disp !== 'offline' ? online : offline).push({ uid, p, disp });
  });
  const renderRow = ({ uid, p, disp }) => {
    const roleColor = server ? roleColorFor(server, uid) : null;
    const topRole = server ? memberRolesOf(server, uid).sort((a, b) => b.position - a.position)[0] : null;
    // Anyone with any member-management permission gets a gear on every
    // row except their own and the owner's — you can't kick/ban/re-role
    // someone who outranks or equals you, so it's hidden rather than
    // shown-then-refused.
    const showGear = canManageMembers && uid !== myUid && uid !== ownerId;
    return `
    <div class="member-row" data-u="${esc(uid)}">
      ${avatarHTML(32, p.avatarColor, initials(p.username), disp, p.avatarUrl, p.equippedDecoration, uid, p.equippedMask)}
      <span class="mname${disp !== 'offline' ? ' online-name' : ''}"${roleColor ? ` style="color:${esc(cssColor(roleColor, 'inherit'))}"` : ''}>${esc(displayNameOf(p))}${premiumStar(p)}${roleTag(p)}${botTag(p)}${ownerCrown(uid, ownerId)}${vanishedListFor(vanishData).includes(uid) && (uid === myUid || isOwner) ? `<span class="vanish-tag" title="${uid === myUid ? 'Only you and other owners can see you here' : 'Vanished. Only owners and co-owners can see this'}">Vanished</span>` : ''}</span>
      ${topRole && topRole.color ? roleChipHTML(topRole) : ''}
      ${showGear ? `<span class="member-manage-btn" title="Manage Member" data-manage-uid="${esc(uid)}">${icon('gear')}</span>` : ''}
    </div>`;
  };
  // Roles flagged "Display separately" (hoisted, same idea as Discord)
  // get their own section pulled out of the plain Online list, ranked
  // highest first. Everyone else online falls into a plain "Online"
  // bucket, same as before.
  const hoisted = server ? serverRoles(server).filter(r => r.hoist && r.id !== 'everyone').sort((a, b) => b.position - a.position) : [];
  const claimed = new Set();
  const sections = [];
  hoisted.forEach(role => {
    const rows = online.filter(m => !claimed.has(m.uid) && memberRolesOf(server, m.uid).some(r => r.id === role.id));
    rows.forEach(m => claimed.add(m.uid));
    if (rows.length) sections.push({ label: role.name, count: rows.length, rows });
  });
  const remainingOnline = online.filter(m => !claimed.has(m.uid));
  sections.push({ label: 'Online', count: remainingOnline.length, rows: remainingOnline });
  sections.push({ label: 'Offline', count: offline.length, rows: offline });
  $('member-panel-body').innerHTML = sections.map(s => s.rows.length ? `
    <div class="side-section-label">${esc(s.label)} — ${s.count}</div>
    <div>${s.rows.map(renderRow).join('')}</div>` : '').join('');
  $('member-panel').querySelectorAll('.member-row[data-u]').forEach(row => {
    row.onclick = (e) => { if (e.target.closest('.member-manage-btn')) return; openProfileModal(row.dataset.u); };
  });
  if (server) {
    $('member-panel').querySelectorAll('.member-manage-btn').forEach(btn => {
      btn.onclick = (e) => { e.stopPropagation(); openManageMemberModal(btn.dataset.manageUid, server); };
    });
  }
}

// ============================================================
// CHAT VIEW SWITCH
// ============================================================
// Both of these use a short delay before actually showing a spinner —
// if the data arrives before the delay is up (typical, especially from
// Firestore's local cache), nothing ever flashes on screen at all.
let loadingViewTimer = null;
function scheduleLoadingView() {
  clearTimeout(loadingViewTimer);
  loadingViewTimer = setTimeout(showLoadingView, 150);
}
function cancelLoadingView() { clearTimeout(loadingViewTimer); }

let msgLoadTimer = null;
function scheduleMsgLoading() {
  clearTimeout(msgLoadTimer);
  msgLoadTimer = setTimeout(() => {
    $('messages').innerHTML = `<div class="msg-loading"><div class="spinner small"></div></div>`;
  }, 150);
}
function cancelMsgLoading() { clearTimeout(msgLoadTimer); }

function showWelcome() {
  cancelLoadingView();
  hideMainPageViews();
  $('loading-view').classList.add('hidden');
  $('welcome-view').classList.remove('hidden');
  $('chat-view').classList.add('hidden');
  setChatHeaderHash('');
  $('chat-header-title').textContent = 'Select a conversation';
  $('members-toggle').classList.add('hidden');
  hideHeaderActions();
}
function showChat() {
  cancelLoadingView();
  hideMainPageViews();
  $('loading-view').classList.add('hidden');
  $('welcome-view').classList.add('hidden');
  $('chat-view').classList.remove('hidden');
}
function showLoadingView() {
  cancelLoadingView();
  hideMainPageViews();
  $('welcome-view').classList.add('hidden');
  $('chat-view').classList.add('hidden');
  $('loading-view').classList.remove('hidden');
  $('members-toggle').classList.add('hidden');
  hideHeaderActions();
  setChatHeaderHash('');
  $('chat-header-title').textContent = '';
}

function renderCurrentView() {
  if (currentView === 'channel' || currentView === 'dm' || currentView === 'groupdm') renderMessages(lastRawMessages);
  if (currentView === 'channel' && currentServerData) {
    renderMemberPanel(currentServerData.members || [], currentServerData.ownerId, currentServerData);
  } else if (currentView === 'groupdm') {
    const g = (window.__myGroupDMs || []).find(x => x.id === currentGroupDMId);
    if (g) renderMemberPanel(g.participants || [], g.ownerId);
  }
  renderDMRows();
}

// ============================================================
// MESSAGES
// ============================================================
function reactionEmojiMarkup(e) {
  const custom = /^:(.+):$/.exec(e);
  if (custom && customEmojis[custom[1]]) {
    return `<img class="reaction-emoji-img" src="${customEmojis[custom[1]].dataUrl}" alt=":${esc(custom[1])}:">`;
  }
  return esc(e);
}
function reactionsHTML(reactions) {
  if (!reactions) return '';
  const entries = Object.entries(reactions).filter(([, arr]) => arr && arr.length);
  if (!entries.length) return '';
  return `<div class="reaction-row">` + entries.map(([e, arr]) =>
    `<button type="button" class="reaction-pill${arr.includes(myUid) ? ' mine' : ''}" data-e="${esc(e)}">${reactionEmojiMarkup(e)}<span>${arr.length}</span></button>`
  ).join('') + `</div>`;
}

// The download button is a real link, not script: Chrome only allows a download that starts right at the click, and blocks one that
// starts after a delay ("this site attempted to download multiple files automatically"). For Cloudinary files the link has the
// fl_attachment flag, which makes Cloudinary send the file as a download instead of showing it in the tab. The download attribute
// is ignored for links to another site, so the file name comes from Cloudinary (new uploads keep their real name, see uploadFileToCloudinary).
function attachmentDownloadUrl(url) {
  if (/^https:\/\/res\.cloudinary\.com\//.test(url) && url.includes('/upload/') && !url.includes('fl_attachment')) return url.replace('/upload/', '/upload/fl_attachment/');
  return url;
}
// ---------- audio / video attachments: watch or listen right inside the chat ----------
// The player elements are kept in a cache and put back into each new row, because renderMessages rebuilds the whole list on every
// change (a new message, a reaction...) and a freshly built <video> would restart mid-song. Moving a media element inside the same
// task keeps it playing, so the cache is what lets playback carry on through re-renders.
const AUDIO_FILE_EXT = /\.(mp3|wav|ogg|oga|m4a|aac|flac|opus)$/i;
const VIDEO_FILE_EXT = /\.(mp4|m4v|mov|webm|ogv|mkv|avi)$/i;
function attachmentMediaKind(a) {
  if (!a || !a.url || a.type === 'image') return null;
  const n = a.name || '';
  return AUDIO_FILE_EXT.test(n) ? 'audio' : VIDEO_FILE_EXT.test(n) ? 'video' : null;
}
const msgMediaCache = new Map();     // "messageId:index" -> the <audio>/<video> element
const msgMediaFailed = new Set();    // keys whose file the browser couldn't play (show a note instead)
let msgMediaUsed = new Set();
let msgMediaPausedMusic = false;     // true while the Shop song is paused so a chat video/audio can be heard
function getMsgMediaEl(key, kind, url) {
  msgMediaUsed.add(key);
  if (msgMediaFailed.has(key)) {
    const note = document.createElement('div');
    note.className = 'msg-media-err';
    note.textContent = "Your browser can't play this file here. Use the download button.";
    return note;
  }
  let el = msgMediaCache.get(key);
  if (el && el.dataset.url !== url) { disposeMsgMedia(key); el = null; }
  if (!el) {
    el = document.createElement(kind);
    el.className = 'msg-media msg-media-' + kind;
    el.controls = true; el.preload = 'metadata'; el.dataset.url = url; el.src = url;
    if (kind === 'video') el.playsInline = true;
    el.addEventListener('error', () => {
      msgMediaFailed.add(key); msgMediaCache.delete(key);
      const note = document.createElement('div');
      note.className = 'msg-media-err';
      note.textContent = "Your browser can't play this file here. Use the download button.";
      if (el.isConnected) el.replaceWith(note);
    });
    msgMediaCache.set(key, el);
  }
  return el;
}
function disposeMsgMedia(key) {
  const el = msgMediaCache.get(key);
  msgMediaCache.delete(key);
  if (!el) return;
  try { el.pause(); el.removeAttribute('src'); el.load(); } catch (e) {}
  if (rpcMedia && rpcMedia.el === el) { rpcMedia = null; activityRefresh(); }   // a removed player sends no pause event
}
// Called at the end of every render: players for messages that are no longer on screen are stopped and dropped.
function purgeMsgMedia() {
  [...msgMediaCache.keys()].forEach(k => { if (!msgMediaUsed.has(k)) disposeMsgMedia(k); });
  msgMediaMaybeResumeMusic();
}
function msgMediaMaybeResumeMusic() {
  if (!msgMediaPausedMusic) return;
  if ([...msgMediaCache.values()].some(o => !o.paused && !o.ended)) return;
  msgMediaPausedMusic = false;
  if (typeof musicAudio !== 'undefined' && musicAudio && musicAudio.paused) musicAudio.play().catch(() => {});
}
// One thing plays at a time: starting a chat video/audio pauses any other one and the Shop song, and the song carries on after.
document.addEventListener('play', (e) => {
  const el = e.target;
  if (!el.classList || !el.classList.contains('msg-media')) return;
  msgMediaCache.forEach(o => { if (o !== el && !o.paused) o.pause(); });
  if (typeof musicAudio !== 'undefined' && musicAudio && !musicAudio.paused) { musicAudio.pause(); msgMediaPausedMusic = true; }
  // Activity status: "Watching/Listening to <file name>" while it plays.
  const card = el.closest('.msg-media-card'), nm = card && card.querySelector('.mmc-name');
  const fileName = (nm ? nm.textContent : '').replace(/\.[A-Za-z0-9]{1,5}$/, '').trim();
  rpcMedia = fileName ? { el, type: el.tagName === 'VIDEO' ? 'watching' : 'listening', name: fileName, startedAt: Date.now() } : null;
  activityRefresh();
}, true);
['pause', 'ended'].forEach(ev => document.addEventListener(ev, (e) => {
  if (e.target.classList && e.target.classList.contains('msg-media')) {
    if (rpcMedia && rpcMedia.el === e.target) { rpcMedia = null; activityRefresh(); }
    msgMediaMaybeResumeMusic();
  }
}, true));

function attachmentHTML(m, canDelete) {
  // m.attachments (array) covers new multi-image messages; m.attachment
  // (singular) is kept for backward compatibility with older messages.
  const atts = m.attachments || (m.attachment ? [m.attachment] : []);
  if (atts.length) {
    const gridCls = atts.length > 1 ? ' msg-attachment-grid' : '';
    return `<div class="msg-attachment${gridCls}">` + atts.map((a, i) => {
      const url = safeUrl(a && a.url, 'media');
      if (!url) return '';
      const delBtn = canDelete ? `<button type="button" class="msg-att-del" data-attidx="${i}" title="Delete this image">${icon('trash')}</button>` : '';
      if (a.type === 'image') return `<div class="msg-att-item"><img src="${esc(url)}" alt="${esc(a.name)}" loading="lazy">${delBtn}</div>`;
      const dlHref = esc(attachmentDownloadUrl(url)), dlName = esc(a.name || 'file');
      const kind = attachmentMediaKind(a);
      // Audio and video play right here. The file name and a download button sit under the player.
      if (kind) return `<div class="msg-att-item is-media"><div class="msg-media-card is-${kind}">
          <div class="msg-media-slot" data-mkey="${esc((m.id || 'x') + ':' + i)}" data-kind="${kind}" data-url="${esc(url)}"></div>
          <div class="msg-media-cap"><span class="mfc-icon">${icon('file')}</span><span class="mmc-name">${dlName}</span><span class="mmc-size">${esc(humanFileSize(a.size || 0))}</span>
            <a class="msg-media-dl" href="${dlHref}" download="${dlName}" rel="noopener" title="Download ${dlName}" aria-label="Download ${dlName}">${icon('download')}</a></div>
        </div>${delBtn}</div>`;
      // Other files: clicking the card downloads it (it no longer opens the Cloudinary page in a new tab).
      return `<div class="msg-att-item is-file"><a class="msg-file-card" href="${dlHref}" download="${dlName}" rel="noopener">
            <span class="mfc-icon">${icon('file')}</span>
            <span class="mfc-body"><span class="mfc-name">${esc(a.name)}</span><span class="mfc-size">${esc(humanFileSize(a.size || 0))}</span></span>
          </a><a class="msg-att-dl" href="${dlHref}" download="${dlName}" rel="noopener" title="Download ${dlName}" aria-label="Download ${dlName}">${icon('download')}</a>${delBtn}</div>`;
    }).join('') + `</div>`;
  }
  if (m.gifUrl) {
    return `<div class="msg-attachment"><img src="${esc(m.gifUrl)}" alt="GIF" loading="lazy"></div>`;
  }
  return '';
}

// ---------- polls (the message-card side — creation is up near the composer) ----------
function pollExpiresAtMs(poll) {
  return poll.expiresAt && typeof poll.expiresAt.toMillis === 'function' ? poll.expiresAt.toMillis() : (poll.expiresAt || 0);
}
function pollTimeLeft(expiresAtMs) {
  const ms = expiresAtMs - Date.now();
  if (ms <= 0) return 'Final results';
  const mins = Math.round(ms / 60000);
  if (mins < 60) return `${mins} minute${mins === 1 ? '' : 's'} left`;
  const hours = Math.round(mins / 60);
  if (hours < 24) return `${hours} hour${hours === 1 ? '' : 's'} left`;
  const days = Math.round(hours / 24);
  return `${days} day${days === 1 ? '' : 's'} left`;
}
// A poll answer's emoji is either a plain unicode character or a custom
// emoji shortcode (":name:") picked from the real emoji picker — render
// either the same way messages do.
function emojiTokenHTML(token) {
  if (!token) return '';
  const m = /^:([a-z0-9_]+):$/i.exec(token);
  if (m && customEmojis[m[1].toLowerCase()]) {
    const ce = customEmojis[m[1].toLowerCase()];
    return `<img class="custom-emoji" src="${esc(ce.dataUrl)}" alt=":${esc(ce.name)}:" title=":${esc(ce.name)}:">`;
  }
  return esc(token);
}
function pollHTML(m) {
  const poll = m.poll;
  if (!poll) return '';
  const votes = poll.votes || {};
  const counts = poll.answers.map((_, i) => Object.values(votes).filter(arr => Array.isArray(arr) && arr.includes(i)).length);
  const totalVoters = Object.keys(votes).length;
  const totalVotes = counts.reduce((a, b) => a + b, 0);
  const myVotes = votes[myUid] || [];
  const expiresAtMs = pollExpiresAtMs(poll);
  const expired = Date.now() >= expiresAtMs;
  const topCount = expired && totalVotes > 0 ? Math.max(...counts) : -1;

  const rows = poll.answers.map((ans, i) => {
    const c = counts[i];
    const pct = totalVotes ? Math.round((c / totalVotes) * 100) : 0;
    const mine = myVotes.includes(i);
    const isWinner = expired && totalVotes > 0 && c === topCount;
    return `<button type="button" class="poll-option${mine ? ' voted' : ''}${expired ? ' locked' : ''}${isWinner ? ' winning' : ''}" data-idx="${i}"${expired ? ' disabled' : ''}>
      <span class="poll-option-fill" style="width:${pct}%"></span>
      <span class="poll-option-main">
        <span class="poll-option-check"></span>
        <span class="poll-option-text">${ans.emoji ? `<span class="poll-option-emoji">${emojiTokenHTML(ans.emoji)}</span>` : ''}${esc(ans.text)}</span>
      </span>
      <span class="poll-option-pct">${totalVotes ? pct + '%' : ''}</span>
    </button>`;
  }).join('');

  const footerLeft = `${totalVoters} vote${totalVoters === 1 ? '' : 's'} • ${pollTimeLeft(expiresAtMs)}`;
  return `<div class="poll-card" data-mid="${esc(m.id)}">
    <div class="poll-card-question">${icon('poll')}<span>${esc(poll.question)}</span></div>
    <div class="poll-options">${rows}</div>
    <div class="poll-card-footer"><span>${footerLeft}</span>${poll.allowMultiple ? '<span class="poll-multi-tag">Pick one or more</span>' : ''}</div>
  </div>`;
}
async function togglePollVote(msgId, idx) {
  if (currentView !== 'channel' && currentView !== 'dm' && currentView !== 'groupdm') return;
  const ref = msgRef(msgId);
  if (!ref) return;
  try {
    await db.runTransaction(async (tx) => {
      const snap = await tx.get(ref);
      if (!snap.exists) return;
      const data = snap.data();
      const poll = data.poll;
      if (!poll) return;
      if (Date.now() >= pollExpiresAtMs(poll)) return; // voting closed, no-op
      const votes = { ...(poll.votes || {}) };
      let mine = Array.isArray(votes[myUid]) ? [...votes[myUid]] : [];
      if (poll.allowMultiple) {
        mine = mine.includes(idx) ? mine.filter(i => i !== idx) : [...mine, idx];
      } else {
        mine = (mine.length === 1 && mine[0] === idx) ? [] : [idx];
      }
      if (mine.length) votes[myUid] = mine; else delete votes[myUid];
      tx.update(ref, { 'poll.votes': votes });
    });
  } catch (e) { toast('Could not update your vote.', 'error'); }
}

function purgeResultHTML(m) {
  const n = m.purgeResult.count;
  return `<div class="purge-card">${icon('check')}<span>Deleted <b>${n}</b> message${n === 1 ? '' : 's'}</span></div>`;
}

function buildMessageLineEl(m, canDelete) {
  if (m.ephemeral) {
    const el = document.createElement('div');
    el.className = 'msg-line is-ephemeral';
    el.dataset.mid = m.id;
    el.innerHTML = `<div class="msg-row-wrap"><span class="msg-text">${esc(m.text).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')}</span></div>` +
      `<div class="eph-foot"><span class="eph-eye">${icon('eye')}</span>Only you can see this <span class="eph-dot">•</span> <a href="#" class="eph-dismiss">Dismiss message</a></div>`;
    el.querySelector('.eph-dismiss').onclick = (e) => { e.preventDefault(); dismissEphemeral(m.id); };
    return el;
  }
  const pinnable = canPin();
  const canEditThis = m.uid === myUid && !m.sticker && !m.poll && !m.purgeResult && !m.wordle;
  const line = document.createElement('div');
  line.className = 'msg-line' + (m.pinned ? ' is-pinned' : '');
  line.dataset.mid = m.id;

  // The reply reference is built as its own sibling block, appended before
  // .msg-row-wrap. Earlier attempts positioned the corner connector with a
  // *negative* left offset to reach back into the avatar column — but
  // #messages scrolls vertically (overflow-y: auto) with no overflow-x set,
  // and per the CSS spec that silently forces overflow-x to "auto" too,
  // which was clipping anything positioned left of the row's own edge
  // clean off-screen. That's why it never showed up right. Fixed by
  // keeping the whole reply row — icon included — inside its own normal
  // bounds instead of reaching outside them.
  if (m.replyTo) {
    const rp = profileCache[m.replyTo.uid];
    const avatarUrl = (rp && rp.avatarUrl) || DEFAULT_AVATAR_URL;
    const replyEl = document.createElement('div');
    replyEl.className = 'msg-reply-ref';
    replyEl.innerHTML =
      `<span class="reply-corner-icon"><svg viewBox="0 0 16 16" width="14" height="14"><path d="M5 3 V8 a3 3 0 0 0 3 3 H13" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg></span>` +
      `<img class="reply-avatar" src="${esc(avatarUrl)}" alt="">` +
      `<span class="mrr-user">${esc(m.replyTo.username)}</span>` +
      `<span class="mrr-text">${esc(m.replyTo.text || '')}</span>`;
    replyEl.onclick = () => jumpToMessage(m.replyTo.id);
    line.appendChild(replyEl);
  }

  const rowWrap = document.createElement('div');
  rowWrap.className = 'msg-row-wrap' + (m.sticker ? ' is-sticker' : '');

  const bodyHTML = (m.sticker
    ? `<img class="msg-sticker" src="${esc(m.sticker.dataUrl)}" alt="${esc(m.sticker.name)}" title="${esc(m.sticker.name)}">`
    : m.poll
    ? pollHTML(m)
    : m.purgeResult
    ? purgeResultHTML(m)
    : m.wordle
    ? wordleCardHTML(m)
    : (m.text ? `<span class="msg-text">${renderMessageText(m.text)}</span>${m.edited ? `<span class="edited-tag">(edited)</span>` : ''}` : '') +
      attachmentHTML(m, canDelete));

  rowWrap.innerHTML = bodyHTML +
    `<span class="msg-hover-actions">` +
    `<span class="hover-icon-btn react-btn" title="Add Reaction">${icon('smiley')}</span>` +
    `<span class="hover-icon-btn reply-msg" title="Reply">${icon('reply')}</span>` +
    (canEditThis ? `<span class="hover-icon-btn edit-msg" title="Edit">${icon('edit')}</span>` : '') +
    (pinnable ? `<span class="hover-icon-btn pin-msg${m.pinned ? ' on' : ''}" title="${m.pinned ? 'Unpin' : 'Pin Message'}">${icon('pin')}</span>` : '') +
    (canDelete ? `<span class="hover-icon-btn del-msg" title="Delete">${icon('trash')}</span>` : '') +
    `</span>`;
  rowWrap.querySelector('.react-btn').onclick = (e) => { e.stopPropagation(); toggleReactPopover(e.currentTarget, m.id); };
  rowWrap.querySelector('.reply-msg').onclick = () => setReplyTarget(m.id);
  if (canEditThis) rowWrap.querySelector('.edit-msg').onclick = () => startEditMessage(m.id);
  if (pinnable) rowWrap.querySelector('.pin-msg').onclick = () => togglePin(m.id);
  if (canDelete) rowWrap.querySelector('.del-msg').onclick = () => deleteMessage(m.id);
  // (Anyone who can see a file can download it: the download button on a file card is a plain link, see attachmentDownloadUrl.)
  rowWrap.querySelectorAll('.msg-media-slot').forEach(slot => slot.replaceWith(getMsgMediaEl(slot.dataset.mkey, slot.dataset.kind, slot.dataset.url)));
  rowWrap.querySelectorAll('.msg-att-del').forEach(btn => {
    btn.onclick = (e) => { e.stopPropagation(); deleteMessageAttachment(m.id, parseInt(btn.dataset.attidx, 10)); };
  });
  if (m.poll) {
    rowWrap.querySelectorAll('.poll-option').forEach(btn => {
      btn.onclick = () => togglePollVote(m.id, parseInt(btn.dataset.idx, 10));
    });
  }
  if (m.wordle) {
    const playBtn = rowWrap.querySelector('.wc-play');
    if (playBtn) playBtn.onclick = () => openWordleGame(m);
  }
  if (m.id === editingMessageId) buildEditBoxInto(rowWrap, m);
  line.appendChild(rowWrap);

  const rx = reactionsHTML(m.reactions);
  if (rx) {
    const tmp = document.createElement('div');
    tmp.innerHTML = rx;
    const rxEl = tmp.firstElementChild;
    rxEl.querySelectorAll('.reaction-pill').forEach(btn => { btn.onclick = () => toggleReaction(m.id, btn.dataset.e); });
    line.appendChild(rxEl);
  }
  return line;
}
function jumpToMessage(id) {
  const el = document.querySelector(`.msg-line[data-mid="${CSS.escape(id)}"]`);
  if (!el) { toast('Original message isn\'t loaded here.'); return; }
  el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  el.classList.add('flash-highlight');
  setTimeout(() => el.classList.remove('flash-highlight'), 1200);
}

// Every render gets a number. A render that had to wait for profiles gives up if a newer one started meanwhile
// (a new message arrived, or you switched to another conversation), so an old list can never be drawn over a newer one.
let messagesRenderSeq = 0;
async function renderMessages(rawMsgs) {
  const seq = ++messagesRenderSeq;
  const searching = searchActive;
  const q = searching ? ($('search-input').value || '').trim().toLowerCase() : '';
  let msgs = q ? rawMsgs.filter(m => `${m.text || ''} ${m.poll ? m.poll.question : ''}`.toLowerCase().includes(q)) : rawMsgs;
  if (!searching) {
    // "Only you can see this" messages sit in the list by time but are never stored anywhere.
    const eph = ephemeralsHere();
    if (eph.length) msgs = [...msgs, ...eph].sort((a, b) => ((a.createdAt && a.createdAt.toMillis ? a.createdAt.toMillis() : Date.now()) - (b.createdAt && b.createdAt.toMillis ? b.createdAt.toMillis() : Date.now())));
  }
  if (searching) $('search-count').textContent = q ? `${msgs.length} result${msgs.length === 1 ? '' : 's'}` : '';

  const uids = [...new Set(msgs.flatMap(m => [m.uid, m.replyTo && m.replyTo.uid, ...(m.targets || [])]).filter(Boolean))];
  if (uids.some(u => !profileCache[u])) await Promise.all(uids.map(u => getProfile(u)));
  if (seq !== messagesRenderSeq) return;
  const wrap = $('messages');
  const wasAtBottom = wrap.scrollHeight - wrap.scrollTop - wrap.clientHeight < 80;
  wrap.innerHTML = '';
  msgMediaUsed = new Set();

  if (searching && q && !msgs.length) {
    wrap.innerHTML = '<div class="empty" style="padding:20px 16px;">No messages match your search.</div>';
    purgeMsgMedia();
    return;
  }

  if (!searching && !msgs.length) {
    const name = currentView === 'channel' ? `#${$('chat-header-title').textContent}` : $('chat-header-title').textContent;
    wrap.innerHTML = `
      <div class="convo-start">
        <span class="convo-start-icon">${currentView === 'channel' ? '#' : icon('people')}</span>
        <h2>Welcome to ${esc(name)}!</h2>
        <p>${currentView === 'channel' ? 'This is the start of the channel.' : 'This is the beginning of your conversation.'}</p>
      </div>`;
    purgeMsgMedia();
    return;
  }

  let lastUid = null, lastMillis = 0, lastDay = null, groupEl = null;

  msgs.forEach(m => {
    const millis = m.createdAt && m.createdAt.toMillis ? m.createdAt.toMillis() : Date.now();
    // dayStr() always formats a real date (e.g. "September 2, 2026") — it never
    // returns the word "Today". A message you just sent has no createdAt yet
    // (pending server timestamp), so falling back to the literal word "Today"
    // created a mismatched, brand-new divider that merged once the real
    // timestamp arrived. Fall back to today's *formatted* date instead so it
    // matches the divider your other messages from today are already under.
    const day = dayStr(m.createdAt) || dayStr(new Date(millis));
    if (day !== lastDay) {
      const div = document.createElement('div');
      div.className = 'day-divider';
      div.textContent = day;
      wrap.appendChild(div);
      lastDay = day; lastUid = null;
    }
    if (m.system) {
      wrap.appendChild(buildSystemMessageEl(m));
      lastUid = null; groupEl = null;
      return;
    }
    const p = profileCache[m.uid] || { username: m.username || 'Unknown User', avatarColor: '#5865f2' };
    // A reply always starts a fresh group (own avatar + username), even when
    // the same author sent the message directly above it — otherwise the
    // reply got silently appended into the previous block with no avatar of
    // its own, which not only looks like a mid-group continuation but makes
    // the reply-to relationship far less clear at a glance.
    const sameGroup = !searching && !m.replyTo && m.uid === lastUid && (millis - lastMillis) < 5 * 60 * 1000;
    // In a server channel, Manage Messages (and the owner) can delete
    // anyone's message, not just their own — everywhere else (DMs, group
    // DMs) it stays author-only, since there's no role system there.
    const canDelete = m.uid === myUid ||
      (currentView === 'channel' && currentServerData && hasServerPerm(currentServerData, myUid, 'manageMessages'));

    if (sameGroup && groupEl) {
      groupEl.querySelector('.msg-body').appendChild(buildMessageLineEl(m, canDelete));
    } else {
      groupEl = document.createElement('div');
      groupEl.className = 'msg-group';
      groupEl.dataset.uid = m.uid;
      const body = document.createElement('div');
      body.className = 'msg-body';
      const meta = document.createElement('div');
      meta.className = 'msg-meta';
      const roleColor = (currentView === 'channel' && currentServerData) ? roleColorFor(currentServerData, m.uid) : null;
      meta.innerHTML = `<span class="author${m.uid === myUid ? ' own' : ''}"${roleColor ? ` style="color:${esc(cssColor(roleColor, 'inherit'))}"` : ''}>${esc((currentView === 'channel' && serverNickFor(m.uid)) || displayNameOf(p))}${premiumStar(p)}${roleTag(p)}${botTag(p)}</span><span class="time">${timeStr(m.createdAt)}</span>`;
      body.appendChild(meta);
      body.appendChild(buildMessageLineEl(m, canDelete));
      groupEl.innerHTML = avatarHTML(40, p.avatarColor, initials(p.username), null, p.avatarUrl, p.equippedDecoration, undefined, p.equippedMask);
      groupEl.appendChild(body);
      wrap.appendChild(groupEl);
    }
    lastUid = m.uid; lastMillis = millis;
  });

  purgeMsgMedia();
  if (!searching && msgKeepFromBottom && rawMsgs.length > msgKeepFromBottom.count) {
    wrap.scrollTop = wrap.scrollHeight - msgKeepFromBottom.dist;   // older messages arrived above: stay where you were
    msgKeepFromBottom = null;
  } else if (!searching && (wasAtBottom || msgs.length <= 20)) wrap.scrollTop = wrap.scrollHeight;
}

// ---------- reaction popover (full emoji picker: standard + custom) ----------
let openReactPopover = null;
function toggleReactPopover(anchorEl, msgId) {
  closeReactPopover();
  const pop = document.createElement('div');
  pop.className = 'react-popover full-react-popover';
  pop.innerHTML = `
    <div class="ep-search"><input type="text" class="rp-search" placeholder="Search emoji"></div>
    <div class="ep-cats rp-cats"></div>
    <div class="ep-scroll">
      <div class="ep-section-label">Custom</div>
      <div class="ep-grid rp-custom-grid"></div>
      <div class="rp-standard-sections"></div>
    </div>`;
  document.body.appendChild(pop);

  const r = anchorEl.getBoundingClientRect();
  const pw = 320, ph = Math.min(360, window.innerHeight - 16);
  pop.style.width = pw + 'px';
  pop.style.maxHeight = ph + 'px';
  pop.style.left = Math.max(8, Math.min(r.left, window.innerWidth - pw - 8)) + 'px';
  pop.style.top = Math.max(8, Math.min(r.top - ph - 8, window.innerHeight - ph - 8)) + 'px';

  const doReact = (emojiKey) => { toggleReaction(msgId, emojiKey); closeReactPopover(); };

  function renderGrids(q) {
    q = (q || '').toLowerCase();
    const customNames = Object.keys(customEmojis).filter(n => !q || n.includes(q)).sort();
    const customWrap = pop.querySelector('.rp-custom-grid');
    customWrap.innerHTML = customNames.length
      ? customNames.map(n => `<button type="button" title=":${esc(n)}:"><img src="${esc(customEmojis[n].dataUrl)}" alt=":${esc(n)}:"></button>`).join('')
      : '<div class="ep-empty">No custom emoji yet</div>';
    customWrap.querySelectorAll('button').forEach((btn, i) => { btn.onclick = () => doReact(`:${customNames[i]}:`); });

    const sectionsWrap = pop.querySelector('.rp-standard-sections');
    sectionsWrap.innerHTML = EMOJI_CATEGORIES.map(cat => {
      const names = Object.keys(cat.items).filter(n => !q || n.includes(q));
      if (!names.length) return '';
      return `<div class="ep-section-label" id="rp-sec-${cat.key}">${esc(cat.label)}</div>
        <div class="ep-grid">${names.map(n => `<button type="button" title=":${esc(n)}:">${cat.items[n]}</button>`).join('')}</div>`;
    }).join('') || '<div class="ep-empty">No emoji match "' + esc(q) + '"</div>';
    sectionsWrap.querySelectorAll('button').forEach(btn => { btn.onclick = () => doReact(btn.textContent); });
  }

  pop.querySelector('.rp-cats').innerHTML = EMOJI_CATEGORIES.map(cat => `<button type="button" class="ep-cat-btn" data-cat="${cat.key}" title="${esc(cat.label)}">${cat.icon}</button>`).join('');
  pop.querySelectorAll('.rp-cats .ep-cat-btn').forEach(btn => {
    btn.onclick = () => { const t = pop.querySelector('#rp-sec-' + btn.dataset.cat); if (t) t.scrollIntoView({ block: 'start' }); };
  });
  const searchInput = pop.querySelector('.rp-search');
  searchInput.addEventListener('input', () => renderGrids(searchInput.value));
  renderGrids('');
  setTimeout(() => searchInput.focus(), 0);

  openReactPopover = pop;
  setTimeout(() => document.addEventListener('click', outsideReactClose), 0);
}
function outsideReactClose(e) { if (openReactPopover && !openReactPopover.contains(e.target)) closeReactPopover(); }
function closeReactPopover() {
  if (openReactPopover) { openReactPopover.remove(); openReactPopover = null; document.removeEventListener('click', outsideReactClose); }
}

async function toggleReaction(msgId, emoji) {
  if (currentView !== 'channel' && currentView !== 'dm' && currentView !== 'groupdm') return;
  const ref = msgRef(msgId);
  const msg = lastRawMessages.find(m => m.id === msgId);
  const already = !!(msg && msg.reactions && (msg.reactions[emoji] || []).includes(myUid));
  if (!already) {
    if (isSiteMuted()) { toast(siteMuteText(), 'error'); return; }
    if (isTimedOutHere()) { toast('You cannot react while timed out.', 'error'); return; }
    const isNewEmoji = !(msg && msg.reactions && (msg.reactions[emoji] || []).length);
    if (isNewEmoji && !canHere('addReactions')) { toast('You can only join existing reactions in this channel.', 'error'); return; }
    if (/^:[A-Za-z0-9_]+:$/.test(emoji) && !canHere('useExternalEmoji')) { toast('You cannot use custom emoji in this channel.', 'error'); return; }
  }
  try {
    await ref.update({ [`reactions.${emoji}`]: already ? FieldValue.arrayRemove(myUid) : FieldValue.arrayUnion(myUid) });
    if (!already) db.collection('users').doc(myUid).update({
      'stats.reactionsGiven': FieldValue.increment(1),
      'dailyStats.reactionsGiven': FieldValue.increment(1),
    }).catch(() => {});
  } catch (e) { toast('Could not react.', 'error'); }
}

// Text and images now delete independently: the message-level trash icon
// only clears the text if the message also carries an image/file (the
// attachment stays); the per-image trash icon (see attachmentHTML) only
// drops that one attachment and leaves the text alone. A message with
// only one or the other still deletes outright — nothing would be left.
async function deleteMessage(id) {
  try {
    const ref = msgRef(id);
    if (!ref) return;
    const snap = await ref.get();
    const data = snap.data();
    const hasAttachment = !!(data && ((data.attachments && data.attachments.length) || data.attachment));
    if (hasAttachment && data.text && data.text.trim()) {
      await ref.update({ text: '', edited: false });
    } else {
      await ref.delete();
    }
  } catch (e) { toast('Could not delete message.', 'error'); }
}
async function deleteMessageAttachment(id, idx) {
  try {
    const ref = msgRef(id);
    if (!ref) return;
    const snap = await ref.get();
    const data = snap.data();
    if (!data) return;
    const atts = (data.attachments || (data.attachment ? [data.attachment] : [])).slice();
    if (idx < 0 || idx >= atts.length) return;
    atts.splice(idx, 1);
    if (!atts.length && !(data.text && data.text.trim())) {
      await ref.delete();
    } else {
      await ref.update({ attachments: atts, attachment: FieldValue.delete() });
    }
  } catch (e) { toast('Could not delete image.', 'error'); }
}

// ---------- editing (own messages only) ----------
let editingMessageId = null; // message currently being edited, if any
let editingDraft = '';       // its in-progress text — survives a re-render triggered by unrelated activity (a new message, a reaction, a poll vote) arriving while the user is mid-edit
function buildEditBoxInto(rowWrap, m) {
  const textSpan = rowWrap.querySelector('.msg-text');
  const editedTag = rowWrap.querySelector('.edited-tag');
  const box = document.createElement('div');
  box.className = 'msg-edit-box';
  box.innerHTML = `<textarea class="msg-edit-input" rows="1"></textarea>
    <div class="msg-edit-hint">escape to <a class="med-cancel">cancel</a> &bull; enter to <a class="med-save">save</a></div>`;
  if (textSpan) textSpan.replaceWith(box); else rowWrap.insertBefore(box, rowWrap.firstChild);
  if (editedTag) editedTag.remove();

  const ta = box.querySelector('.msg-edit-input');
  ta.value = editingDraft;
  autoResize(ta);
  ta.addEventListener('input', () => { editingDraft = ta.value; autoResize(ta); });

  const finish = async (save) => {
    if (save) {
      const newText = applyMessageFilter(ta.value.trim());
      if (!newText) { toast('Message can\'t be empty — delete it instead if you want it gone.'); return; }
      if (newText !== (m.text || '')) {
        try { await msgRef(m.id).update({ text: newText, edited: true }); }
        catch (e) { toast('Could not save edit.', 'error'); return; }
      }
    }
    editingMessageId = null;
    editingDraft = '';
    if (isMobile() && useCustomKeyboard()) hideCustomKeyboard();
    renderMessages(lastRawMessages);
  };

  if (isMobile() && useCustomKeyboard()) {
    ta.selectionStart = ta.selectionEnd = ta.value.length;
    ta.readOnly = true;
    // A silent rebuild mid-edit (renderMessages fired for some unrelated
    // reason while this same message was still being edited) replaces this
    // textarea with a fresh one. If the keyboard's already open and driving
    // this exact edit, just repoint it at the new element instead of
    // reopening — reopening would reset shift/caps-lock and the current page.
    if (ckField && editingMessageId === m.id && !$('custom-keyboard').classList.contains('hidden')) {
      ckField.el = ta;
      ckField.onEnter = () => finish(true);
      positionCkCursor();
    } else {
      showCustomKeyboardFor(ta, { onEnter: () => finish(true), multiline: true });
    }
    // Unlike the composer/search boxes, this element doesn't live for the
    // life of the page — it's rebuilt per edit — so it needs its own
    // click-to-reopen wiring rather than the one-time setup those get.
    // Covers tapping back into the field after the keyboard was dismissed
    // by a tap elsewhere (e.g. on the message row outside the edit box).
    ta.addEventListener('click', () => {
      if (useCustomKeyboard() && (!ckField || ckField.el !== ta)) showCustomKeyboardFor(ta, { onEnter: () => finish(true), multiline: true });
    });
  } else {
    ta.focus();
    ta.setSelectionRange(ta.value.length, ta.value.length);
    ta.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); finish(true); }
      else if (e.key === 'Escape') { e.preventDefault(); finish(false); }
    });
  }
  box.querySelector('.med-save').onclick = () => finish(true);
  box.querySelector('.med-cancel').onclick = () => finish(false);
}
function startEditMessage(msgId) {
  const m = lastRawMessages.find(x => x.id === msgId);
  if (!m || m.uid !== myUid) return; // only your own messages, ever
  const line = document.querySelector(`.msg-line[data-mid="${CSS.escape(msgId)}"]`);
  const rowWrap = line && line.querySelector('.msg-row-wrap');
  if (!rowWrap || rowWrap.querySelector('.msg-edit-box')) return;
  closeActionSheet();
  editingMessageId = msgId;
  editingDraft = m.text || '';
  buildEditBoxInto(rowWrap, m);
}

async function copyMessageText(m) {
  try {
    await navigator.clipboard.writeText(m.text || '');
    toast('Copied.');
  } catch (e) { toast('Could not copy — your browser blocked clipboard access.', 'error'); }
}

// ---------- replying ----------
let replyTarget = null;
function setReplyTarget(msgId) {
  const m = lastRawMessages.find(x => x.id === msgId);
  if (!m) return;
  closeActionSheet();
  const uname = (profileCache[m.uid] && displayNameOf(profileCache[m.uid])) || m.username || 'Unknown User';
  const atts = m.attachments || (m.attachment ? [m.attachment] : []);
  const preview = m.sticker ? `Sent a sticker: ${m.sticker.name}` : m.gifUrl ? 'Sent a GIF' :
    m.poll ? `📊 Poll: ${m.poll.question}` :
    m.wordle ? '🟩 Wordle game' :
    atts.length > 1 ? `Sent ${atts.length} files` : atts.length ? `Sent a file: ${atts[0].name || ''}` : (m.text || '');
  replyTarget = { id: m.id, uid: m.uid, username: uname, text: preview.slice(0, 150) };
  $('reply-bar-username').textContent = uname;
  $('reply-bar').classList.remove('hidden');
  if (isMobile() && useCustomKeyboard()) showCustomKeyboard(); else $('composer-input').focus();
}
function clearReplyTarget() {
  replyTarget = null;
  $('reply-bar').classList.add('hidden');
  clearDraftAttachments();
  closeMentionPopup();
}
$('reply-bar-close').onclick = clearReplyTarget;

// ============================================================
// POLLS — create modal, dynamic answer rows, and the emoji picker
// used per answer. Poll *messages* (the interactive card that shows
// up in chat, and voting) live further down near message rendering.
// ============================================================
const ALL_EMOJI_FLAT = EMOJI_CATEGORIES.flatMap(cat => Object.values(cat.items));

function pollAnswerRowHTML() {
  return `<div class="poll-answer-row">
    <button type="button" class="poll-answer-emoji-btn" title="Add an emoji">${icon('smiley')}</button>
    <input type="text" class="poll-answer-input" maxlength="55" placeholder="Type your answer">
    <button type="button" class="poll-answer-remove" title="Remove this answer">${icon('trash')}</button>
  </div>`;
}

function wirePollAnswerRows() {
  const wrap = $('poll-answer-list');
  const rows = [...wrap.querySelectorAll('.poll-answer-row')];
  rows.forEach((row, i) => {
    const removeBtn = row.querySelector('.poll-answer-remove');
    removeBtn.classList.toggle('hidden', rows.length <= 2);
    removeBtn.onclick = () => { row.remove(); wirePollAnswerRows(); updatePollAddButtonState(); };
    const emojiBtn = row.querySelector('.poll-answer-emoji-btn');
    emojiBtn.onclick = (e) => { e.stopPropagation(); openPollEmojiPicker(row, emojiBtn); };
    const input = row.querySelector('.poll-answer-input');
    if (!input.dataset.wired) {
      input.dataset.wired = '1';
      // Discord's own poll composer auto-adds a new empty answer field the
      // moment you start typing in the last one, so you never have to reach
      // for "+ Add another answer" mid-flow — mirror that here.
      input.addEventListener('input', () => {
        const allRows = [...wrap.querySelectorAll('.poll-answer-row')];
        const isLast = row === allRows[allRows.length - 1];
        if (isLast && input.value.trim() && allRows.length < 10) addPollAnswerRow();
      });
    }
  });
}

function addPollAnswerRow() {
  const wrap = $('poll-answer-list');
  if (wrap.querySelectorAll('.poll-answer-row').length >= 10) return;
  wrap.insertAdjacentHTML('beforeend', pollAnswerRowHTML());
  wirePollAnswerRows();
  updatePollAddButtonState();
}

function updatePollAddButtonState() {
  const count = $('poll-answer-list').querySelectorAll('.poll-answer-row').length;
  $('poll-add-answer').classList.toggle('hidden', count >= 10);
}

function openPollEmojiPicker(row, btn) {
  emojiPickerTarget = { type: 'poll', row, btn };
  const panel = $('emoji-picker-panel');
  $('sticker-picker-panel').classList.add('hidden');
  $('gif-picker-panel').classList.add('hidden');
  $('composer-action-menu').classList.add('hidden');
  panel.classList.add('ep-anchored');
  const r = btn.getBoundingClientRect();
  const popW = 340, popH = 320;
  let left = Math.min(r.left, window.innerWidth - popW - 8);
  left = Math.max(8, left);
  let top = r.bottom + 6;
  if (top + popH > window.innerHeight - 8) top = Math.max(8, r.top - popH - 6);
  panel.style.left = `${left}px`;
  panel.style.top = `${top}px`;
  panel.classList.remove('hidden');
  $('emoji-search').value = '';
  renderEmojiPickerGrids();
}
function closePollEmojiPicker() { closeEmojiPickerPanel(); }

function resetPollModal() {
  $('poll-question').value = '';
  $('poll-question-count').textContent = '0/300';
  $('poll-answer-list').innerHTML = '';
  addPollAnswerRow();
  addPollAnswerRow();
  $('poll-duration').value = '86400000';
  $('poll-multiple').checked = false;
  closePollEmojiPicker();
}

function openPollModal() {
  if (!canHere('createPolls')) { toast('You do not have permission to create polls in this channel.', 'error'); return; }
  if (isSiteMuted()) { toast(siteMuteText(), 'error'); return; }
  if (isTimedOutHere()) { toast('You cannot create polls while timed out.', 'error'); return; }
  if (currentView !== 'channel' && currentView !== 'dm' && currentView !== 'groupdm') { toast('Pick a conversation first.'); return; }
  resetPollModal();
  openModal('poll-modal');
  setTimeout(() => $('poll-question').focus(), 50);
}

$('poll-add-answer').onclick = addPollAnswerRow;
$('poll-question').addEventListener('input', () => {
  $('poll-question-count').textContent = `${$('poll-question').value.length}/300`;
});

async function submitPoll() {
  const question = $('poll-question').value.trim();
  if (!question) { toast('Please enter a poll question.', 'error'); return; }
  const answers = [...$('poll-answer-list').querySelectorAll('.poll-answer-row')]
    .map(row => ({ text: row.querySelector('.poll-answer-input').value.trim(), emoji: row.dataset.emoji || null }))
    .filter(a => a.text);
  if (answers.length < 2) { toast('Add at least 2 answers.', 'error'); return; }
  if (currentView !== 'channel' && currentView !== 'dm' && currentView !== 'groupdm') { toast('Pick a conversation first.'); return; }
  const durationMs = parseInt($('poll-duration').value, 10) || 86400000;
  const allowMultiple = $('poll-multiple').checked;
  const payload = {
    uid: myUid, username: myProfile.username, createdAt: FieldValue.serverTimestamp(),
    type: 'poll',
    poll: {
      question, answers, allowMultiple,
      expiresAt: firebase.firestore.Timestamp.fromMillis(Date.now() + durationMs),
      votes: {},
    },
  };
  const btn = $('poll-submit');
  btn.disabled = true;
  try {
    await sendToCurrentConversation(payload);
    closeModal('poll-modal');
    toast('Poll posted.');
  } catch (e) { toast(e.message || 'Could not post the poll.', 'error'); }
  finally { btn.disabled = false; }
}
$('poll-submit').onclick = submitPoll;
// Closing the poll modal (X or Cancel) while its emoji picker is open
// shouldn't leave that panel floating over the chat behind it.
document.querySelectorAll('#poll-modal [data-close="poll-modal"]').forEach(el => {
  el.addEventListener('click', closeEmojiPickerPanel);
});

async function sendToCurrentConversation(payload) {
  if (isSiteMuted()) throw new Error(siteMuteText());
  if (currentView === 'channel' && currentServerData) {
    if (isTimedOutHere()) throw new Error(`You are timed out for ${timeoutLeftText(timeoutUntil(currentServerData, myUid))}.`);
    if (!canHere('sendMessages')) throw new Error('You do not have permission to send messages in this channel.');
    if (payload.sticker && !canHere('useExternalStickers')) throw new Error('You cannot use stickers in this channel.');
    if (payload.gifUrl && !canHere('embedLinks')) throw new Error('You cannot post GIFs or embeds in this channel.');
    if (payload.attachments && payload.attachments.length && !canHere('attachFiles')) throw new Error('You do not have permission to attach files in this channel.');
    if (payload.poll && !canHere('createPolls')) throw new Error('You do not have permission to create polls in this channel.');
  }
  let ref;
  if (currentView === 'channel') {
    ref = await db.collection('servers').doc(currentServerId).collection('channels').doc(currentChannelId).collection('messages').add(payload);
    db.collection('users').doc(myUid).update({ 'dailyStats.channelsMessaged': FieldValue.increment(1) }).catch(() => {});
  } else if (currentView === 'dm') {
    ref = await db.collection('dms').doc(currentDMId).collection('messages').add(payload);
    await db.collection('dms').doc(currentDMId).update({
      updatedAt: FieldValue.serverTimestamp(),
      lastMessage: { text: previewForMessage(payload), username: myProfile.username },
    });
    db.collection('users').doc(myUid).update({ 'dailyStats.dmsMessaged': FieldValue.increment(1) }).catch(() => {});
  } else if (currentView === 'groupdm') {
    ref = await db.collection('groupDMs').doc(currentGroupDMId).collection('messages').add(payload);
    await db.collection('groupDMs').doc(currentGroupDMId).update({
      updatedAt: FieldValue.serverTimestamp(),
      lastMessage: { text: previewForMessage(payload), username: myProfile.username },
    });
    db.collection('users').doc(myUid).update({ 'dailyStats.dmsMessaged': FieldValue.increment(1) }).catch(() => {});
  } else {
    throw new Error('No conversation selected.');
  }
  db.collection('users').doc(myUid).update({
    'stats.messagesSent': FieldValue.increment(1),
    'dailyStats.messagesSent': FieldValue.increment(1),
  }).catch(() => {});
  return ref;
}

// Posts a message on behalf of a bot (e.g. Sapphire). Deliberately doesn't
// reuse sendToCurrentConversation — that function always credits myUid's
// own stats/quests, which shouldn't happen for something the bot sent.
async function postBotMessage(payload) {
  const coll = msgCollectionRef();
  if (!coll) return;
  await coll.add(payload);
  const preview = { text: previewForMessage(payload), username: payload.username };
  if (currentView === 'dm') {
    await db.collection('dms').doc(currentDMId).update({ updatedAt: FieldValue.serverTimestamp(), lastMessage: preview });
  } else if (currentView === 'groupdm') {
    await db.collection('groupDMs').doc(currentGroupDMId).update({ updatedAt: FieldValue.serverTimestamp(), lastMessage: preview });
  }
}

// ============================================================
// VANISH, SFMODE AND JOIN/LEAVE MESSAGES  (v4.14)
// NOTES FOR AI MODELS:
//  - "Vanished" is stored per place as a `vanished` array of usernames on servers/{id} or
//    groupDMs/{id}. A vanished person is still a member: they can read and type, but everyone
//    else's member list, group name and @mention list skips them. This is cosmetic privacy, the
//    app has no backend, so Firestore rules are not involved.
//  - sfmode is `sfMode: true` on users/{name}. staffFlagsFromProfile() turns the effective
//    isAdmin/isOwner flags off while it is on, so every existing staff check behaves like a
//    normal player without being touched. The real rank is still platformRank(myProfile).
//  - System messages (joined / left / added) are normal message docs with `system` set to
//    'join' | 'leave' | 'add', plus `place` ('server' | 'group') and `targets` for 'add'.
//  - Ephemeral messages ("Only you can see this") never touch Firestore. They live in
//    ephemeralMsgs, are merged into the list in renderMessages(), and vanish on reload.
// ============================================================
let ephemeralMsgs = [];
function convKey() { return [currentView, currentServerId, currentChannelId, currentDMId, currentGroupDMId].join('|'); }
function groupById(id) { return (window.__myGroupDMs || []).find(x => x.id === id) || null; }
function vanishedListFor(x) { return x && Array.isArray(x.vanished) ? x.vanished : []; }
function currentVanishData() {
  if (currentView === 'channel') return currentServerData;
  if (currentView === 'groupdm') return groupById(currentGroupDMId);
  return null;
}
// Everyone except you loses vanished people. You always see yourself, so you know it worked.
// Owners and co-owners see each other vanished (only they can vanish), so for them nothing is
// filtered. In sfmode isOwner is false, so an owner in player mode is hidden from like anyone else.
function withoutVanished(list, data) {
  const v = vanishedListFor(data);
  if (isOwner) return list || [];
  return v.length ? (list || []).filter(u => u === myUid || !v.includes(u)) : (list || []);
}
function visibleMemberCount(s) { return withoutVanished(s && s.members, s).length; }
function postEphemeral(text) {
  ephemeralMsgs.push({ id: 'eph-' + Date.now() + Math.random().toString(36).slice(2, 6), key: convKey(), text, ts: Date.now() });
  if (currentView === 'channel' || currentView === 'dm' || currentView === 'groupdm') renderMessages(lastRawMessages);
  else toast(text.replace(/\*\*/g, ''));
}
function dismissEphemeral(id) {
  ephemeralMsgs = ephemeralMsgs.filter(e => e.id !== id);
  renderMessages(lastRawMessages);
}
function ephemeralsHere() {
  const k = convKey();
  return ephemeralMsgs.filter(e => e.key === k).map(e => ({
    id: e.id, ephemeral: true, text: e.text, uid: SAPPHIRE_BOT_UID, username: SAPPHIRE_BOT_PROFILE.username,
    createdAt: { toMillis: () => e.ts, toDate: () => new Date(e.ts) },
  }));
}
async function postSystemMessage(coll, fields) {
  if (!coll) return;
  await coll.add(Object.assign({ createdAt: FieldValue.serverTimestamp() }, fields));
}
const SYS_WELCOMES = [
  '{u} just joined the server. Welcome!', '{u} hopped into the server.', 'Say hi to {u}, who just showed up.',
  'Welcome, {u}. We hope you brought snacks.', '{u} arrived. Everyone act normal.', 'A wild {u} appeared.',
  '{u} is here to hang out.', 'Good to see you, {u}.',
];
function sysNameHTML(uid) { return `<b class="sys-name">${esc(displayNameOf(profileCache[uid] || { username: uid }))}</b>`; }
function systemTextHTML(m) {
  const who = sysNameHTML(m.uid);
  const place = m.place === 'server' ? 'server' : 'group';
  if (m.system === 'leave') return `${who} left the ${place}.`;
  if (m.system === 'add') {
    const names = (m.targets || []).map(sysNameHTML);
    const list = names.length > 1 ? names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1] : (names[0] || 'someone');
    return `${who} added ${list} to the group.`;
  }
  if (place === 'server') {
    let h = 0; String(m.id || m.uid).split('').forEach(c => { h = (h * 31 + c.charCodeAt(0)) >>> 0; });
    return SYS_WELCOMES[h % SYS_WELCOMES.length].replace('{u}', who);
  }
  return `${who} joined the group.`;
}
function systemPlainText(m) { const d = document.createElement('div'); d.innerHTML = systemTextHTML(m); return d.textContent; }
function buildSystemMessageEl(m) {
  const el = document.createElement('div');
  el.className = 'sys-msg sys-' + (m.system === 'leave' ? 'leave' : 'join');
  el.dataset.mid = m.id;
  const arrow = m.system === 'leave'
    ? '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M9 4H5v16h4M15 8l4 4-4 4M19 12H9"/></svg>'
    : '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h10M11 8l4 4-4 4M15 4h4v16h-4"/></svg>';
  el.innerHTML = `<span class="sys-ico">${arrow}</span><span class="sys-text">${systemTextHTML(m)}</span><span class="sys-time">${esc(timeStr(m.createdAt) || timeStr(new Date()))}</span>`;
  return el;
}
// A real server join drops a welcome line in the server's first channel (the oldest one).
async function postServerJoinMessage(serverId) {
  try {
    const snap = await db.collection('servers').doc(serverId).collection('channels').get();
    const ms = d => { const c = d.data().createdAt; return c && c.toMillis ? c.toMillis() : 0; };
    const first = snap.docs.slice().sort((a, b) => ms(a) - ms(b))[0];
    if (!first) return;
    await postSystemMessage(db.collection('servers').doc(serverId).collection('channels').doc(first.id).collection('messages'), { system: 'join', place: 'server', uid: myUid, username: myProfile.username });
  } catch (e) { /* a missing welcome line is not worth an error */ }
}
async function postServerLeaveMessage(serverId) {
  try {
    const snap = await db.collection('servers').doc(serverId).collection('channels').get();
    const ms = d => { const c = d.data().createdAt; return c && c.toMillis ? c.toMillis() : 0; };
    const first = snap.docs.slice().sort((a, b) => ms(a) - ms(b))[0];
    if (!first) return;
    await postSystemMessage(db.collection('servers').doc(serverId).collection('channels').doc(first.id).collection('messages'), { system: 'leave', place: 'server', uid: myUid, username: myProfile.username });
  } catch (e) { /* ignore */ }
}

// /vanish, /unvanish. want: true = vanish, false = unvanish, null = toggle (typing /vanish again unvanishes).
async function runVanishCommand(want) {
  const cmd = want === false ? 'unvanish' : 'vanish';
  if (!isOwner) { toast(`You do not have permission to use /${cmd}.`, 'error'); return; }
  if (currentView !== 'channel' && currentView !== 'groupdm') { postEphemeral('**/vanish** only works in group chats and servers.'); return; }
  const data = currentVanishData();
  if (!data) return;
  const already = vanishedListFor(data).includes(myUid);
  const goVanish = want == null ? !already : want;
  const isServer = currentView === 'channel';
  const name = isServer ? data.name : groupDMDisplayName(data);
  if (goVanish === already) {
    postEphemeral(already ? `You are already vanished in **${name}**. Type **/unvanish** to come back.` : `You are not vanished in **${name}**.`);
    return;
  }
  try {
    const ref = isServer ? db.collection('servers').doc(data.id) : db.collection('groupDMs').doc(data.id);
    await ref.update({ vanished: goVanish ? FieldValue.arrayUnion(myUid) : FieldValue.arrayRemove(myUid) });
    const cur = vanishedListFor(data);
    data.vanished = goVanish ? [...cur.filter(u => u !== myUid), myUid] : cur.filter(u => u !== myUid);
    await postSystemMessage(msgCollectionRef(), { system: goVanish ? 'leave' : 'join', place: isServer ? 'server' : 'group', uid: myUid, username: myProfile.username });
    refreshMembersAfterVanish();
    postEphemeral(goVanish
      ? `You are now vanished in **${name}**. Everyone else sees you as having left and you are gone from the member list, but you can still read and type here. Other owners and co-owners can still see you. Send **/vanish** or **/unvanish** to come back.`
      : `Welcome back. You are visible again in **${name}**.`);
  } catch (e) { toast(e.message || `Could not /${cmd}.`, 'error'); }
}
function refreshMembersAfterVanish() {
  renderDMRows();
  if (currentView === 'channel' && currentServerData) renderMemberPanel(currentServerData.members || [], currentServerData.ownerId, currentServerData);
  else if (currentView === 'groupdm') { const g = groupById(currentGroupDMId); if (g) renderMemberPanel(g.participants || [], g.ownerId); }
}

// /sfmode [on|off|toggle]. "on" = player mode (tag hidden, staff commands off). Plain /sfmode flips it.
async function runSfmodeCommand(arg) {
  if (platformRank(myProfile) < 1) { toast('You do not have permission to use /sfmode.', 'error'); return; }
  const a = (arg || '').toLowerCase();
  if (a && !['on', 'off', 'toggle'].includes(a)) { postEphemeral('Use **/sfmode**, **/sfmode on**, **/sfmode off** or **/sfmode toggle**.'); return; }
  const next = a === 'on' ? true : a === 'off' ? false : !sfMode;
  if (next === sfMode) { postEphemeral(next ? 'sfmode is already **on**. You are acting like a normal player.' : 'sfmode is already **off**. Your staff powers are active.'); return; }
  try {
    await db.collection('users').doc(myUid).update({ sfMode: next });
    myProfile.sfMode = next;
    staffFlagsFromProfile(myProfile);
    profileCache[myUid] = myProfile;
    applyAdminVisibility();
    renderSelfPanel();
    if (currentView === 'channel' || currentView === 'dm' || currentView === 'groupdm') renderCurrentView();
    postEphemeral(next
      ? 'sfmode is **on**. Your staff tag is hidden and staff commands are off, so you are a normal player for now. Send **/sfmode** to switch back.'
      : 'sfmode is **off**. Your staff tag and staff commands are back.');
  } catch (e) { toast(e.message || 'Could not change sfmode.', 'error'); }
}

const SAPPHIRE_PURGE_MAX = 1000; // safety ceiling when an explicit count is given
const SAPPHIRE_PURGE_BATCH_SIZE = 450; // stay safely under Firestore's 500-op batch cap
async function runPurgeCommand(rawCountText) {
  if (!sapphireReady('purge')) return;
  if (currentView !== 'channel' && currentView !== 'dm' && currentView !== 'groupdm') { toast('Pick a conversation first.'); return; }
  const parsed = parseInt(rawCountText, 10);
  const n = Number.isFinite(parsed) && parsed > 0 ? Math.min(SAPPHIRE_PURGE_MAX, parsed) : null; // no count → delete everything
  const coll = msgCollectionRef();
  if (!coll) return;
  try {
    // No count given: /purge wipes the whole conversation, bot messages
    // included. The command echo below is posted *after* this deletion pass
    // so it survives this run, but since the next /purge deletes everything
    // (not just a bounded window), that echo — and this run's confirmation
    // card — get swept up automatically next time, instead of piling up.
    const query = n ? coll.orderBy('createdAt', 'desc').limit(n) : coll;
    const snap = await query.get();
    const docs = snap.docs;
    for (let i = 0; i < docs.length; i += SAPPHIRE_PURGE_BATCH_SIZE) {
      const batch = db.batch();
      docs.slice(i, i + SAPPHIRE_PURGE_BATCH_SIZE).forEach(d => batch.delete(d.ref));
      await batch.commit();
    }
    const purgeText = rawCountText ? `/purge ${rawCountText}` : '/purge';
    const echoRef = await sendToCurrentConversation({
      text: purgeText,
      uid: myUid, username: myProfile.username, createdAt: FieldValue.serverTimestamp(),
    });
    await postBotMessage({
      uid: SAPPHIRE_BOT_UID, username: SAPPHIRE_BOT_PROFILE.username, createdAt: FieldValue.serverTimestamp(),
      purgeResult: { count: docs.length },
      replyTo: echoRef ? { id: echoRef.id, uid: myUid, username: myProfile.username, text: purgeText } : null,
    });
  } catch (e) { toast(e.message || 'Could not purge messages.', 'error'); }
}

// Returns 'platform' (Frixion staff, anywhere) or 'server' (a server owner/mod using the Sapphire
// app their server added), or null after telling the person why they can't.
function sapphireReady(action) {
  const mode = sapphireModeFor(action);
  if (mode) return mode;
  if (currentView === 'channel' && currentServerData && !serverHasApp(currentServerData, 'sapphire')) {
    toast(canAddServerApps(currentServerData) ? 'Add the Sapphire app to this server first (server menu → Add App).' : 'This server has not added the Sapphire app.', 'error');
  } else if (currentView !== 'channel' && action !== 'purge') { /* DMs: do nothing, no message */ }
  else toast(`You do not have permission to use /${action} here.`, 'error');
  return null;
}
// Server-scoped /mute /unmute /ban /unban: only touch people who are in this server, using the
// same rank rules as the member manager (never the owner, never someone at or above your role).
async function runServerModerationCommand(action, rawName, reason) {
  const server = currentServerData;
  const hasReason = action === 'mute' || action === 'ban' || action === 'kick';
  if (!server || !rawName) { toast(`Usage: /${action} <username>${hasReason ? ' [reason]' : ''}`); return; }
  const lower = rawName.toLowerCase();
  const pool = (action === 'unban') ? (server.bannedUsers || []) : (server.members || []);
  const uid = pool.find(u => u.toLowerCase() === lower);
  if (!uid) { toast(action === 'unban' ? `${rawName} is not banned from this server.` : `${rawName} is not in this server.`, 'error'); return; }
  if (action !== 'unban' && action !== 'unmute') {
    if (uid === myUid) { toast(`You can't /${action} yourself.`, 'error'); return; }
    if (server.ownerId === uid) { toast("You can't moderate the server owner.", 'error'); return; }
    const tp = await getProfile(uid);
    const targetIsStaff = !!(tp && (tp.owner || tp.coowner || tp.op));
    if (isFrixionStaff()) {
      // Frixion staff can moderate any member, except staff who outrank them.
      if (targetIsStaff && !canManagePlatformUser(Object.assign({ username: uid }, tp))) { toast("You can't moderate someone who outranks you.", 'error'); return; }
    } else {
      if (topRoleOf(server, uid).position >= topRoleOf(server, myUid).position) { toast("You can't moderate someone who outranks you.", 'error'); return; }
      // A server's Sapphire can't touch Frixion staff.
      if (targetIsStaff) { toast("You can't moderate Frixion staff.", 'error'); return; }
    }
  }
  const why = reason ? ` (${reason})` : '';
  try {
    const ref = db.collection('servers').doc(server.id);
    if (action === 'mute') {
      await ref.update({ [`timeouts.${uid}`]: INDEFINITE_MUTE_UNTIL });
      logAudit(server.id, `muted ${uid} until unmuted${why}`);
      toast(`Muted ${uid} in this server until you unmute them.`);
    } else if (action === 'unmute') {
      await ref.update({ [`timeouts.${uid}`]: FieldValue.delete() });
      logAudit(server.id, `unmuted ${uid}`);
      toast(`Unmuted ${uid}.`);
    } else if (action === 'kick') {
      await ref.update({ members: FieldValue.arrayRemove(uid) });
      logAudit(server.id, `kicked ${uid}${why}`);
      toast(`Kicked ${uid}. They can rejoin with an invite.`);
    } else if (action === 'ban') {
      await ref.update({ members: FieldValue.arrayRemove(uid), bannedUsers: FieldValue.arrayUnion(uid), [`banInfo.${uid}`]: { by: myUid, at: Date.now(), reason: reason || '' } });
      logAudit(server.id, `banned ${uid}${why}`);
      toast(`Banned ${uid} from this server.`);
    } else {
      await ref.update({ bannedUsers: FieldValue.arrayRemove(uid), [`banInfo.${uid}`]: FieldValue.delete() });
      logAudit(server.id, `unbanned ${uid}`);
      toast(`Unbanned ${uid}.`);
    }
  } catch (e) { toast(e.message || `Could not /${action}.`, 'error'); }
}
// /mute /unmute /ban /unban /kick only ever act inside the server they are used in. Frixion-wide mutes
// and bans live in the Admin Panel.
async function runModerationCommand(action, rawName, reason) {
  const mode = sapphireReady(action);
  if (!mode) return;
  return runServerModerationCommand(action, rawName, reason);
}

async function sendMessage() {
  const input = $('composer-input');
  const sendChannel = currentView === 'channel' ? currentChannelObj() : null;
  if (sendChannel && currentServerData && !hasChannelPerm(sendChannel, currentServerData, myUid, 'sendMessages')) {
    toast('You do not have permission to send messages in this channel.');
    return;
  }
  if (sendChannel && input.value.trim() && slowmodeRemaining(sendChannel) > 0) {
    toast(`Slowmode is on. You can send another message in ${slowmodeRemaining(sendChannel)}s.`);
    return;
  }
  if (isSiteMuted()) { toast(siteMuteText(), 'error'); return; }
  if (isTimedOutHere()) {
    toast(`You are timed out in this server for ${timeoutLeftText(timeoutUntil(currentServerData, myUid))}.`, 'error');
    return;
  }
  if (slashState) { selectSlashCommand(slashCandidates[slashIndex]); return; }
  if (cmdMode) { const text = finishCommandMode(); if (text == null) return; input.value = text; }
  let raw = input.value.trim();
  const pendingAttachments = draftAttachments.slice();
  if (pendingAttachments.length && !canHere('attachFiles')) {
    toast('You do not have permission to attach files in this channel.', 'error');
    return;
  }
  if (sendChannel && /^\/(poll|purge|mute|unmute|ban|unban|kick|wordle)\b/i.test(raw) && !canHere('useApplicationCommands')) {
    toast('You do not have permission to use commands in this channel.', 'error');
    return;
  }
  // "/tts hello" speaks the message aloud for everyone viewing the channel.
  let ttsFlag = false;
  if (/^\/tts\s+\S/i.test(raw)) {
    raw = raw.replace(/^\/tts\s+/i, '');
    if (canHere('sendTTS')) ttsFlag = true;
    else toast('You cannot send text-to-speech here — sent as a normal message.');
  }
  if (raw && !canHere('useExternalEmoji')) {
    const usesCustom = (raw.match(/:([A-Za-z0-9_]+):/g) || []).some(code => customEmojis[code.slice(1, -1)]);
    if (usesCustom) { toast('You cannot use custom emoji in this channel.', 'error'); return; }
  }
  // Typing "/poll" alone and hitting Enter opens the poll composer instead
  // of sending it as a message — same trigger word, but it now behaves
  // like every other slash command (acts on send, not on keystroke), and
  // the "/poll" text is cleared the same way any other sent text would be.
  if (!pendingAttachments.length && raw.toLowerCase() === '/poll') {
    input.value = '';
    autoResize(input);
    updateComposerCharCount();
    clearMyTypingDoc();
    closeMentionPopup();
    openPollModal();
    return;
  }
  // /vanish, /unvanish and /sfmode. They are handled here and never posted as text, even when the
  // person is not allowed to use them (they get a "no permission" toast instead).
  const selfCmd = !pendingAttachments.length ? /^\/(vanish|unvanish|sfmode)(?:\s+(\S+))?\s*$/i.exec(raw) : null;
  if (selfCmd) {
    input.value = '';
    autoResize(input);
    updateComposerCharCount();
    clearMyTypingDoc();
    closeMentionPopup();
    const which = selfCmd[1].toLowerCase();
    if (which === 'sfmode') runSfmodeCommand(selfCmd[2]);
    else runVanishCommand(which === 'unvanish' ? false : null);
    return;
  }
  // "/purge <n>" — admin-only, deletes the last n messages in the current
  // conversation and has Sapphire post a confirmation card.
  const purgeMatch = !pendingAttachments.length ? /^\/purge(?:\s+(\d+))?$/i.exec(raw) : null;
  if (purgeMatch) {
    input.value = '';
    autoResize(input);
    updateComposerCharCount();
    clearMyTypingDoc();
    closeMentionPopup();
    runPurgeCommand(purgeMatch[1]);
    return;
  }
  // "/wordle" starts a Wordle game card (the app has to be added to the server first).
  if (!pendingAttachments.length && /^\/wordle$/i.test(raw)) {
    input.value = '';
    autoResize(input);
    updateComposerCharCount();
    clearMyTypingDoc();
    closeMentionPopup();
    startWordleGame();
    return;
  }
  // "/mute <user> [reason]", "/ban <user> [reason]", "/unmute <user>", "/unban <user>" — admin
  // only. No duration: mutes and bans last until they are undone.
  const modMatch = !pendingAttachments.length ? /^\/(mute|unmute|ban|unban|kick)(?:\s+@?(\S+)(?:\s+([\s\S]+))?)?$/i.exec(raw) : null;
  if (modMatch) {
    input.value = '';
    autoResize(input);
    updateComposerCharCount();
    clearMyTypingDoc();
    closeMentionPopup();
    // Moderation commands only mean something inside a server. In a DM or group DM they
    // do nothing at all: no message, no error.
    if (currentView !== 'channel') return;
    runModerationCommand(modMatch[1].toLowerCase(), modMatch[2], (modMatch[3] || '').trim());
    return;
  }
  if (!raw && !pendingAttachments.length) return;
  if (currentView !== 'channel' && currentView !== 'dm' && currentView !== 'groupdm') { toast('Pick a conversation first.'); return; }
  if (raw.length > COMPOSER_MAX_LENGTH) { toast(`Your message is ${raw.length - COMPOSER_MAX_LENGTH} characters over the limit.`, 'error'); return; }
  if (sendChannel && sendChannel.slowmode) { lastChannelSendAt[sendChannel.id] = Date.now(); renderSlowmodeIndicator(); }
  input.value = '';
  autoResize(input);
  updateComposerCharCount();
  clearMyTypingDoc();
  closeMentionPopup();
  draftAttachments = [];
  renderAttachmentDraft();
  const text = raw ? applyMessageFilter(raw) : '';
  const payload = { text, uid: myUid, username: myProfile.username, createdAt: FieldValue.serverTimestamp() };
  if (ttsFlag) payload.tts = true;
  if (text && /(^|[\s(>])@(everyone|here)\b/i.test(text) && !canHere('mentionEveryone')) payload.everyoneBlocked = true;
  if (replyTarget) payload.replyTo = { id: replyTarget.id, uid: replyTarget.uid, username: replyTarget.username, text: replyTarget.text };
  try {
    if (pendingAttachments.length) {
      const bar = $('upload-progress');
      bar.classList.remove('hidden');
      bar.innerHTML = `<div class="spinner small"></div><span>Uploading ${pendingAttachments.length > 1 ? pendingAttachments.length + ' files' : esc(pendingAttachments[0].file.name)}…</span>`;
      const uploaded = [];
      const barText = bar.querySelector('span');
      const total = pendingAttachments.length;
      let n = 0;
      for (const d of pendingAttachments) {
        n++;
        const label = total > 1 ? `Uploading file ${n} of ${total}` : `Uploading ${d.file.name}`;
        const url = await uploadFileGeneric(d.file, d.type === 'image', pct => { if (barText) barText.textContent = `${label}… ${pct}%`; });
        uploaded.push({ url, type: d.type, name: d.file.name, size: d.file.size });
        if (d.previewUrl) URL.revokeObjectURL(d.previewUrl);
      }
      bar.classList.add('hidden');
      payload.attachments = uploaded;
    }
    await sendToCurrentConversation(payload);
    clearReplyTarget();
  } catch (e) {
    $('upload-progress').classList.add('hidden');
    toast(e.message || 'Failed to send message.', 'error');
  }
}
// No explicit Send button — matches Discord's real composer (Enter to send).
$('composer-input').addEventListener('keydown', (e) => {
  if (slashHandleKey(e)) { e.preventDefault(); return; }
  if (mentionState) {
    if (e.key === 'Tab' || e.key === 'Enter') { e.preventDefault(); completeMention(mentionCandidates[mentionSelectedIndex]); return; }
    if (e.key === 'ArrowDown') { e.preventDefault(); mentionSelectedIndex = (mentionSelectedIndex + 1) % mentionCandidates.length; renderMentionPopup(); return; }
    if (e.key === 'ArrowUp') { e.preventDefault(); mentionSelectedIndex = (mentionSelectedIndex - 1 + mentionCandidates.length) % mentionCandidates.length; renderMentionPopup(); return; }
    if (e.key === 'Escape') { closeMentionPopup(); return; }
  }
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); ckWordBoundaryCheck(e.target); sendMessage(); }
});
// Autocorrect on desktop: the word-boundary check only ran through the
// mobile custom keyboard's own key handlers before, so a real keyboard
// typing space never triggered it. This covers that path; Enter is
// handled above right before sendMessage() clears the field.
$('composer-input').addEventListener('keyup', (e) => {
  if (e.key === ' ' && !(ckField && ckField.el === e.target)) ckWordBoundaryCheck(e.target);
});
function autoResize(el) { el.style.height = 'auto'; el.style.height = Math.min(el.scrollHeight, 200) + 'px'; }

// ---------- composer character count ----------
// Positioned with CSS (position:absolute, tucked into the composer's own
// corner) so showing/hiding it never changes the composer bar's height.
const COMPOSER_MAX_LENGTH = 1000;
const COMPOSER_COUNT_SHOW_AT = 100; // only surface it once you're within 100 chars of the cap
function updateComposerCharCount() {
  updateComposerSendBtn();
  const counter = $('composer-char-count');
  if (!counter) return;
  const len = $('composer-input').value.length;
  const remaining = COMPOSER_MAX_LENGTH - len;
  if (remaining > COMPOSER_COUNT_SHOW_AT) { counter.classList.add('hidden'); return; }
  counter.classList.remove('hidden');
  const over = remaining < 0;
  counter.classList.toggle('over-limit', over);
  counter.textContent = over ? `-${Math.abs(remaining)}` : `${remaining}`;
}
// Phone: Discord's round send button, shown once there's something to send (the keyboard's return key still sends too).
// While you type, the gift, GIF and sticker buttons step aside to give the text room, as they do in Discord's app.
function updateComposerSendBtn() {
  const input = $('composer-input'), composer = $('composer');
  const has = !input.disabled && (input.value.trim() !== '' || draftAttachments.length > 0);
  if (composer.classList.contains('has-text') === has) return;
  composer.classList.toggle('has-text', has);
  if (isMobile()) autoResize(input);   // the field just got wider or narrower, so its height may change
}
$('composer-send-btn').onmousedown = e => e.preventDefault();   // keep the keyboard up
$('composer-send-btn').onclick = () => { ckWordBoundaryCheck($('composer-input')); sendMessage(); };

// ---------- typing indicator ----------
// Presence is a small doc per-user under a `typing` subcollection on
// whichever conversation is open. Writes are throttled (not one per
// keystroke) and self-expire client-side; a staleness check on the reading
// side also ignores anything too old, in case a tab closed without ever
// clearing its own doc.
const TYPING_WRITE_INTERVAL_MS = 4000;
const TYPING_IDLE_MS = 5000;
const TYPING_STALE_MS = 8000;
let typingDocRef = null;
let typingIdleTimer = null;
let lastTypingWriteAt = 0;

function typingCollectionRef() {
  if (currentView === 'channel') return db.collection('servers').doc(currentServerId).collection('channels').doc(currentChannelId).collection('typing');
  if (currentView === 'dm') return db.collection('dms').doc(currentDMId).collection('typing');
  if (currentView === 'groupdm') return db.collection('groupDMs').doc(currentGroupDMId).collection('typing');
  return null;
}

function clearMyTypingDoc() {
  if (typingIdleTimer) { clearTimeout(typingIdleTimer); typingIdleTimer = null; }
  if (typingDocRef) { const ref = typingDocRef; typingDocRef = null; ref.delete().catch(() => {}); }
  lastTypingWriteAt = 0;
}

function noteComposerTyping() {
  if (!myUid) return;
  const coll = typingCollectionRef();
  if (!coll) return;
  const hasText = $('composer-input').value.trim().length > 0;
  if (!hasText) { clearMyTypingDoc(); return; }
  const ref = coll.doc(myUid);
  typingDocRef = ref;
  const now = Date.now();
  if (now - lastTypingWriteAt > TYPING_WRITE_INTERVAL_MS) {
    lastTypingWriteAt = now;
    ref.set({ username: myProfile.username, updatedAt: FieldValue.serverTimestamp() }).catch(() => {});
  }
  if (typingIdleTimer) clearTimeout(typingIdleTimer);
  typingIdleTimer = setTimeout(() => { if (typingDocRef) { const r = typingDocRef; typingDocRef = null; r.delete().catch(() => {}); } }, TYPING_IDLE_MS);
}

function renderTypingIndicator(names) {
  const el = $('typing-indicator');
  if (!el) return;
  if (!names.length) { el.innerHTML = ''; return; }
  let text;
  if (names.length === 1) text = `${names[0]} is typing...`;
  else if (names.length === 2) text = `${names[0]} and ${names[1]} are typing...`;
  else text = `${names[0]} and ${names.length - 1} others are typing...`;
  el.innerHTML = `<span class="typing-dots"><span></span><span></span><span></span></span><span>${esc(text)}</span>`;
}

function subscribeTyping() {
  if (unsub.typing) { unsub.typing(); unsub.typing = null; }
  const coll = typingCollectionRef();
  if (!coll) { renderTypingIndicator([]); return; }
  unsub.typing = coll.onSnapshot(snap => {
    const now = Date.now();
    const names = [];
    snap.forEach(d => {
      if (d.id === myUid) return;
      const data = d.data();
      const ts = data.updatedAt && data.updatedAt.toMillis ? data.updatedAt.toMillis() : 0;
      if (ts && now - ts > TYPING_STALE_MS) return;
      names.push(data.username || d.id);
    });
    renderTypingIndicator(names);
  });
}
$('composer-input').addEventListener('input', (e) => { autoResize(e.target); commandInputChanged(e.target); updateSlashState(e.target); updateMentionState(e.target); updateComposerCharCount(); noteComposerTyping(); });

// ============================================================
// MENTIONS (@ autocomplete + rendering)
// Typing "@" plus a few letters pops up matching members from whichever
// server/DM/group is currently open, top match highlighted; Tab, Enter,
// or tapping a row completes it (see positionMentionPopup — reuses the
// same caret-measuring trick as the mobile keyboard's cursor overlay).
// Rendered mentions only get the "glow" style when that user is actually
// in the current conversation.
// ============================================================
function currentContextUsernames() {
  if (currentView === 'channel' && currentServerData) return withoutVanished(currentServerData.members, currentServerData);
  if (currentView === 'dm') return [myUid, currentDMOtherUid].filter(Boolean);
  if (currentView === 'groupdm') {
    const g = (window.__myGroupDMs || []).find(x => x.id === currentGroupDMId);
    return g ? withoutVanished(g.participants, g) : [];
  }
  return [];
}



// ============================================================
// APPS — small Frixion apps that post interactive cards in chat.
// A server only offers an app once its owner has added it (Server menu →
// Add App). In DMs and group DMs every app is available, like Discord's
// user-installed apps. Right now there is one: Wordle.
// ============================================================
const FRIXION_APPS = [
  { id: 'wordle', name: 'Wordle', command: 'wordle', desc: 'Guess the secret five-letter word in six tries. Anyone in the chat can play along.', avatar: WORDLE_AVATAR_URL },
  // Sapphire adds moderation commands. Server owners can add it to their own server, where the
  // commands only affect that server's members. Frixion staff (owner, co-owners, admins) can use
  // Sapphire everywhere without adding it, and their commands act on the whole of Frixion.
  { id: 'sapphire', name: 'Sapphire', command: 'purge', commands: ['purge', 'mute', 'unmute', 'ban', 'unban', 'kick'],
    desc: 'Moderation commands for your server: /purge, /mute, /unmute, /ban, /unban and /kick. They only affect your server\'s members.', avatar: SAPPHIRE_AVATAR_URL },
];
const isFrixionStaff = () => !!(isAdmin || isOwner);
// A short list of an app's commands, each with its icon and what it does. Used on the Add App page
// and in the + menu so every command shows the same picture it has in the autofill list.
function appCommandRowsHTML(app) {
  const names = app.commands || [app.command];
  return `<div class="app-cmd-list">` + names.map(n => {
    const c = SLASH_COMMANDS.find(x => x.name === n);
    if (!c) return '';
    return `<div class="app-cmd-row">${slashIconHTML(c, 'app-cmd-ico')}<span class="app-cmd-name">/${esc(c.name)}</span>${c.options.map(o => `<span class="slash-opt${o.required ? '' : ' optional'}">${esc(o.name)}</span>`).join('')}<span class="app-cmd-desc">${esc(c.desc)}</span></div>`;
  }).join('') + `</div>`;
}
function appById(id) { return FRIXION_APPS.find(a => a.id === id) || null; }
function serverHasApp(server, appId) { return !!(server && Array.isArray(server.apps) && server.apps.includes(appId)); }
// Is this app usable in the conversation that's open right now?
function appInstalledHere(appId) {
  if (currentView === 'channel') return serverHasApp(currentServerData, appId);
  return true;
}
// Sapphire's commands: Frixion staff can use them anywhere (they act on all of Frixion). Everyone
// else needs a server that added Sapphire plus the matching server permission, and then the
// command only touches that server.
const SAPPHIRE_SERVER_PERM = { purge: 'manageMessages', mute: 'timeoutMembers', unmute: 'timeoutMembers', ban: 'banMembers', unban: 'banMembers', kick: 'kickMembers' };
function sapphireModeFor(action) {
  // /purge works anywhere for Frixion staff. Mute, ban and kick only make sense inside a server.
  if (action === 'purge' && isFrixionStaff()) return 'platform';
  if (currentView !== 'channel' || !currentServerData) return null;
  if (isFrixionStaff()) return 'server';   // staff can moderate any server they are in
  if (serverHasApp(currentServerData, 'sapphire') && hasServerPerm(currentServerData, myUid, SAPPHIRE_SERVER_PERM[action])) return 'server';
  return null;
}
function appsAvailableHere() {
  return FRIXION_APPS.filter(a => a.id === 'sapphire'
    ? (a.commands || []).some(c => sapphireModeFor(c))
    : appInstalledHere(a.id));
}
function canAddServerApps(server) { return !!server && isServerOwnerLevel(server, myUid); }
// Any server owner can add any app to their own server.
function canAddApp(server, app) { return canAddServerApps(server); }
function canOpenAddApp(server) { return !!server && FRIXION_APPS.some(a => canAddApp(server, a)); }

// ---- Add App (server owners) ----
function openAddAppModal(server) {
  if (!canOpenAddApp(server)) { toast('Only the server owner can add apps.', 'error'); return; }
  const { overlay, close } = openInfoModal('Add Apps to ' + server.name, '<div id="add-app-list" class="add-app-list"></div>');
  const paint = () => {
    const cur = (currentServerData && currentServerData.id === server.id) ? currentServerData : server;
    overlay.querySelector('#add-app-list').innerHTML = FRIXION_APPS.filter(a => canAddApp(server, a)).map(a => {
      const on = serverHasApp(cur, a.id);
      return `<div class="add-app-row" data-app="${esc(a.id)}">
        <img class="add-app-avatar" src="${esc(a.avatar)}" alt="">
        <div class="add-app-info"><div class="add-app-name">${esc(a.name)} <span class="bot-tag"><span>APP</span></span></div>
          <div class="add-app-desc">${esc(a.desc)}</div>
          <div class="add-app-cmd">${a.commands ? 'Adds these commands' : 'Adds this command and a spot in the + menu'}</div>${appCommandRowsHTML(a)}</div>
        <button type="button" class="${on ? 'btn-secondary' : 'btn-accent-inline'} add-app-btn">${on ? 'Remove' : 'Add App'}</button>
      </div>`;
    }).join('');
    overlay.querySelectorAll('.add-app-row').forEach(row => {
      const id = row.dataset.app, app = appById(id);
      row.querySelector('.add-app-btn').onclick = async () => {
        const has = serverHasApp((currentServerData && currentServerData.id === server.id) ? currentServerData : server, id);
        try {
          await db.collection('servers').doc(server.id).update({ apps: has ? FieldValue.arrayRemove(id) : FieldValue.arrayUnion(id) });
          // the live server listener updates currentServerData; mirror it locally so the button flips straight away
          const base = (currentServerData && currentServerData.id === server.id) ? currentServerData : server;
          const list = new Set(base.apps || []); has ? list.delete(id) : list.add(id);
          base.apps = [...list];
          logAudit(server.id, `${has ? 'removed' : 'added'} the ${app.name} app`);
          toast(has ? `${app.name} removed from ${server.name}.` : `${app.name} added to ${server.name}. Try /${app.command}!`);
          paint();
        } catch (e) { toast(e.message || 'Could not update apps.', 'error'); }
      };
    });
  };
  paint();
}

// ---- "Use apps" panel in the + menu ----
function renderAppsPanel() {
  const panel = $('apps-panel');
  const list = appsAvailableHere();
  const server = currentView === 'channel' ? currentServerData : null;
  panel.innerHTML = `<div class="apps-panel-head">Apps</div>` + (list.length
    ? list.map(a => `<button type="button" class="apps-panel-item" data-app="${esc(a.id)}"><img src="${esc(a.avatar)}" alt=""><span class="apn-text"><b>${esc(a.name)}</b><small>${esc(a.desc)}</small>${appCommandRowsHTML(a)}</span></button>`).join('')
    : `<div class="apps-panel-empty">No apps are available here yet.${canOpenAddApp(server) ? '' : ' Ask the server owner to add one.'}</div>`)
    + (canOpenAddApp(server) ? `<button type="button" class="apps-panel-add" id="apps-panel-add-btn">＋ Add App</button>` : '');
  panel.querySelectorAll('.apps-panel-item').forEach(btn => { btn.onclick = () => { panel.classList.add('hidden'); runAppCommand(btn.dataset.app); }; });
  const add = $('apps-panel-add-btn');
  if (add) add.onclick = () => { panel.classList.add('hidden'); openAddAppModal(server); };
}
$('use-apps-menu').onclick = (e) => {
  e.stopPropagation();
  $('composer-action-menu').classList.add('hidden');
  const panel = $('apps-panel');
  renderAppsPanel();
  panel.classList.toggle('hidden');
};
document.addEventListener('click', (e) => {
  const panel = $('apps-panel');
  if (!panel.classList.contains('hidden') && !panel.contains(e.target) && !e.target.closest('#attach-btn')) panel.classList.add('hidden');
});
function runAppCommand(appId) {
  if (appId === 'wordle') startWordleGame();
  else if (appId === 'sapphire') {
    // Sapphire has several commands, so picking it drops "/" into the composer to open the command list.
    const input = $('composer-input');
    input.value = '/';
    input.dispatchEvent(new Event('input', { bubbles: true }));
    focusComposerForCommand(input);
  }
}

