// SETTINGS MODAL
// ============================================================
$('open-my-settings').onclick = () => openProfileModal(myUid);
$('open-settings-gear').onclick = openSettings;
function openSettings() { populateSettings(); openModal('settings-modal'); }

document.querySelectorAll('#settings-nav .nav-item[data-pane]').forEach(item => {
  item.onclick = () => {
    document.querySelectorAll('#settings-nav .nav-item[data-pane]').forEach(i => i.classList.remove('active'));
    item.classList.add('active');
    document.querySelectorAll('.settings-pane').forEach(p => p.classList.add('hidden'));
    $(item.dataset.pane).classList.remove('hidden');
    if (item.dataset.pane === 'pane-updates') renderUpdates();
    if (item.dataset.pane === 'pane-activity') populateRpc();
    if (item.dataset.pane === 'pane-app') populateAppPane();
    try { item.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' }); } catch (e) {}   // keeps the chosen tab in view in the phone's swipeable row
  };
});

$('open-admin-panel').onclick = () => { closeModal('settings-modal'); openAdminEntry(); };
$('open-owner-panel').onclick = () => { closeModal('settings-modal'); openAdminPanel(); };

function populateSettings() {
  if (!myProfile) return;
  $('set-username').value = myProfile.username;
  $('autocorrect-toggle').checked = isAutocorrectEnabled();
  $('custom-keyboard-toggle').checked = useCustomKeyboard();
  $('quick-buttons-toggle').checked = showQuickButtons();
  renderQuickTextList();
  populateRpc();

  const swatchWrap = $('avatar-color-swatches');
  swatchWrap.innerHTML = '';
  AVATAR_COLORS.forEach(c => {
    const sw = document.createElement('div');
    sw.className = 'swatch' + (myProfile.avatarColor === c ? ' selected' : '');
    sw.style.background = c;
    sw.onclick = async () => { await db.collection('users').doc(myUid).update({ avatarColor: c }); };
    swatchWrap.appendChild(sw);
  });

  $('orb-balance-amt').textContent = fmtOrbs(myProfile.orbs);
  $('premium-action-area').innerHTML = buildPremiumActionHTML();
  wirePremiumActionButtons('premium-action-area');

  renderThemeGrid();
  renderQuests();
}

function buildPremiumActionHTML() {
  const active = isPremium(myProfile);
  const balance = myProfile.orbs || 0;
  const days = Math.round(PREMIUM_DURATION_MS / 86400000);
  if (active) {
    const until = new Date(myProfile.premiumUntil).toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' });
    return `
      <span class="premium-active-badge">${icon('star')} Frixion Premium Active</span>
      <p class="desc" style="margin-top:12px;">Active until ${until}. Renewing early adds another ${days} days on top of your current expiry.</p>
      <button class="btn-accent-inline" style="width:100%;" data-premium-action="renew">Renew Now — ${PREMIUM_COST_ORBS} Orbs</button>`;
  }
  const canAfford = balance >= PREMIUM_COST_ORBS;
  return `
    <button class="btn-accent-inline" style="width:100%;" data-premium-action="subscribe" ${canAfford ? '' : 'disabled'}>Subscribe — ${PREMIUM_COST_ORBS} Orbs / ${days} days</button>
    ${canAfford ? '' : `<p class="desc" style="margin-top:10px;">You have ${balance} Orbs. Play games to earn the rest.</p>`}`;
}
function wirePremiumActionButtons(containerId) {
  const btn = $(containerId).querySelector('[data-premium-action]');
  if (btn) btn.onclick = subscribeToPremium;
}

function genRedeemCode() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  const seg = () => Array.from({ length: 4 }, () => chars[Math.floor(Math.random() * chars.length)]).join('');
  return `FRX-${seg()}-${seg()}`;
}
// maxUses: how many times the code can be redeemed in total (0 = no limit). Each account can redeem a code once.
// usedBy lists who has redeemed it; redeemedBy is the latest one (older code only looked at that).
async function createRedeemCode(type, value, createdBy, customCode, maxUses = 1) {
  const code = (customCode || '').trim().toUpperCase() || genRedeemCode();
  const existing = await db.collection('redeemCodes').doc(code).get();
  if (existing.exists) throw new Error('That code is already in use.');
  await db.collection('redeemCodes').doc(code).set({
    code, type, value, createdBy, maxUses, uses: 0, usedBy: [], redeemedBy: null, createdAt: FieldValue.serverTimestamp(), redeemedAt: null,
  });
  return code;
}
// Codes made before limits existed could be redeemed once, by whoever is in redeemedBy.
function codeUsage(data) {
  const n = Number(data && data.maxUses);
  const maxUses = Number.isFinite(n) && n >= 0 ? Math.floor(n) : 1;
  const usedBy = Array.isArray(data && data.usedBy) ? data.usedBy : (data && data.redeemedBy ? [data.redeemedBy] : []);
  const uses = Math.max(Number(data && data.uses) || 0, usedBy.length);
  return { maxUses, usedBy, uses, usedUp: maxUses > 0 && uses >= maxUses };
}
function showCodeModal(code, description) {
  $('code-reveal-text').textContent = code;
  $('code-reveal-desc').textContent = description;
  openModal('code-reveal-modal');
}
$('code-reveal-copy').onclick = () => {
  navigator.clipboard.writeText($('code-reveal-text').textContent).then(() => toast('Code copied.')).catch(() => {});
};

// Pays for a Premium code and creates it in one transaction: the Orbs are checked and taken at the same moment the code is
// made, so clicking twice (or two open tabs) can't spend the same Orbs twice or push the balance below zero.
let premiumPurchaseBusy = false;
async function buyPremiumCode(days) {
  if (premiumPurchaseBusy) throw new Error('busy');
  premiumPurchaseBusy = true;
  try {
    const userRef = db.collection('users').doc(myUid);
    let code = null;
    for (let tries = 0; tries < 5 && !code; tries++) {
      const candidate = genRedeemCode();
      const codeRef = db.collection('redeemCodes').doc(candidate);
      code = await db.runTransaction(async tx => {
        const [me, existing] = await Promise.all([tx.get(userRef), tx.get(codeRef)]);
        if (existing.exists) return null;                  // that random code is taken: try another
        if (((me.data() || {}).orbs || 0) < PREMIUM_COST_ORBS) throw new Error('not-enough-orbs');
        tx.update(userRef, { orbs: FieldValue.increment(-PREMIUM_COST_ORBS) });
        tx.set(codeRef, { code: candidate, type: 'premium', value: days, createdBy: myUid, maxUses: 1, uses: 0, usedBy: [], redeemedBy: null, createdAt: FieldValue.serverTimestamp(), redeemedAt: null });
        return candidate;
      });
    }
    if (!code) throw new Error('Could not make a code. Try again.');
    return code;
  } finally { premiumPurchaseBusy = false; }
}
async function subscribeToPremium() {
  const days = Math.round(PREMIUM_DURATION_MS / 86400000);
  try {
    const code = await buyPremiumCode(days);
    closeModal('premium-modal');
    showCodeModal(code, `This code adds ${days} days of Frixion Premium. Redeem it any time from Codes.`);
  } catch (e) {
    if (e.message === 'busy') return;
    toast(e.message === 'not-enough-orbs' ? 'Not enough Orbs. Play games to earn more.' : 'Something went wrong.', 'error');
  }
}

async function giftPremiumTo(recipientUsername) {
  const fresh = (await db.collection('users').doc(myUid).get()).data();
  if ((fresh.orbs || 0) < PREMIUM_COST_ORBS) { toast(`You need ${PREMIUM_COST_ORBS} Orbs to gift Premium.`); return; }
  const days = Math.round(PREMIUM_DURATION_MS / 86400000);
  confirmAction({
    title: 'Gift Frixion Premium', body: `Gift Frixion Premium to ${recipientUsername} for ${PREMIUM_COST_ORBS} Orbs?`,
    confirmLabel: 'Gift Premium', danger: false,
    onConfirm: async () => {
  try {
    let code;
    try { code = await buyPremiumCode(days); } catch (e) {
      if (e.message === 'busy') return;
      toast(e.message === 'not-enough-orbs' ? `You need ${PREMIUM_COST_ORBS} Orbs to gift Premium.` : 'Something went wrong.', 'error');
      return;
    }
    const dmId = dmIdFor(myUid, recipientUsername);
    const ref = db.collection('dms').doc(dmId);
    const dsnap = await ref.get();
    if (!dsnap.exists) await ref.set({ participants: [myUid, recipientUsername], autoDelete: true, createdAt: FieldValue.serverTimestamp() });
    await ref.collection('messages').add({
      text: `Gifted Frixion Premium! Redeem this code in Settings > Codes for ${days} days: ${code}`,
      uid: myUid, username: myProfile.username, createdAt: FieldValue.serverTimestamp(),
    });
    await ref.update({ updatedAt: FieldValue.serverTimestamp() });
    toast(`Gifted Premium to ${recipientUsername}!`);
    closeModal('gift-modal');
  } catch (e) { toast('Something went wrong.', 'error'); }
    },
  });
}

// Checking the code, marking it used and giving the reward all happen in one transaction, so a code can only ever pay out
// once, even if the button is pressed twice or two people try the same code at the same moment.
async function redeemCode() {
  const code = ($('redeem-code-input').value || '').trim().toUpperCase();
  const btn = $('redeem-code-btn');
  $('redeem-code-error').textContent = '';
  if (!code) { $('redeem-code-error').textContent = 'Enter a code.'; return; }
  if (code.length > 64 || code.includes('/')) { $('redeem-code-error').textContent = 'That code is invalid.'; return; }
  if (btn.disabled) return;
  btn.disabled = true;
  try {
    const ref = db.collection('redeemCodes').doc(code);
    const userRef = db.collection('users').doc(myUid);
    const result = await db.runTransaction(async tx => {
      const [snap, me] = await Promise.all([tx.get(ref), tx.get(userRef)]);
      if (!snap.exists) return { error: 'That code is invalid.' };
      const data = snap.data();
      const usage = codeUsage(data);
      if (usage.usedBy.includes(myUid)) return { error: 'You have already redeemed this code.' };
      if (usage.usedUp) return { error: usage.maxUses === 1 ? 'That code has already been redeemed.' : 'That code has been used up.' };
      const value = Math.max(0, Math.floor(Number(data.value) || 0));
      if (data.type === 'orbs') {
        tx.update(userRef, { orbs: FieldValue.increment(value) });
      } else if (data.type === 'premium') {
        const fresh = me.data() || {};
        const base = isPremium(fresh) ? fresh.premiumUntil : Date.now();
        tx.update(userRef, { premiumUntil: base + value * 86400000 });
      } else return { error: 'That code is invalid.' };
      tx.update(ref, { uses: usage.uses + 1, usedBy: [...usage.usedBy, myUid], redeemedBy: myUid, redeemedAt: FieldValue.serverTimestamp() });
      return { type: data.type, value };
    });
    if (result.error) { $('redeem-code-error').textContent = result.error; return; }
    toast(result.type === 'orbs' ? `+${result.value} Orbs redeemed!` : `Frixion Premium extended by ${result.value} days!`);
    $('redeem-code-input').value = '';
    renderCodesView();
  } catch (e) { $('redeem-code-error').textContent = 'Something went wrong.'; }
  finally { btn.disabled = false; }
}

function openPremiumModal() {
  $('premium-modal-orb-amt').textContent = fmtOrbs(myProfile.orbs);
  $('premium-modal-action-area').innerHTML = buildPremiumActionHTML();
  wirePremiumActionButtons('premium-modal-action-area');
  openModal('premium-modal');
}

// ============================================================
// ACCESSIBILITY — SCREEN SHAKE
//
// >>> RULE FOR EVERY AI MODEL AND DEVELOPER WORKING ON THIS PROJECT <<<
// Settings > Accessibility has a "Reduce screen shake" switch. It must turn off
// EVERY shake, rumble, tilt, camera-shake and violent-motion effect in Frixion:
// the ones that exist today AND anything you add later (shop items, games,
// events, error bars, animations, all of it). Whenever you add one:
//   - Motion driven by JavaScript: call shakeAllowed() first and skip the
//     motion when it returns false.
//   - Motion driven by a CSS animation: add a rule like
//       html[data-no-shake] .your-class { animation: none !important; }
//     to the "screen shake" block at the very bottom of style.css.
// Never ship a new shake that ignores this switch. The setting is saved on
// the device, and mirrored onto the account (a11yNoShake) so it follows the
// person to other devices. With no choice made it defaults to the browser's
// "reduce motion" preference.
// ============================================================
const SHAKE_KEY = 'frixion_no_shake';
function screenShakeOff() {
  let v = null; try { v = localStorage.getItem(SHAKE_KEY); } catch (e) {}
  if (v === '1') return true;
  if (v === '0') return false;
  return !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
}
function shakeAllowed() { return !screenShakeOff() && !epilepsyMode(); }   // Epilepsy Mode (below) also stops every shake
function applyShakeSetting() {
  const epi = epilepsyMode(), off = screenShakeOff() || epi;
  document.documentElement.toggleAttribute('data-no-shake', off);
  const t = $('a11y-no-shake-toggle'); if (t) { t.checked = off; t.disabled = epi; }   // Epilepsy Mode forces it on
  if (off) resetScreenShake();
}
function setScreenShakeOff(off) {
  try { localStorage.setItem(SHAKE_KEY, off ? '1' : '0'); } catch (e) {}
  applyShakeSetting();
  if (myUid) db.collection('users').doc(myUid).update({ a11yNoShake: off }).catch(() => {});
}
function syncShakeFromProfile(p) {
  if (!p || typeof p.a11yNoShake !== 'boolean') return;
  let v = null; try { v = localStorage.getItem(SHAKE_KEY); } catch (e) {}
  if (v !== (p.a11yNoShake ? '1' : '0')) { try { localStorage.setItem(SHAKE_KEY, p.a11yNoShake ? '1' : '0'); } catch (e) {} applyShakeSetting(); }
}
// ============================================================
// ACCESSIBILITY — EPILEPSY MODE
//
// >>> RULE FOR EVERY AI MODEL AND DEVELOPER WORKING ON THIS PROJECT <<<
// Settings > Accessibility has an "Epilepsy mode" switch (epilepsyMode()). When it is on, NOTHING in Frixion
// may flash, strobe, flicker, pulse brightly or swap colours quickly: no screen flashes, no flickering or
// glitching effects, no pulsing glows, no bars that blink, no static. It also switches on everything that
// "Reduce screen shake" does. Whenever you add something that flashes or flickers, including shop items,
// games, cutscenes, animations and sound-synced visuals:
//   - Motion driven by JavaScript: check epilepsyMode() and skip the effect (or show a still version).
//   - A CSS animation: add html[data-epilepsy] .your-class { animation: none !important; } to the
//     "Epilepsy mode" block at the very bottom of style.css.
//   - A video or other media that flashes: don't autoplay it in epilepsy mode, and warn before playing it.
// Never ship a flashing effect that ignores this switch. It is saved on the device and mirrored onto the
// account (a11yEpilepsy). It is never turned on automatically.
// ============================================================
const EPI_KEY = 'frixion_epilepsy_mode';
function epilepsyMode() { try { return localStorage.getItem(EPI_KEY) === '1'; } catch (e) { return false; } }
function applyEpilepsySetting() {
  const on = epilepsyMode();
  document.documentElement.toggleAttribute('data-epilepsy', on);
  const t = $('a11y-epilepsy-toggle'); if (t) t.checked = on;
  if (on && musicBarsEl) { musicBarsEl.remove(); musicBarsEl = null; musicBarSet = null; musicBarsH = 0; }
  applyShakeSetting();
}
function setEpilepsyMode(on) {
  try { localStorage.setItem(EPI_KEY, on ? '1' : '0'); } catch (e) {}
  applyEpilepsySetting();
  if (myUid) db.collection('users').doc(myUid).update({ a11yEpilepsy: on }).catch(() => {});
}
function syncEpilepsyFromProfile(p) {
  if (!p || typeof p.a11yEpilepsy !== 'boolean') return;
  if (p.a11yEpilepsy !== epilepsyMode()) { try { localStorage.setItem(EPI_KEY, p.a11yEpilepsy ? '1' : '0'); } catch (e) {} applyEpilepsySetting(); }
}

// ============================================================
// ACCESSIBILITY — LIQUID GLASS
// Settings > Accessibility > "Liquid glass" sets html[data-liquid-glass], and style.css turns menus, pop-ups,
// pickers, sheets and floating bars into frosted, see-through glass. Anything new that is a menu, pop-up or
// floating panel should get a rule in the "Liquid glass" block at the bottom of style.css. Saved on the device and
// mirrored onto the account (a11yLiquidGlass).
// ============================================================
const GLASS_KEY = 'frixion_liquid_glass';
function liquidGlassOn() { try { return localStorage.getItem(GLASS_KEY) === '1'; } catch (e) { return false; } }
// Three sliders tune it: Opacity (how solid the glass is), Strength (blur, colour boost and edge shine) and Menu
// background blur (how much the page behind a menu or pop-up window is blurred; works with or without glass).
const GLASS_TUNE_KEY = 'frixion_glass_tune';
const GLASS_TUNE_DEFAULTS = { opacity: 34, strength: 60, menuBlur: null };   // menuBlur null = automatic (8px with glass on, none with it off)
function glassTune() {
  let t = {}; try { t = JSON.parse(localStorage.getItem(GLASS_TUNE_KEY) || '{}') || {}; } catch (e) {}
  const num = (v, lo, hi, d) => (typeof v === 'number' && isFinite(v)) ? Math.min(hi, Math.max(lo, v)) : d;
  return { opacity: num(t.opacity, 10, 100, GLASS_TUNE_DEFAULTS.opacity), strength: num(t.strength, 0, 100, GLASS_TUNE_DEFAULTS.strength), menuBlur: num(t.menuBlur, 0, 30, null) };
}
function applyLiquidGlass() {
  const on = liquidGlassOn(), t = glassTune(), root = document.documentElement;
  root.toggleAttribute('data-liquid-glass', on);
  root.style.setProperty('--glass-a', (t.opacity / 100).toFixed(2));
  root.style.setProperty('--glass-blur', (4 + t.strength * 0.56).toFixed(1) + 'px');
  root.style.setProperty('--glass-sat', (1 + t.strength * 0.02).toFixed(2));
  root.style.setProperty('--glass-hl', (t.strength / 60).toFixed(2));
  const bg = t.menuBlur === null ? (on ? 8 : 0) : t.menuBlur;
  root.style.setProperty('--menu-bg-filter', bg > 0 ? `blur(${bg}px)` : 'none');
  const tog = $('a11y-glass-toggle'); if (tog) tog.checked = on;
  [['a11y-glass-opacity', t.opacity, '%'], ['a11y-glass-strength', t.strength, '%'], ['a11y-menu-blur', bg, 'px']].forEach(([id, v, u]) => {
    const el = $(id); if (!el) return;
    if (document.activeElement !== el) el.value = v;
    const out = $(id + '-val'); if (out) out.textContent = Math.round(v) + u;
  });
  const box = $('glass-tune-box'); if (box) box.classList.toggle('is-off', !on);
}
function setLiquidGlass(on) {
  try { localStorage.setItem(GLASS_KEY, on ? '1' : '0'); } catch (e) {}
  applyLiquidGlass();
  if (myUid) db.collection('users').doc(myUid).update({ a11yLiquidGlass: on }).catch(() => {});
}
let glassTuneSaveT = 0;
function setGlassTune(patch, save) {
  const next = { ...glassTune(), ...patch };
  try { localStorage.setItem(GLASS_TUNE_KEY, JSON.stringify(next)); } catch (e) {}
  applyLiquidGlass();
  if (!save) return;
  clearTimeout(glassTuneSaveT);
  glassTuneSaveT = setTimeout(() => { if (myUid) db.collection('users').doc(myUid).update({ a11yGlassTune: next }).catch(() => {}); }, 400);
}
function syncLiquidGlassFromProfile(p) {
  if (!p) return;
  if (typeof p.a11yLiquidGlass === 'boolean' && p.a11yLiquidGlass !== liquidGlassOn()) { try { localStorage.setItem(GLASS_KEY, p.a11yLiquidGlass ? '1' : '0'); } catch (e) {} applyLiquidGlass(); }
  if (p.a11yGlassTune && typeof p.a11yGlassTune === 'object' && JSON.stringify(p.a11yGlassTune) !== JSON.stringify(glassTune())) {
    try { localStorage.setItem(GLASS_TUNE_KEY, JSON.stringify(p.a11yGlassTune)); } catch (e) {} applyLiquidGlass();
  }
}

function resetScreenShake() {
  document.body.style.transform = '';
  document.documentElement.classList.remove('is-shaking');
}

// ============================================================
// SHOP MUSIC
// A track is an ordinary shop item (category "music", profile fields
// ownedMusic / equippedMusic). The equipped track loops for as long as the
// person is signed in. To add one: put the audio file in the Music folder (next to index.html),
// add an entry here and, if it should shake the screen, a loudness envelope
// in MUSIC_SHAKE_ENVELOPES (one byte per 1/30 s, 0-255, base64).
//   cutscenes: optional list of { src, label } videos (kept in the Cutscenes folder) that play one after another on the first purchase.
//   banner:   optional image file (kept in the Banners folder) used as the background of the track's Shop card, behind its name.
//   bannerPos: optional CSS background-position for the banner (e.g. '50% 30%') when the middle of the picture isn't the part to show.
//   shake:    the screen tilts and shakes to the beat (up to 40 degrees).
//   Any new shake must respect shakeAllowed() — see the accessibility rule above.
//
// RULES FOR ANY AI MODEL / DEVELOPER ADDING A SONG (the owner asked for these):
//   1. Files live in folders next to index.html, never loose in the main directory:
//        Music/      the song's audio file          (src: 'Music/your-song.mp3')
//        Banners/    the Shop card's banner image   (banner: 'Banners/your-song-banner.jpg')
//        Cutscenes/  any cutscene videos            (cutscenes: [{ src: 'Cutscenes/your-video.mp4' }])
//      Folder names are case-sensitive on GitHub, so keep the capital first letter.
//   2. DO NOT feature new songs. Leave "featured" out of the new entry (or set featured: false) so it stays off the
//      Featured tab. Only the songs already marked featured below stay there. The owner can feature one later from the
//      Shop tab of the Admin or Owner panel.
//   3. Do not add a changelog entry for a song unless the owner asks for one.
// ============================================================
const MUSIC_TRACKS = [
  { id: 'equinox', name: '『 EQUILIBRIUM INCARNATE, EQUINOX 』', price: 1000000, featured: true, hero: true, fx: 'equinox',
    desc: 'Plays on a loop and shakes your screen to the beat. Buying it plays two cutscenes. You can turn the shaking off in Settings > Accessibility.',
    src: 'Music/equinox-music.mp3', shake: true,
    // Videos shown in order the first time it is bought. Each one can be replayed on its own from the Shop.
    // The ?v= on a file name is only there so browsers fetch the newer video instead of an old cached one.
    cutscenes: [{ src: 'Cutscenes/equinox-cutscene.mp4?v=2', label: 'Cutscene' }, { src: 'Cutscenes/equinox-aftermath.mp4?v=1', label: 'Aftermath' }],
    // Black-and-white bars at the top and bottom of the screen, on cue with the song (seconds into the track).
    // 'move' bars jump up and down and flash black/white with the beat; 'hold' bars stay still, waiting for the drop.
    bars: [
      { from: 59,  to: 79,  mode: 'move' },   // 0:59 - 1:18
      { from: 101, to: 110, mode: 'move' },   // 1:41 - 1:49
      { from: 110, to: 112, mode: 'hold' },   // 1:50 - 1:51
      { from: 112, to: 122, mode: 'move' },   // 1:52 - 2:01
      { from: 122, to: 124, mode: 'hold' },   // 2:02 - 2:03
      { from: 124, to: 133, mode: 'move' },   // 2:04 - 2:12
      { from: 133, to: 134, mode: 'hold' },   // 2:13
      { from: 134, to: 143, mode: 'move' },   // 2:14 - 2:22
    ] },
  { id: 'pure-vessel', name: 'Pure Vessel', price: 150000, featured: true, banner: 'Banners/pure-vessel-banner.png',
    desc: 'Plays on a loop for as long as you are signed in.',
    src: 'Music/pure-vessel-music.mp3' },
  { id: 'overcontrol', name: 'Overcontrol Main Theme', price: 250000, featured: true, banner: 'Banners/overcontrol-banner.png',
    desc: 'Plays on a loop for as long as you are signed in.',
    src: 'Music/overcontrol-main-theme.mp3' },
  { id: 'null-1st-theme', name: 'Null 1st Theme', price: 500000, featured: true, banner: 'Banners/null-1st-banner.jpg', bannerPos: '50% 30%',
    desc: 'Plays on a loop for as long as you are signed in.',
    src: 'Music/null-1st-theme.mp3' },
  { id: 'null-2nd-theme', name: 'Null 2nd Theme', price: 750000, featured: true, banner: 'Banners/null-2nd-banner.jpg',
    desc: 'Plays on a loop for as long as you are signed in.',
    src: 'Music/null-2nd-theme.mp3' },
  { id: 'null-3rd-theme', name: 'Null 3rd Theme', price: 1250000, featured: true, banner: 'Banners/null-3rd-banner.jpg',
    desc: 'Plays on a loop for as long as you are signed in.',
    src: 'Music/null-3rd-theme.mp3' },
];
// Songs added by staff (Admin / Owner panel > Shop > Music). They live in one config document, config/customMusic, as a map of
// id -> { name, desc, price, featured, src, banner?, cutscenes?: [{ src, label }], createdBy, createdAt }. The files themselves are on
// Cloudinary (see uploadFileToCloudinary). Built-in songs stay in MUSIC_TRACKS above.
let customMusicTracks = [];
function allMusicTracks() { return [...MUSIC_TRACKS, ...customMusicTracks]; }
const MUSIC_SHAKE_ENVELOPES = {
  equinox: '',
};

let musicAudio = null, musicTrack = null, musicEnv = null, musicShakeRaf = 0, musicGestureFn = null, cutsceneActive = false;
let musicBarsEl = null, musicBarsH = 0, musicBarsLast = 0;
function musicVolume() {
  let v = NaN; try { v = parseFloat(localStorage.getItem('frixion_music_volume')); } catch (e) {}
  return isFinite(v) ? Math.min(1, Math.max(0, v)) : 0.6;
}
function setMusicVolume(v) {
  try { localStorage.setItem('frixion_music_volume', String(v)); } catch (e) {}
  if (musicAudio) musicAudio.volume = v;
}
function musicStop() {
  if (musicGestureFn) { ['pointerdown', 'keydown', 'touchstart'].forEach(t => window.removeEventListener(t, musicGestureFn, true)); musicGestureFn = null; }
  if (musicAudio) { try { musicAudio.pause(); musicAudio.removeAttribute('src'); musicAudio.load(); } catch (e) {} }
  musicAudio = null; musicTrack = null; musicEnv = null; musicStartedAt = 0;
  activityRefresh();
  cancelAnimationFrame(musicShakeRaf); musicShakeRaf = 0;
  resetScreenShake();
  if (musicBarsEl) { musicBarsEl.remove(); musicBarsEl = null; }
  musicBarSet = null; musicBarsH = 0; musicBarsLast = 0;
}
// Call with the equipped track id (or null). Starts, switches or stops the music to match.
function musicSync(id) {
  if (cutsceneActive) return;
  if (!id) { if (musicAudio) musicStop(); return; }
  if (musicTrack && musicTrack.id === id) return;
  const track = allMusicTracks().find(t => t.id === id);
  musicStop();
  if (!track) return;
  musicTrack = track; musicStartedAt = Date.now();
  activityRefresh();
  const a = new Audio(track.src);
  a.loop = true; a.preload = 'auto'; a.volume = musicVolume();
  musicAudio = a;
  const b64 = MUSIC_SHAKE_ENVELOPES[track.id];
  try { musicEnv = track.shake && b64 ? Uint8Array.from(atob(b64), c => c.charCodeAt(0)) : null; } catch (e) { musicEnv = null; }
  // Browsers only allow sound after the person has clicked or tapped the page; if it's blocked, start on the first one.
  a.play().catch(() => {
    const go = () => { ['pointerdown', 'keydown', 'touchstart'].forEach(t => window.removeEventListener(t, go, true)); if (musicGestureFn === go) musicGestureFn = null; if (musicAudio === a) a.play().catch(() => {}); };
    musicGestureFn = go;
    ['pointerdown', 'keydown', 'touchstart'].forEach(t => window.addEventListener(t, go, true));
  });
  if (musicEnv || track.bars) musicShakeRaf = requestAnimationFrame(musicShakeTick);
}
function resumeMusicLoop() {
  if (musicAudio && !musicShakeRaf && !pageHidden() && (musicEnv || (musicTrack && musicTrack.bars))) musicShakeRaf = requestAnimationFrame(musicShakeTick);
}
// Shakes the whole page in time with the music. The loudness envelope was measured from the
// track ahead of time, so it stays in sync with audio.currentTime and works from any hosting.
function musicShakeTick(now) {
  // Nobody can see the page (a background tab, or the app window in the tray): stop drawing until it shows again.
  // resumeMusicLoop() restarts it. The music itself keeps playing.
  if (pageHidden()) {
    musicShakeRaf = 0;
    if (document.body.style.transform) resetScreenShake();
    if (musicBarsEl) musicBarsEl.style.visibility = 'hidden';
    musicBarsLast = 0;
    return;
  }
  musicShakeRaf = requestAnimationFrame(musicShakeTick);
  const a = musicAudio;
  if (!a) return;
  musicBarsTick(a, now);
  if (!musicEnv) return;
  if (!shakeAllowed() || a.paused || cutsceneActive) { if (document.body.style.transform) resetScreenShake(); return; }
  const pos = (a.currentTime * 30) % musicEnv.length, i = Math.floor(pos), f = pos - i;
  const e = (musicEnv[i] * (1 - f) + musicEnv[(i + 1) % musicEnv.length] * f) / 255;
  const s = Math.pow(e, 1.5);                         // quiet stretches barely move; the loudest hits reach the maximum
  const t = now / 1000;
  const wobble = 0.6 * Math.sin(t * 31) + 0.4 * Math.sin(t * 17 + 1.3);     // always between -1 and 1
  const MAX_TILT = 40;                                // degrees
  document.documentElement.classList.add('is-shaking');
  document.body.style.transform = `translate(${(26 * s * Math.sin(t * 43 + 2)).toFixed(1)}px, ${(20 * s * Math.sin(t * 37)).toFixed(1)}px) rotate(${(MAX_TILT * s * wobble).toFixed(2)}deg) scale(${(1 + 0.04 * s).toFixed(3)})`;
}

// The Equinox bars, built to match the ones in Sol's RNG: flat, solid blocks with a gap between each one, every block
// either black or white. One row hangs from the top of the screen and another stands on the bottom. They sit on the
// <html> element, not the page, so the screen shake doesn't carry them off.
//   'move' cue: every bar jumps up and down on its own and flips between black and white, quickly. The whole set
//               re-rolls on each hit of the beat, and the louder the music the faster they flash.
//   'hold' cue: the bars freeze where they are, waiting for the drop.
//   Between cues they slide away. "Reduce screen shake" does not affect them at all, and
//   Epilepsy mode hides them completely (they flash, so they MUST respect it — see the Epilepsy mode block).
const MB_PITCH = 96;           // px from the start of one bar to the start of the next; the bar is 62% of that, the rest is gap
let musicBarSet = null;        // { n, top: [bar...], bot: [bar...] }; each bar { el, cur, to, hold, white, flipAt, moveAt }
function mbRnd() { return Math.random(); }
function buildMusicBars() {
  const n = Math.max(8, Math.round(window.innerWidth / MB_PITCH));
  if (musicBarsEl) musicBarsEl.remove();
  musicBarsEl = document.createElement('div');
  musicBarsEl.id = 'music-bars';
  musicBarsEl.setAttribute('aria-hidden', 'true');
  const set = { n, top: [], bot: [], beatAvg: 0, beatAt: 0, fakeAt: 0 };
  [['top', 'mb-top'], ['bot', 'mb-bot']].forEach(([key, cls]) => {
    const row = document.createElement('div');
    row.className = 'mb-row ' + cls;
    for (let i = 0; i < n; i++) {
      const slot = document.createElement('div'), el = document.createElement('div');
      slot.className = 'mb-slot'; el.className = 'mb-bar';
      const white = mbRnd() < 0.5;
      if (white) el.classList.add('w');
      slot.append(el); row.append(slot);
      const h = 0.06 + mbRnd() * 0.94;
      set[key].push({ el, cur: 0, to: h, hold: 0.12 + mbRnd() * 0.8, white, flipAt: 0, moveAt: 0, y: '' });
    }
    musicBarsEl.append(row);
  });
  document.documentElement.append(musicBarsEl);
  musicBarSet = set;
}
function musicBarsTick(a, now) {
  const cues = musicTrack && musicTrack.bars;
  if (!cues) return;
  const dt = Math.min(0.1, Math.max(0, (now - (musicBarsLast || now)) / 1000)); musicBarsLast = now;
  const live = !a.paused && !pageHidden() && !cutsceneActive;
  const cue = live && !epilepsyMode() ? cues.find(c => a.currentTime >= c.from && a.currentTime < c.to) : null;
  musicBarsH += ((cue ? 1 : 0) - musicBarsH) * Math.min(1, dt * (cue ? 9 : 6));   // 0 = away, 1 = in place
  if (musicBarsH < 0.01 && !cue) { if (musicBarsEl) musicBarsEl.style.visibility = 'hidden'; return; }
  if (!musicBarsEl || !musicBarSet || musicBarSet.n !== Math.max(8, Math.round(window.innerWidth / MB_PITCH))) buildMusicBars();
  musicBarsEl.style.visibility = 'visible';
  const set = musicBarSet;
  const moving = !!cue && cue.mode === 'move';          // "Reduce screen shake" does nothing here; only Epilepsy mode stops the bars (it makes cue null above)
  // How loud the song is right now (0-1). If the loudness data is missing, a steady made-up beat stands in.
  let s = 0.6;
  if (musicEnv) {
    const pos = (a.currentTime * 30) % musicEnv.length, i = Math.floor(pos), f = pos - i;
    s = Math.pow((musicEnv[i] * (1 - f) + musicEnv[(i + 1) % musicEnv.length] * f) / 255, 1.2);
  }
  // A "beat" is the loudness jumping above its recent average.
  let beat = false;
  if (moving) {
    const t = now / 1000;
    set.beatAvg += (s - set.beatAvg) * Math.min(1, dt * 5);
    if (musicEnv ? (s > set.beatAvg * 1.18 + 0.05 && t - set.beatAt > 0.11) : t - set.beatAt > 0.26) { beat = true; set.beatAt = t; }
  }
  const ease = 1 - Math.exp(-dt * (moving ? 30 : 9));
  const paint = (bars, flip) => bars.forEach(b => {
    if (moving) {
      if (beat) {
        if (mbRnd() < 0.8) b.to = 0.06 + Math.pow(mbRnd(), 0.7) * 0.94 * (0.75 + 0.25 * s);   // jump to a new height
        if (mbRnd() < 0.45) { b.white = !b.white; b.el.classList.toggle('w', b.white); }      // flash on the hit
      }
      if (now >= b.moveAt) { b.to = 0.06 + Math.pow(mbRnd(), 0.8) * 0.94 * (0.7 + 0.3 * s); b.moveAt = now + 110 + mbRnd() * 330; }
      if (now >= b.flipAt) {                                                                    // quick flicker between black and white
        b.white = !b.white; b.el.classList.toggle('w', b.white);
        b.flipAt = now + (70 + mbRnd() * 230) * (1.25 - 0.7 * s);
      }
    }
    const target = moving ? b.to : b.hold;
    b.cur += (target - b.cur) * ease;
    const y = ((1 - Math.min(1, b.cur) * musicBarsH) * 100 * (flip ? 1 : -1)).toFixed(2);
    if (y !== b.y) { b.y = y; b.el.style.transform = `translateY(${y}%)`; }
  });
  paint(set.top, false);
  paint(set.bot, true);
}

// The video that plays the first time a track with a cutscene is bought.
function playCutscene(src) {
  return new Promise(resolve => {
    const el = document.createElement('div');
    el.id = 'cutscene-screen';
    // The stage turns sideways on a phone held upright (see style.css), so the wide video fills the screen.
    el.innerHTML = '<div class="cut-stage"><video playsinline preload="auto"></video><button type="button" class="cut-skip hidden">Skip</button></div>';
    document.body.append(el);
    const v = el.querySelector('video'), skip = el.querySelector('.cut-skip');
    let done = false;
    const finish = () => {
      if (done) return; done = true;
      el.classList.add('is-out');
      setTimeout(() => el.remove(), 400);
      try { v.pause(); } catch (e) {}
      resolve();
    };
    v.onended = finish; v.onerror = finish; skip.onclick = finish;
    setTimeout(() => skip.classList.remove('hidden'), 2000);
    setTimeout(finish, 120000);                        // never trap anyone behind a stuck video
    v.src = src;
    v.play().catch(() => { v.muted = true; v.play().catch(finish); });   // blocked with sound: play it silent rather than skip it
  });
}

// Animated name text (used by shop items that set `fx`). The name is rendered letter by letter, and a ring of
// little words (taken from the name) is placed behind it; CSS sends them drifting outward and fading, over and over.
function fxTextHTML(text, fx) {
  let i = 0;
  const words = String(text).split(' ').map(w => '<span class="fx-w">' + Array.from(w).map(c => `<span class="fx-ch" style="--i:${i++}">${esc(c)}</span>`).join('') + '</span>').join(' ');
  const bits = String(text).replace(/[『』,]/g, '').split(' ').filter(Boolean);
  const N = 10;
  const echoes = bits.length ? Array.from({ length: N }, (_, n) => {
    const ang = (n / N) * Math.PI * 2 + (n % 2) * 0.35;
    const dx = Math.round(Math.cos(ang) * (92 + (n % 3) * 22)), dy = Math.round(Math.sin(ang) * (40 + (n % 2) * 16));
    return `<span class="fx-echo" aria-hidden="true" style="--dx:${dx}px;--dy:${dy}px;--d:${(-n * 0.44).toFixed(2)}s">${esc(bits[n % bits.length])}</span>`;
  }).join('') : '';
  return `<span class="fx-text fx-${esc(fx || 'plain')}" role="text" aria-label="${esc(text)}">${echoes}<span class="fx-letters" aria-hidden="true">${words}</span></span>`;
}

// ============================================================
// SHOP — Featured, Avatar Decorations, Nameplates, Profile Effects, and
// Profile Frames are all functional.
// ============================================================
function orbIconSVG(size) { return `<svg viewBox="0 0 24 24" width="${size}" height="${size}"><circle cx="12" cy="12" r="9" fill="currentColor"/><circle cx="9" cy="9" r="2.6" fill="#fff" opacity=".55"/></svg>`; }

function shopItemPreviewHTML(key, item) {
  if (key === 'decorations') return `<div class="sic-deco-stage">${avatarHTML(72, myProfile.avatarColor, initials(myProfile.username), null, myProfile.avatarUrl, item.id)}</div>`;
  if (key === 'masks') return `<div class="sic-deco-stage">${avatarHTML(72, myProfile.avatarColor, initials(myProfile.username), null, myProfile.avatarUrl, null, undefined, item.id)}</div>`;
  if (key === 'music') return `<div class="sic-music-preview${item.fx ? ' fx-bg-' + esc(item.fx) : ''}${item.banner ? ' has-banner' : ''}${myProfile && myProfile.equippedMusic === item.id ? ' is-playing' : ''}"${item.banner ? ` style="background-image:${esc(cssUrl(item.banner))}${item.bannerPos ? ';background-position:' + esc(item.bannerPos) : ''}"` : ''}><div class="smp-eq" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div>${item.fx ? fxTextHTML(item.name, item.fx) : `<span class="smp-title">${esc(item.name)}</span>`}</div>`;
  if (key === 'banners') return `<div class="sic-banner-preview">
    <div class="sic-banner-strip${item.animated ? ' banner-anim' : ''}" style="background:${esc(bannerGradientCSS(item))};"></div>
    <div class="sic-banner-avatar">${avatarHTML(44, myProfile.avatarColor, initials(myProfile.username), null, myProfile.avatarUrl)}</div>
    <div class="sic-banner-lines"><span></span><span></span></div>
  </div>`;
  if (key === 'nameplates') {
    const cls = 'sic-nameplate-preview' + (item.cssClass ? ' ' + item.cssClass : '') + ((item.animated && !item.cssClass) ? ' nameplate-shimmer' : '');
    const style = item.colors ? `background:linear-gradient(135deg, ${esc(item.colors[0])}, ${esc(item.colors[1])});` : '';
    return `<div class="${cls}" style="${style}"><span>${esc(displayNameOf(myProfile))}</span></div>`;
  }
  if (key === 'profile_effects') {
    const cls = 'sic-effect-preview' + (item.cssClass ? ' ' + item.cssClass : '') + (item.style ? ' effect-style-' + item.style : '');
    const style = item.color ? `--custom-particle-color:${esc(item.color)};` : '';
    return `<div class="${cls}" style="${style}">${PROFILE_EFFECT_PARTICLES_HTML}</div>`;
  }
  if (key === 'profile_frames') {
    const cls = 'sic-frame-preview' + (item.cssClass ? ' ' + item.cssClass : '') + (item.glow ? ' frame-custom-glow' : '');
    const style = item.color ? `border:3px solid ${esc(item.color)};--custom-frame-color:${esc(item.color)};` : '';
    return `<div class="${cls}" style="${style}">${avatarHTML(56, myProfile.avatarColor, initials(myProfile.username), null, myProfile.avatarUrl)}</div>`;
  }
  // Big LiquidType-style swatch: the gradient fills the whole preview and
  // the name sits on top of it (with a dark scrim behind the text for
  // legibility) instead of living in a separate line below — this is
  // also why themes skip the usual .sic-name block in shopItemCardHTML.
  if (key === 'themes') return `<div class="sic-theme-preview" style="background:linear-gradient(135deg, ${item.bg[0]} 0%, ${item.bg[1]} 55%, ${item.bg[2]} 100%);">
    <div class="sic-theme-overlay">
      <span class="sic-theme-name">${esc(item.name)}</span>
      ${item.animated ? '<span class="sic-animated-tag">Animated</span>' : ''}
    </div>
  </div>`;
  return '';
}

function itemCutscenes(item) { return item.cutscenes || (item.cutscene ? [{ src: item.cutscene, label: 'Cutscene' }] : []); }
function shopItemCardHTML(key, item) {
  const def = SHOP_CATEGORY_DEFS[key];
  const owned = (myProfile[def.ownedField] || []).includes(item.id);
  const equipped = myProfile[def.equipField] === item.id;
  const action = equipped ? 'unequip' : owned ? 'equip' : 'buy';
  const label = equipped ? 'Unequip' : owned ? 'Equip' : `${orbIconSVG(13)}<span>${Number(item.price).toLocaleString()}</span>`;
  return `<div class="shop-item-card${key === 'themes' ? ' is-theme-card' : ''}${key === 'music' ? ' is-music-card' : ''}${item.hero ? ' is-hero' : ''}" data-item="${esc(item.id)}" data-cat="${key}">
    <div class="sic-preview">${shopItemPreviewHTML(key, item)}</div>
    ${(key === 'themes' || key === 'music') ? '' : `<div class="sic-name">${esc(item.name)}${item.animated ? '<span class="sic-animated-tag">Animated</span>' : ''}</div>`}
    ${item.desc ? `<div class="sic-desc">${esc(item.desc)}</div>` : ''}
    <button class="sic-btn${equipped ? ' is-equipped' : owned ? ' is-owned' : ''}" data-action="${action}">${label}</button>
    ${owned && itemCutscenes(item).length ? `<div class="sic-replay" role="group" aria-label="Replay cutscenes">${itemCutscenes(item).map((c, n) => `<button type="button" class="sic-replay-seg" data-seg="${n}">Replay ${esc(c.label)}</button>`).join('')}</div>` : ''}
  </div>`;
}

function wireShopCardButtons(wrap) {
  wrap.querySelectorAll('.shop-item-card').forEach(card => {
    const key = card.dataset.cat;
    const id = card.dataset.item;
    const btn = card.querySelector('.sic-btn');
    card.querySelectorAll('.sic-replay-seg').forEach(b => { b.onclick = () => replayCutscene(key, id, +b.dataset.seg); });
    btn.onclick = () => {
      if (btn.dataset.action === 'buy') buyShopItem(key, id);
      else if (btn.dataset.action === 'equip') equipShopItem(key, id);
      else equipShopItem(key, null);
    };
  });
}

// Featured is split into one section per kind of item. Music comes first, so the newest tracks sit at the very top.
const SHOP_FEATURED_ORDER = ['music', 'themes', 'banners', 'decorations', 'masks', 'nameplates', 'profile_effects', 'profile_frames'];
function shopGridClass(key) {
  return 'shop-grid' + (key === 'music' ? ' music-shop-grid' : (key === 'themes' || key === 'banners') ? ' theme-shop-grid' : '');
}
function renderShopFeatured() {
  const wrap = $('shop-pane-featured');
  const keys = SHOP_FEATURED_ORDER.concat(Object.keys(SHOP_CATEGORY_DEFS).filter(k => !SHOP_FEATURED_ORDER.includes(k)));
  const sections = [];
  keys.forEach(key => {
    const def = SHOP_CATEGORY_DEFS[key];
    if (!def) return;
    const items = def.catalog.filter(item => item.featured && !item.disabled);
    if (!items.length) return;
    sections.push(`<div class="shop-section-label">${esc(def.label)}</div><div class="${shopGridClass(key)}">${items.map(item => shopItemCardHTML(key, item)).join('')}</div>`);
  });
  wrap.innerHTML = sections.join('') || '<div class="shop-empty-state"><b>Nothing featured right now</b><span>Check the other tabs.</span></div>';
  wireShopCardButtons(wrap);
}

function renderShopCategoryPane(key) {
  const def = SHOP_CATEGORY_DEFS[key];
  const wrap = $('shop-pane-' + key);
  if (!def || !wrap) return;
  const q = ($('shop-search').value || '').trim().toLowerCase();
  const matches = (item) => !q || item.name.toLowerCase().includes(q);
  const animated = def.catalog.filter(i => i.animated && matches(i));
  const staticOnes = def.catalog.filter(i => !i.animated && matches(i));
  const gridCls = 'shop-grid' + ((key === 'themes' || key === 'banners') ? ' theme-shop-grid' : '');
  if (key === 'masks') {
    const list = def.catalog.filter(matches);
    wrap.innerHTML = `<div class="shop-section-label">Avatar Masks</div>` + (list.length
      ? `<div class="shop-grid">${list.map(i => shopItemCardHTML(key, i)).join('')}</div>`
      : `<div class="shop-empty-state"><b>${q ? 'No masks found' : 'No masks yet'}</b><span>${q ? 'Try a different search.' : 'Full avatar masks published by Frixion staff will show up here.'}</span></div>`);
    wireShopCardButtons(wrap);
    return;
  }
  if (key === 'music') {
    const list = def.catalog.filter(i => !i.disabled && matches(i));
    const now = def.catalog.find(t => t.id === myProfile.equippedMusic);
    wrap.innerHTML = `<div class="shop-section-label">Music</div>
      <div class="music-toolbar">
        <div class="mt-now">${now ? `<span class="mt-label">Now playing</span> ${esc(now.name)}` : 'Nothing equipped.'}</div>
        <label class="mt-vol"><span>Volume</span><input type="range" id="music-volume" min="0" max="100" value="${Math.round(musicVolume() * 100)}" aria-label="Music volume"></label>
      </div>` + (list.length
        ? `<div class="${shopGridClass(key)}">${list.map(i => shopItemCardHTML(key, i)).join('')}</div>`
        : `<div class="shop-empty-state"><b>${q ? 'No music found' : 'No music yet'}</b><span>${q ? 'Try a different search.' : 'New tracks will show up here.'}</span></div>`);
    wireShopCardButtons(wrap);
    $('music-volume').oninput = e => setMusicVolume(e.target.value / 100);
    return;
  }
  if (key === 'banners' && !def.catalog.length) {
    wrap.innerHTML = `<div class="shop-section-label">Banners</div><div class="shop-empty-state"><b>No banners yet</b><span>Gradient banners published by Frixion staff will show up here.</span></div>`;
    return;
  }
  wrap.innerHTML =
    `<div class="shop-section-label">Animated</div>` +
    `<div class="${gridCls}">${animated.map(i => shopItemCardHTML(key, i)).join('') || '<div class="empty">No animated items found.</div>'}</div>` +
    `<div class="shop-section-label">Not Animated</div>` +
    `<div class="${gridCls}">${staticOnes.map(i => shopItemCardHTML(key, i)).join('') || '<div class="empty">No items found.</div>'}</div>`;
  wireShopCardButtons(wrap);
}

function refreshOpenShopPanes() {
  if ($('shop-view').classList.contains('hidden')) return;
  $('shop-orb-amt').textContent = fmtOrbs(myProfile.orbs);
  renderShopFeatured();
  Object.keys(SHOP_CATEGORY_DEFS).forEach(renderShopCategoryPane);
}

async function buyShopItem(key, id) {
  const def = SHOP_CATEGORY_DEFS[key];
  const item = def && def.catalog.find(i => i.id === id);
  if (!item) return;
  if (item.disabled) { toast('That item is not available right now.', 'error'); return; }
  try {
    const fresh = (await db.collection('users').doc(myUid).get()).data();
    if ((fresh[def.ownedField] || []).includes(id)) { toast('You already own this.'); return; }
    if ((fresh.orbs || 0) < item.price) { toast('Not enough Orbs. Play games to earn more.'); return; }
    // The first purchase of a track with a cutscene plays it, so hold the music back until it ends.
    const cuts = itemCutscenes(item);
    const showCut = cuts.length && !epilepsyMode();   // Epilepsy mode: not played automatically (it can be replayed from the Shop)
    if (showCut) cutsceneActive = true;
    // Equip it immediately on purchase, matching how Discord's own shop works.
    await db.collection('users').doc(myUid).update({
      orbs: FieldValue.increment(-item.price),
      [def.ownedField]: FieldValue.arrayUnion(id),
      [def.equipField]: id,
    });
    toast(`Purchased ${item.name}!`);
    refreshOpenShopPanes();
    if (cuts.length && !showCut) toast('Epilepsy mode is on, so the cutscenes were skipped. You can replay them from the Shop.');
    if (showCut) {
      for (const c of cuts) await playCutscene(c.src);
      cutsceneActive = false;
      musicSync(myProfile && myProfile[def.equipField] === id ? id : (myProfile && myProfile.equippedMusic) || null);
    }
  } catch (e) { cutsceneActive = false; toast('Purchase failed.', 'error'); }
}

// Plays an unlocked item's cutscene again. The music stops while it plays and carries on afterwards.
function replayCutscene(key, id, seg) {
  const def = SHOP_CATEGORY_DEFS[key];
  const item = def && def.catalog.find(i => i.id === id);
  const cut = item && itemCutscenes(item)[seg || 0];
  if (!cut || !(myProfile[def.ownedField] || []).includes(id) || cutsceneActive) return;
  const run = async () => {
    cutsceneActive = true;
    if (musicAudio) try { musicAudio.pause(); } catch (e) {}
    try { await playCutscene(cut.src); } catch (e) {}
    cutsceneActive = false;
    if (musicAudio) musicAudio.play().catch(() => {});
    else musicSync((myProfile && myProfile.equippedMusic) || null);
  };
  if (epilepsyMode()) {
    confirmAction({ title: 'Flashing Lights Warning', body: 'Epilepsy mode is on, but this cutscene is a video and it may contain flashing lights that Frixion can\'t remove. Play it anyway?', confirmLabel: 'Play Cutscene', danger: false, onConfirm: run });
  } else run();
}

async function equipShopItem(key, id) {
  const def = SHOP_CATEGORY_DEFS[key];
  if (!def) return;
  try {
    await db.collection('users').doc(myUid).update({ [def.equipField]: id || null });
    toast(id ? 'Equipped.' : 'Unequipped.');
    refreshOpenShopPanes();
  } catch (e) { toast('Could not update.', 'error'); }
}

function openShop() {
  $('shop-orb-amt').textContent = fmtOrbs(myProfile.orbs);
  document.querySelectorAll('.shop-tab').forEach(t => t.classList.remove('on'));
  document.querySelector('.shop-tab[data-shop-tab="featured"]').classList.add('on');
  document.querySelectorAll('.shop-pane').forEach(p => p.classList.add('hidden'));
  $('shop-pane-featured').classList.remove('hidden');
  $('shop-search').value = '';
  renderShopFeatured();
  Object.keys(SHOP_CATEGORY_DEFS).forEach(renderShopCategoryPane);
}

function switchShopTab(tabKey, tabEl) {
  document.querySelectorAll('.shop-tab').forEach(t => t.classList.remove('on'));
  tabEl.classList.add('on');
  document.querySelectorAll('.shop-pane').forEach(p => p.classList.add('hidden'));
  $('shop-pane-' + tabKey).classList.remove('hidden');
  $('shop-browse-menu').classList.add('hidden');
}
document.querySelectorAll('.shop-tab[data-shop-tab]').forEach(tab => {
  tab.onclick = () => switchShopTab(tab.dataset.shopTab, tab);
});
document.querySelectorAll('.shop-browse-opt').forEach(opt => {
  opt.onclick = () => switchShopTab(opt.dataset.shopTab, $('shop-browse-toggle'));
});
$('shop-browse-toggle').onclick = (e) => { e.stopPropagation(); $('shop-browse-menu').classList.toggle('hidden'); };
document.addEventListener('click', (e) => { if (!e.target.closest('.shop-browse-wrap')) $('shop-browse-menu').classList.add('hidden'); });
$('shop-search').addEventListener('input', () => {
  const openPane = document.querySelector('.shop-pane:not(.hidden)');
  if (!openPane) return;
  const key = openPane.id.replace('shop-pane-', '');
  if (SHOP_CATEGORY_DEFS[key]) renderShopCategoryPane(key);
});

function renderThemeGrid() {
  const themeGrid = $('theme-grid');
  themeGrid.innerHTML = '';
  THEMES.forEach(t => {
    const locked = t.premium && !isPremium(myProfile);
    const card = document.createElement('div');
    card.className = `theme-card theme-swatch-${t.key}` + (locked ? ' locked' : '') + (((myProfile.theme || 'dark') === t.key) ? ' selected' : '');
    card.innerHTML = `<span>${esc(t.name)}</span>` + (locked ? `<span class="lock-badge">${icon('shield')}</span>` : '');
    card.onclick = async () => {
      if (locked) { openPremiumModal(); return; }
      await db.collection('users').doc(myUid).update({ theme: t.key });
    };
    themeGrid.appendChild(card);
  });
}

function renderQuests() { mountGameHubs(); }

$('save-account-btn').onclick = async () => {
  const uname = $('set-username').value.trim();
  if (!uname || uname === myProfile.username) { toast('Nothing to change.'); return; }
  toast("Username can't be changed after registration — it's your document ID.", 'error');
  $('set-username').value = myProfile.username;
};

// ============================================================
// ADMIN PANEL
// Staff are the accounts with op, coowner or owner on their user doc. (The old admin-password dialog was removed: the
// Admin Panel button only ever showed for staff, so the dialog could never appear.)
// ============================================================
function openAdminEntry() {
  if (isAdmin || isOwner) { openAdminPanel(); return; }
  toast('The Admin Panel is for Frixion staff.', 'error');
}

let adminSelectedUser = null;
function openAdminPanel() {
  $('admin-panel-title').textContent = isOwner ? 'Owner Panel' : 'Admin Panel';
  // Players and System Hub are two faces of the same panel — the owner sees
  // System Hub in Players' place (it does everything Players did, plus the
  // owner-only actions), never both at once.
  $('admin-tab-players').classList.toggle('hidden', isOwner);
  $('admin-tab-systemhub').classList.toggle('hidden', !isOwner);
  $('admin-tab-devices').classList.toggle('hidden', !isOwner);
  adminSelectedDevice = null;
  document.querySelectorAll('.admin-tab').forEach(t => t.classList.remove('on'));
  document.querySelectorAll('.admin-pane').forEach(p => p.classList.add('hidden'));
  const defaultTab = isOwner ? 'systemhub' : 'players';
  document.querySelector(`.admin-tab[data-admin-tab="${defaultTab}"]`).classList.add('on');
  $('admin-pane-' + defaultTab).classList.remove('hidden');
  openModal('admin-panel-modal');
  adminSelectedUser = null;
  renderAdminList();
}
$('admin-search').addEventListener('input', renderAdminList);
if ($('system-hub-search')) $('system-hub-search').addEventListener('input', renderAdminList);
if ($('devices-search')) $('devices-search').addEventListener('input', renderDevicesPane);
if ($('devices-cleanup-btn')) $('devices-cleanup-btn').onclick = adminCleanUpDevices;

document.querySelectorAll('.admin-tab').forEach(tab => {
  tab.onclick = () => {
    document.querySelectorAll('.admin-tab').forEach(t => t.classList.remove('on'));
    tab.classList.add('on');
    document.querySelectorAll('.admin-pane').forEach(p => p.classList.add('hidden'));
    $('admin-pane-' + tab.dataset.adminTab).classList.remove('hidden');
    if (tab.dataset.adminTab === 'devices') renderDevicesPane();
    if (tab.dataset.adminTab === 'emojis') renderAdminEmojiList();
    if (tab.dataset.adminTab === 'stickers') renderAdminStickerList();
    if (tab.dataset.adminTab === 'filter') renderAdminFilterList();
    if (tab.dataset.adminTab === 'codes') renderAdminCodesList();
    if (tab.dataset.adminTab === 'conversations') renderAdminConversationsList();
    if (tab.dataset.adminTab === 'shopmanage') {
      renderAdminDecorationList(); renderAdminMaskList(); initDecorationEditor();
      renderAdminThemeList(); initThemeEditor();
      renderAdminNameplateList(); initNameplateEditor();
      renderAdminProfileEffectList(); initEffectEditor();
      renderAdminProfileFrameList(); initFrameEditor();
      renderAdminBannerList(); initBannerEditor();
      renderAdminMusicList();
    }
    if (tab.dataset.adminTab === 'quests') { initGagAdmin(); initCcAdmin(); }
    if (tab.dataset.adminTab === 'systemhub') { adminSelectedUser = null; renderAdminList(); }
  };
});


// ---------- Quests (admin/owner/co-owner): Grow a Garden creator ----------
const GAG_SEED_FNS = { none: 'No special ability', gold: 'Mutation chance (+%)', multi: 'Extra crops per harvest (+N)', weight: 'Heavier fruit (+%)' };
const GAG_PET_FNS = { sell: 'Sell value (+%)', mult: 'Sheckle multiplier (×N)', growth: 'Grow speed (+%)', mutation: 'Mutation chance (+%)', discount: 'Seed discount (-%)' };
const GAG_KINDS = {
  seeds: { coll: 'gardenSeeds', label: 'seed', list: () => ggCustomSeeds },
  sprinklers: { coll: 'gardenSprinklers', label: 'sprinkler', list: () => ggCustomSprinklers },
  pets: { coll: 'gardenPets', label: 'pet', list: () => ggCustomPets },
};
let gagAdminInit = false;
const gagNum = (id, d = 0) => { const v = parseFloat($(id).value); return Number.isFinite(v) ? v : d; };
function initGagAdmin() {
  if (!gagAdminInit) {
    gagAdminInit = true;
    const rarOpts = Object.keys(GG_RARITY).map(k => `<option value="${k}">${esc(GG_RARITY[k].n)}</option>`).join('');
    ['gag-seed-rarity', 'gag-spr-rarity', 'gag-pet-rarity'].forEach(id => { $(id).innerHTML = rarOpts; });
    $('gag-seed-fn').innerHTML = Object.entries(GAG_SEED_FNS).map(([k, v]) => `<option value="${k}">${esc(v)}</option>`).join('');
    $('gag-pet-fn').innerHTML = Object.entries(GAG_PET_FNS).map(([k, v]) => `<option value="${k}">${esc(v)}</option>`).join('');
    document.querySelectorAll('button[data-quest-section]').forEach(tab => {
      tab.onclick = () => {
        document.querySelectorAll('button[data-quest-section]').forEach(t => t.classList.toggle('on', t === tab));
        document.querySelectorAll('.quest-section').forEach(sec => sec.classList.toggle('hidden', sec.dataset.questSection !== tab.dataset.questSection));
      };
    });
    document.querySelectorAll('button[data-gag-section]').forEach(tab => {
      tab.onclick = () => {
        document.querySelectorAll('button[data-gag-section]').forEach(t => t.classList.toggle('on', t === tab));
        document.querySelectorAll('.gag-section').forEach(sec => sec.classList.toggle('hidden', sec.dataset.gagSection !== tab.dataset.gagSection));
      };
    });
    $('gag-seed-publish').onclick = () => gagPublish('seeds');
    $('gag-spr-publish').onclick = () => gagPublish('sprinklers');
    $('gag-pet-publish').onclick = () => gagPublish('pets');
  }
  loadGardenContent().then(renderGagLists);
}
function gagCommon(prefix) {
  const name = ($(prefix + '-name').value || '').trim();
  const ic = ($(prefix + '-ic').value || '').trim();
  return { name, ic, rarity: $(prefix + '-rarity').value, cost: Math.max(0, Math.floor(gagNum(prefix + '-cost', 0))) };
}
async function gagPublish(kind) {
  if (!isAdmin && !isOwner) { toast('Admins only.', 'error'); return; }
  let item;
  if (kind === 'seeds') {
    item = gagCommon('gag-seed');
    item.grow = Math.max(1, gagNum('gag-seed-grow', 10)) * 1000;
    item.sell = Math.max(1, Math.floor(gagNum('gag-seed-sell', 10)));
    item.baseWeight = Math.max(0.01, gagNum('gag-seed-weight', 0.5));
    item.fn = $('gag-seed-fn').value;
    const fv = gagNum('gag-seed-fnval', 0);
    item.fnVal = item.fn === 'multi' ? Math.max(0, Math.floor(fv)) : Math.max(0, fv) / 100;
    if (item.fn === 'none') { item.fnVal = 0; }
  } else if (kind === 'sprinklers') {
    item = gagCommon('gag-spr');
    item.speed = Math.max(0, gagNum('gag-spr-speed', 0)) / 100;
    item.weight = Math.max(0, gagNum('gag-spr-weight', 0)) / 100;
    item.mutation = Math.max(0, gagNum('gag-spr-mut', 0)) / 100;
    item.sellBoost = Math.max(0, gagNum('gag-spr-sell', 0)) / 100;
    if (!(item.speed || item.weight || item.mutation || item.sellBoost)) { toast('Give the sprinkler at least one boost.'); return; }
  } else {
    item = gagCommon('gag-pet');
    item.fn = $('gag-pet-fn').value;
    const v = gagNum('gag-pet-val', 0);
    item.val = item.fn === 'mult' ? Math.max(1, v) : Math.max(0, v) / 100;
    if (!item.val) { toast('Enter a value for the pet\'s function.'); return; }
    if (item.fn === 'discount') item.val = Math.min(0.9, item.val);
  }
  if (!item.name) { toast('Enter a name.'); return; }
  if (!item.ic) { toast('Enter an emoji.'); return; }
  const def = GAG_KINDS[kind];
  item.id = 'c_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
  item.createdBy = myUid;
  try {
    await db.collection(def.coll).doc(item.id).set(item);
    await loadGardenContent();
    renderGagLists();
    toast(`Published the ${item.name} ${def.label}.`);
  } catch (e) { toast(e.message || 'Could not publish.', 'error'); }
}
function gagItemInfo(kind, it) {
  const pc = v => Math.round((v || 0) * 100) + '%';
  if (kind === 'seeds') return `${fmtNum(it.cost)} · ${ggGrowLabel(it.grow)} · sells ${fmtNum(it.sell)}${ggSeedFnText(it) ? ' · ' + ggSeedFnText(it) : ''}`;
  if (kind === 'sprinklers') return `${fmtNum(it.cost)} · +${pc(it.speed)} speed · +${pc(it.weight)} weight${it.mutation ? ' · +' + pc(it.mutation) + ' mutation' : ''}${it.sellBoost ? ' · +' + pc(it.sellBoost) + ' sell' : ''}`;
  return `${fmtNum(it.cost)} · ${ggPetAbility(it)}`;
}
function renderGagLists() {
  const builtin = { seeds: GG_BASE_SEEDS, sprinklers: GG_BASE_SPRINKLERS, pets: GG_BASE_PETS };
  Object.entries(GAG_KINDS).forEach(([kind, def]) => {
    const wrap = $('gag-list-' + kind);
    if (!wrap) return;
    const custom = ggSortByRarity(def.list());
    wrap.innerHTML = (custom.length ? custom.map(it => `<div class="gag-item" data-id="${esc(it.id)}">
        <span class="gag-item-ic">${esc(it.ic)}</span>
        <span class="gag-item-mid"><b>${esc(it.name)}</b> ${rarBadge(it.rarity)}<small>${esc(gagItemInfo(kind, it))}</small></span>
        <span class="gag-item-del" title="Delete">${icon('trash')}</span></div>`).join('')
      : `<div class="empty">No custom ${def.label}s yet.</div>`)
      + `<div class="admin-builtin-label">Built-in</div>` + builtin[kind].map(it => `<div class="gag-item builtin"><span class="gag-item-ic">${esc(it.ic)}</span><span class="gag-item-mid"><b>${esc(it.name)}</b> ${rarBadge(it.rarity)}<small>${esc(gagItemInfo(kind, it))}${it.requiresAll ? ' · needs everything in GAG' : ''}</small></span></div>`).join('');
    wrap.querySelectorAll('.gag-item-del').forEach(btn => {
      btn.onclick = () => {
        const id = btn.closest('.gag-item').dataset.id;
        const it = def.list().find(x => x.id === id);
        confirmAction({
          title: `Delete ${def.label}`, body: `Delete "${it ? it.name : 'this ' + def.label}"? Players who own it keep nothing from it.`, confirmLabel: 'Delete',
          onConfirm: async () => {
            try { await db.collection(def.coll).doc(id).delete(); await loadGardenContent(); renderGagLists(); }
            catch (e) { toast(e.message || 'Could not delete.', 'error'); }
          },
        });
      };
    });
  });
}

// ---------- Quests (admin/owner/co-owner): Cookie Clicker (CC) creator ----------
const CC_UP_FNS = {
  click: 'Click power (x N)',
  clickcps: 'Click bonus from cps (+N%)',
  building: 'One building/item (x N)',
  global: 'All production (+N%)',
  flat: 'Flat cookies/sec (+N)',
};
const CC_UP_HINTS = {
  click: 'Value is a multiplier above 1. 2 makes every click twice as strong.',
  clickcps: 'Value is a percentage. 1 means each click also gives +1% of your cookies per second.',
  building: 'Pick the building or item below. Value is a multiplier above 1. 2 doubles what that one makes.',
  global: 'Value is a percentage. 10 means every building and item makes 10% more.',
  flat: 'Value is cookies per second, added on top of your buildings.',
};
let ccAdminInit = false;
const ccNumField = id => { const raw = ($(id).value || '').trim(); return raw === '' ? NaN : parseFloat(raw); };
function initCcAdmin() {
  if (!ccAdminInit) {
    ccAdminInit = true;
    $('cc-up-fn').innerHTML = Object.entries(CC_UP_FNS).map(([k, v]) => `<option value="${k}">${esc(v)}</option>`).join('');
    $('cc-up-fn').onchange = ccUpFormSync;
    document.querySelectorAll('[data-cc-section]').forEach(tab => {
      if (tab.tagName !== 'BUTTON') return;
      tab.onclick = () => {
        document.querySelectorAll('button[data-cc-section]').forEach(t => t.classList.toggle('on', t === tab));
        document.querySelectorAll('.cc-section').forEach(sec => sec.classList.toggle('hidden', sec.dataset.ccSection !== tab.dataset.ccSection));
      };
    });
    $('cc-up-publish').onclick = () => ccPublish('upgrades');
    $('cc-it-publish').onclick = () => ccPublish('items');
    ['upgrades', 'items'].forEach(kind => {
      $('cc-list-' + kind).addEventListener('click', (e) => {
        const btn = e.target.closest('.gag-item-del');
        if (btn) ccDelete(kind, btn.closest('.gag-item').dataset.id);
      });
    });
    ccUpFormSync();
  }
  ccAdminRefresh();
}
function ccUpFormSync() {
  const fn = $('cc-up-fn').value;
  $('cc-up-target-field').classList.toggle('hidden', fn !== 'building');
  $('cc-up-hint').textContent = CC_UP_HINTS[fn] || '';
  $('cc-up-val').placeholder = fn === 'flat' ? '50' : (fn === 'click' || fn === 'building') ? '2' : '10';
}
// Rebuild the building pickers (they include staff-made items) and the two lists.
function ccAdminRefresh() {
  if (!ccAdminInit) return;
  const opts = ccProd.map(b => `<option value="${esc(b.id)}">${esc(b.ic)} ${esc(b.name)}${b.custom ? ' (item)' : ''}</option>`).join('');
  [['cc-up-target', ''], ['cc-up-req', '<option value="">Always available</option>']].forEach(([id, first]) => {
    const sel = $(id), keep = sel.value;
    sel.innerHTML = first + opts;
    if (keep && [...sel.options].some(o => o.value === keep)) sel.value = keep;
  });
  const row = (it, ic, mid, info, deletable) => `<div class="gag-item${deletable ? '' : ' builtin'}" data-id="${esc(it.id)}">
      <span class="gag-item-ic">${esc(ic)}</span>
      <span class="gag-item-mid"><b>${esc(mid)}</b><small>${esc(info)}</small></span>
      ${deletable ? `<span class="gag-item-del" title="Delete">${icon('trash')}</span>` : ''}</div>`;
  $('cc-list-upgrades').innerHTML = ccUpgrades.length
    ? ccUpgrades.map(u => row(u, u.ic, u.name, `${fmtNum(u.cost)} cookies · ${ccEffectText(u)}${ccReqText(u) ? ' · ' + ccReqText(u) : ''}`, true)).join('')
    : '<div class="empty">No upgrades yet.</div>';
  $('cc-list-items').innerHTML = (ccItems.length
    ? ccItems.map(it => row(it, it.ic, it.name, `${fmtNum(it.cost)} cookies · ${ckNum(it.cps)}/s each · price +${Math.round((it.growth - 1) * 100)}% per one owned`, true)).join('')
    : '<div class="empty">No custom items yet.</div>')
    + '<div class="admin-builtin-label">Built-in buildings</div>'
    + COOKIE_BUILDINGS.map(b => row(b, b.ic, b.name, `${fmtNum(b.base)} cookies · ${ckNum(b.cps)}/s each`, false)).join('');
}
async function ccPublish(kind) {
  if (!isAdmin && !isOwner) { toast('Admins only.', 'error'); return; }
  const p = kind === 'upgrades' ? 'cc-up' : 'cc-it';
  const name = ($(p + '-name').value || '').trim(), ic = ($(p + '-ic').value || '').trim();
  if (!name) { toast('Enter a name.'); return; }
  if (!ic) { toast('Enter an emoji.'); return; }
  const cost = ccNumField(p + '-cost');
  let item, clean;
  if (kind === 'upgrades') {
    const fn = $('cc-up-fn').value, val = ccNumField('cc-up-val');
    if (!(cost >= 0)) { toast('Enter a price (0 or more).'); return; }
    if (!(val > 0)) { toast('Enter an effect value above 0.'); return; }
    if ((fn === 'click' || fn === 'building') && !(val > 1)) { toast('For a multiplier the value has to be above 1. 2 means twice as strong.'); return; }
    const reqId = $('cc-up-req').value, reqN = reqId ? Math.max(1, Math.floor(ccNumField('cc-up-reqn') || 1)) : 1;
    item = { name, ic, cost, fn, val, target: fn === 'building' ? $('cc-up-target').value : '', reqId, reqN };
    item.id = 'cu_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
    clean = ccCleanUpgrade(item);
  } else {
    const cps = ccNumField('cc-it-cps');
    let growth = ccNumField('cc-it-growth'); if (!(growth >= 1)) growth = 15; growth = Math.min(100, growth);
    if (!(cost >= 1)) { toast('Enter a starting price of at least 1 cookie.'); return; }
    if (!(cps > 0)) { toast('Enter cookies per second above 0.'); return; }
    item = { name, ic, cost, cps, growth: 1 + growth / 100 };
    item.id = 'ci_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
    clean = ccCleanItem(item);
  }
  if (!clean) { toast('One of those numbers is out of range. Try something smaller.', 'error'); return; }
  clean.createdBy = myUid;
  const btn = $(p + '-publish'); btn.disabled = true;
  try {
    await CC_DOC().set({ [kind]: { [clean.id]: clean } }, { merge: true });
    toast(`Published ${clean.name}.`);
    $(p + '-name').value = ''; $(p + '-ic').value = '';
  } catch (e) { toast(e.message || 'Could not publish.', 'error'); }
  finally { btn.disabled = false; }
}
function ccDelete(kind, id) {
  if (!isAdmin && !isOwner) return;
  const it = (kind === 'upgrades' ? ccUpgrades : ccItems).find(x => x.id === id);
  const noun = kind === 'upgrades' ? 'upgrade' : 'item';
  confirmAction({
    title: `Delete ${noun}`,
    body: `Delete "${it ? it.name : 'this ' + noun}"? Players who own it lose it.${kind === 'items' ? ' Upgrades that point at it stop showing up.' : ''}`,
    confirmLabel: 'Delete',
    onConfirm: async () => {
      try { await CC_DOC().update({ [kind + '.' + id]: FieldValue.delete() }); }
      catch (e) { toast(e.message || 'Could not delete.', 'error'); }
    },
  });
}

