// ---------- Staff: add a song ----------
const isHttpsUrl = (u) => typeof u === 'string' && /^https:\/\//i.test(u);
function subscribeCustomMusic() {
  db.collection('config').doc('customMusic').onSnapshot(doc => {
    const data = (doc.exists && doc.data()) || {};
    customMusicTracks = Object.entries(data)
      .filter(([, v]) => v && typeof v === 'object' && isHttpsUrl(v.src) && v.name)
      .map(([id, v]) => ({
        id, ...v, price: Number(v.price) || 0, featured: !!v.featured,
        desc: v.desc || 'Plays on a loop for as long as you are signed in.',
        banner: isHttpsUrl(v.banner) ? v.banner : null, disabled: !!v.disabled,
        cutscenes: (Array.isArray(v.cutscenes) ? v.cutscenes : []).filter(c => c && isHttpsUrl(c.src)).slice(0, 3).map(c => ({ src: c.src, label: String(c.label || 'Animation').slice(0, 20) })),
      }))
      .sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
    refreshOpenShopPanes();
    if (!$('admin-panel-modal').classList.contains('hidden')) renderAdminMusicList();
    // The equipped song may be one of these, and it can't start until the list has loaded.
    if (typeof myProfile !== 'undefined' && myProfile) musicSync(myProfile.equippedMusic || null);
  }, err => console.warn('customMusic listener failed.', err));
}
const MUSIC_MAX_ANIMATIONS = 3;
function updateMusicAnimControls() {
  const n = $('music-anim-rows').children.length;
  $('music-anim-count').textContent = `${n}/${MUSIC_MAX_ANIMATIONS}`;
  $('music-anim-add').classList.toggle('hidden', n >= MUSIC_MAX_ANIMATIONS);
}
function addMusicAnimRow() {
  const wrap = $('music-anim-rows');
  if (wrap.children.length >= MUSIC_MAX_ANIMATIONS) return;
  const row = document.createElement('div');
  row.className = 'music-anim-row';
  row.innerHTML = `<input type="text" class="fld-input music-anim-name" maxlength="20" placeholder="Name, e.g. Animation"><input type="file" class="music-anim-file" accept="video/*,.mp4,.webm,.mov"><button type="button" class="btn-secondary slim music-anim-rm" title="Remove this animation">&times;</button>`;
  row.querySelector('.music-anim-rm').onclick = () => { row.remove(); updateMusicAnimControls(); };
  wrap.append(row);
  updateMusicAnimControls();
}
// If the page's HTML is older than this script (a cached index.html, say), these elements are missing; skip quietly rather than stop the whole app from starting.
($('music-anim-add') || {}).onclick = addMusicAnimRow;
let musicPreviewUrl = null;
function updateMusicCardPreview() {
  const host = $('music-card-preview');
  if (!host) return;
  try {
  const f = $('music-banner-input').files[0];
  if (musicPreviewUrl) { URL.revokeObjectURL(musicPreviewUrl); musicPreviewUrl = null; }
  if (f && f.type.startsWith('image/')) musicPreviewUrl = URL.createObjectURL(f);
  host.innerHTML = shopItemPreviewHTML('music', { id: 'preview', name: ($('music-name-input').value || '').trim() || 'Song name', banner: musicPreviewUrl });
  } catch (e) { console.warn('Song card preview failed.', e); }
}
if ($('music-banner-input')) $('music-banner-input').addEventListener('change', updateMusicCardPreview);
if ($('music-name-input')) $('music-name-input').addEventListener('input', updateMusicCardPreview);
($('music-publish-btn') || {}).onclick = async () => {
  if (!isAdmin && !isOwner) { toast('Admins only.', 'error'); return; }
  const name = ($('music-name-input').value || '').trim();
  const desc = ($('music-desc-input').value || '').trim() || 'Plays on a loop for as long as you are signed in.';
  const price = parseInt($('music-price-input').value, 10);
  const audio = $('music-audio-input').files[0];
  const bannerFile = $('music-banner-input').files[0];
  const rows = [...$('music-anim-rows').children].map(r => ({ label: r.querySelector('.music-anim-name').value.trim(), file: r.querySelector('.music-anim-file').files[0] }));
  if (!name) { toast('Enter a name.'); return; }
  if (!Number.isFinite(price) || price < 0) { toast('Enter a valid price.'); return; }
  if (!audio) { toast('Choose the song\'s audio file.'); return; }
  if (!isMediaFile(audio) || (audio.type && !audio.type.startsWith('audio/') && !AUDIO_FILE_EXT.test(audio.name))) { toast('The song has to be an audio file (mp3, wav, ogg, m4a...).', 'error'); return; }
  if (audio.size > MAX_MEDIA_MB * 1024 * 1024) { toast(`The song is over ${MAX_MEDIA_MB}MB.`, 'error'); return; }
  if (bannerFile && (!bannerFile.type.startsWith('image/') || bannerFile.size > MAX_FILE_MB * 1024 * 1024)) { toast(`The banner has to be an image under ${MAX_FILE_MB}MB.`, 'error'); return; }
  for (const [i, r] of rows.entries()) {
    if (!r.label || !r.file) { toast(`Animation ${i + 1} needs both a name and a video file.`); return; }
    if (!isMediaFile(r.file) || r.file.size > MAX_MEDIA_MB * 1024 * 1024) { toast(`Animation ${i + 1} has to be a video under ${MAX_MEDIA_MB}MB.`, 'error'); return; }
  }
  const btn = $('music-publish-btn'), status = $('music-publish-status');
  btn.disabled = true;
  try {
    const prog = label => pct => { status.textContent = `${label}… ${pct}%`; };
    status.textContent = 'Uploading the song… 0%';
    const src = await uploadFileToCloudinary(audio, prog('Uploading the song'));
    let banner = null;
    if (bannerFile) { status.textContent = 'Uploading the banner…'; banner = await uploadImageToCloudinary(bannerFile, prog('Uploading the banner')); }
    const cutscenes = [];
    for (const [i, r] of rows.entries()) {
      status.textContent = `Uploading animation ${i + 1} of ${rows.length}… 0%`;
      cutscenes.push({ src: await uploadFileToCloudinary(r.file, prog(`Uploading animation ${i + 1} of ${rows.length}`)), label: r.label });
    }
    status.textContent = 'Publishing…';
    const id = 'cm-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    const track = { name, desc, price, featured: $('music-featured-input').checked, src, cutscenes, createdBy: myUid, createdAt: Date.now() };
    if (banner) track.banner = banner;
    await db.collection('config').doc('customMusic').set({ [id]: track }, { merge: true });
    ['music-name-input', 'music-desc-input', 'music-price-input', 'music-audio-input', 'music-banner-input'].forEach(i => { $(i).value = ''; }); updateMusicCardPreview();
    $('music-featured-input').checked = false;
    $('music-anim-rows').innerHTML = '';
    updateMusicAnimControls();
    status.textContent = '';
    toast(`Published "${name}" to the shop!`);
  } catch (e) {
    status.textContent = '';
    toast(e.message || 'Failed to publish the song.', 'error');
  } finally { btn.disabled = false; }
};

// ---------- Shop item editor (admin/owner only) ----------
// Published (Firestore) items are edited in place. Built-in catalog items
// can't be rewritten in code, so their edits are stored as overrides in
// config/shopOverrides and merged onto the built-in objects at runtime.
const SHOP_EDIT_TYPES = {
  decorations: { label: 'Avatar Decoration', collection: 'shopDecorations', builtins: AVATAR_DECORATIONS, custom: () => customDecorations.filter(d => !d.mask), render: () => renderAdminDecorationList() },
  masks: { label: 'Avatar Mask', collection: 'shopDecorations', builtins: [], custom: () => customDecorations.filter(d => d.mask), render: () => renderAdminMaskList() },
  themes: { label: 'Theme', collection: 'shopThemes', builtins: SHOP_THEMES, custom: () => customThemes, render: () => renderAdminThemeList() },
  banners: { label: 'Banner', collection: 'shopBanners', builtins: [], custom: () => customBanners, render: () => renderAdminBannerList() },
  nameplates: { label: 'Nameplate', collection: 'shopNameplates', builtins: NAMEPLATES, custom: () => customNameplates, render: () => renderAdminNameplateList() },
  profile_effects: { label: 'Profile Effect', collection: 'shopProfileEffects', builtins: PROFILE_EFFECTS, custom: () => customProfileEffects, render: () => renderAdminProfileEffectList() },
  profile_frames: { label: 'Profile Frame', collection: 'shopProfileFrames', builtins: PROFILE_FRAMES, custom: () => customProfileFrames, render: () => renderAdminProfileFrameList() },
  // Any staff can change a song's name, description, price and Featured, and disable one they added. Only the Owner and Co-Owners
  // (isOwner) can change a song's files (audio, banner, animations) or delete a staff-made song. Built-in songs keep their files in code,
  // so file changes to those are stored as overrides in config/shopOverrides. Staff-made songs live in config/customMusic.
  music: { label: 'Music', collection: null, builtins: MUSIC_TRACKS, custom: () => customMusicTracks, render: () => renderAdminMusicList(), priceFeaturedOnly: true },
};
function renderAdminMusicList() {
  const wrap = $('admin-music-list');
  if (!wrap) return;
  wrap.innerHTML = '';
  if (customMusicTracks.length) {
    wrap.insertAdjacentHTML('beforeend', `<div class="admin-builtin-label">Added by staff</div>` + customMusicTracks.map(t =>
      `<div class="admin-emoji-chip editable" data-id="${esc(t.id)}"><span>${esc(t.name)}</span><span class="admin-chip-tag">${esc(Number(t.price).toLocaleString())}${t.featured ? ' · Featured' : ''}${(t.cutscenes || []).length ? ` · ${t.cutscenes.length} anim` : ''}${t.disabled ? ' · Disabled' : ''}</span></div>`).join(''));
  }
  finishAdminShopList(wrap, 'music');
}
const colorField = (path, label) => ({ path, label, type: 'color' });
const SHOP_EDIT_EXTRA_FIELDS = {
  music: () => [],
  decorations: item => [
    ...(decoEmojiLayers(item).length ? [{ path: 'emojis', label: 'Emoji layout', type: 'emoji-layout', full: true }] : []),
    { path: 'mask', label: 'Full avatar mask (moves it to the Avatar Masks section)', type: 'checkbox' },
  ],
  masks: item => [
    ...(decoEmojiLayers(item).length ? [{ path: 'emojis', label: 'Emoji layout', type: 'emoji-layout', full: true }] : []),
    { path: 'mask', label: 'Full avatar mask (untick to move it back to Decorations)', type: 'checkbox' },
  ],
  themes: () => [colorField('bg.0', 'Color 1'), colorField('bg.1', 'Color 2'), colorField('bg.2', 'Color 3'), colorField('accent', 'Accent'), colorField('accent2', 'Accent 2')],
  banners: () => [colorField('colors.0', 'Color 1'), colorField('colors.1', 'Color 2'), colorField('colors.2', 'Color 3'), { path: 'angle', label: 'Angle', type: 'number' }, { path: 'animated', label: 'Animated', type: 'checkbox' }],
  nameplates: () => [colorField('colors.0', 'Color 1'), colorField('colors.1', 'Color 2'), { path: 'animated', label: 'Shimmer', type: 'checkbox' }],
  profile_effects: () => [colorField('color', 'Particle Color'), { path: 'style', label: 'Movement', type: 'select', options: ['falling', 'rising', 'floating', 'twinkling'] }],
  profile_frames: () => [colorField('color', 'Border Color'), { path: 'glow', label: 'Glowing', type: 'checkbox' }],
};
const shopOverrideKey = (type, id) => `${type}__${id}`;
const builtinShopOriginals = new Map();
let shopOverrides = {};

function applyShopOverrides() {
  Object.entries(SHOP_EDIT_TYPES).forEach(([type, def]) => {
    def.builtins.forEach(item => {
      const key = shopOverrideKey(type, item.id);
      if (!builtinShopOriginals.has(key)) builtinShopOriginals.set(key, { name: item.name, desc: item.desc, price: item.price, featured: !!item.featured, ...(type === 'music' ? { banner: item.banner || null, bannerPos: item.bannerPos || null, src: item.src, cutscenes: item.cutscenes || null, shake: !!item.shake, bars: item.bars || null } : {}) });
      Object.assign(item, builtinShopOriginals.get(key), shopOverrides[key] || {});
      // The shake and the bars are timed to the original recording, so they stop if the audio file is replaced.
      if (type === 'music' && shopOverrides[key] && shopOverrides[key].src) { item.shake = false; item.bars = null; }
    });
  });
}
function subscribeShopOverrides() {
  db.collection('config').doc('shopOverrides').onSnapshot(doc => {
    // Only these fields may be changed on a built-in item, and they are cleaned like any staff-made item.
    const allowed = ['name', 'desc', 'price', 'featured', 'banner', 'bannerPos', 'src', 'cutscenes', 'disabled'];
    shopOverrides = {};
    Object.entries((doc.exists && doc.data()) || {}).forEach(([key, v]) => {
      if (!v || typeof v !== 'object') return;
      const picked = {};
      allowed.forEach(k => { if (k in v) picked[k] = v[k]; });
      const c = cleanCatalogItem(picked);
      if (!c.src) delete c.src;                         // a bad replacement file must not wipe out the song's own audio
      shopOverrides[key] = c;
    });
    applyShopOverrides();
    refreshOpenShopPanes();
    if (!$('admin-panel-modal').classList.contains('hidden')) Object.values(SHOP_EDIT_TYPES).forEach(d => d.render());
  }, err => console.warn('shopOverrides listener failed.', err));
}

function builtinChipVisual(type, item) {
  if (type === 'decorations' && item.svg) return `<span class="admin-chip-deco" aria-hidden="true">${item.svg(22)}</span>`;
  if (type === 'themes') return `<span class="admin-theme-chip-swatch" style="background:linear-gradient(135deg, ${item.bg[0]}, ${item.bg[1]}, ${item.bg[2]});"></span>`;
  return '';
}
// ---- Who made a shop item, and who may change it ----
// Every item staff publish records createdBy. Only that person, or someone of a strictly higher rank (Owner > Co-Owner > Admin),
// can edit, disable or delete it. Items with no creator on record (the built-in ones, and very old ones) stay open to all staff.
const shopItemCreator = item => (item && typeof item.createdBy === 'string' && item.createdBy) ? item.createdBy : null;
function canEditShopItem(item) {
  const by = shopItemCreator(item);
  if (!by || by === myUid) return true;
  const theirs = profileCache[by];
  if (!theirs) return false;                       // their rank isn't known yet: stay locked until it is
  return platformRank(myProfile) > platformRank(theirs);
}
const shopCreatorName = by => { const p = profileCache[by]; return (p && displayNameOf(p)) || by; };
const shopCreatorRequested = new Set();
// Looks up the creators of a list's items once, then draws the list again so the "by" names and locks are right.
function loadShopCreators(type, items) {
  const need = [...new Set(items.map(shopItemCreator).filter(Boolean))].filter(u => !profileCache[u] && !shopCreatorRequested.has(u));
  if (!need.length) return;
  need.forEach(u => shopCreatorRequested.add(u));
  Promise.all(need.map(getProfile)).then(() => { if (!$('admin-panel-modal').classList.contains('hidden')) SHOP_EDIT_TYPES[type].render(); });
}
function finishAdminShopList(wrap, type) {
  const def = SHOP_EDIT_TYPES[type];
  loadShopCreators(type, def.custom());
  wrap.querySelectorAll('.admin-emoji-chip[data-id]:not([data-builtin])').forEach(chip => {
    const item = def.custom().find(x => x.id === chip.dataset.id);
    const by = shopItemCreator(item);
    if (!by) return;
    const allowed = canEditShopItem(item);
    const tag = document.createElement('span');
    tag.className = 'admin-chip-by';
    tag.textContent = `by ${shopCreatorName(by)}`;
    chip.querySelector('.rm') ? chip.insertBefore(tag, chip.querySelector('.rm')) : chip.append(tag);
    if (!allowed) { chip.classList.add('locked'); const rm = chip.querySelector('.rm'); if (rm) rm.remove(); }
  });
  if (def.builtins.length) {
    wrap.insertAdjacentHTML('beforeend', `<div class="admin-builtin-label">Built-in</div>` + def.builtins.map(item =>
      `<div class="admin-emoji-chip editable" data-id="${esc(item.id)}" data-builtin="1">${builtinChipVisual(type, item)}<span>${esc(item.name)}</span><span class="admin-chip-tag">${esc(Number(item.price).toLocaleString())}${item.featured ? ' · Featured' : ''}</span></div>`
    ).join(''));
  }
  wrap.querySelectorAll('.admin-emoji-chip.editable').forEach(chip => {
    chip.title = 'Click to edit';
    chip.onclick = (e) => { if (e.target.closest('.rm')) return; openShopItemEditor(type, chip.dataset.id); };
  });
}

const getByPath = (obj, path) => path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
let shopEditTarget = null;
let shopEditBannerUrl = null;

async function openShopItemEditor(type, id) {
  if (!isAdmin && !isOwner) return;
  const def = SHOP_EDIT_TYPES[type];
  const custom = def.custom().find(x => x.id === id);
  const item = custom || def.builtins.find(x => x.id === id);
  if (!item) return;
  if (custom && shopItemCreator(custom)) {
    await getProfile(shopItemCreator(custom));
    if (!canEditShopItem(custom)) { toast(`${shopCreatorName(shopItemCreator(custom))} made this, so only they or a higher rank can change it.`, 'error'); return; }
  }
  shopEditTarget = { type, id, isCustom: !!custom };
  $('shop-edit-title').textContent = `Edit ${item.name}`;
  const locked = !!def.priceFeaturedOnly && !custom;
  $('shop-edit-name').disabled = false; $('shop-edit-desc').disabled = false;   // built-in songs can be renamed and re-described too (audio and cutscenes stay as coded)
  $('shop-edit-kind').textContent = custom ? def.label + (shopItemCreator(custom) ? ` · Created by ${shopCreatorName(shopItemCreator(custom))}` : '') : locked ? `${def.label} · Built-in (name, description, price, featured and banner can be changed)` : `${def.label} · Built-in (name, description, price and featured can be changed)`;
  $('shop-edit-name').value = item.name || '';
  $('shop-edit-desc').value = item.desc || '';
  $('shop-edit-price').value = Number.isFinite(Number(item.price)) ? item.price : 0;
  $('shop-edit-featured').checked = !!item.featured;
  const fields = custom ? SHOP_EDIT_EXTRA_FIELDS[type](item) : [];
  $('shop-edit-extra').innerHTML = fields.map((f, i) => {
    const val = getByPath(item, f.path);
    const inputId = `shop-edit-x${i}`;
    if (f.type === 'emoji-layout') return `<div class="field full"><label>${esc(f.label)}</label><div id="${inputId}" class="eml-host" data-path="${f.path}" data-type="emoji-layout"></div></div>`;
    if (f.type === 'checkbox') return `<label class="shop-edit-check field full"><input type="checkbox" id="${inputId}" data-path="${f.path}" data-type="checkbox"${val ? ' checked' : ''}> ${esc(f.label)}</label>`;
    if (f.type === 'select') return `<div class="field full"><label for="${inputId}">${esc(f.label)}</label><select id="${inputId}" data-path="${f.path}" data-type="select">${f.options.map(o => `<option value="${o}"${o === val ? ' selected' : ''}>${o[0].toUpperCase() + o.slice(1)}</option>`).join('')}</select></div>`;
    const safeVal = f.type === 'color' ? (/^#[0-9a-f]{6}$/i.test(val || '') ? val : '#ffffff') : (val ?? '');
    return `<div class="field${f.full ? ' full' : ''}"><label for="${inputId}">${esc(f.label)}</label><input type="${f.type}" id="${inputId}" data-path="${f.path}" data-type="${f.type}" value="${esc(String(safeVal))}"${f.type === 'number' ? ' min="0" max="360"' : ''}></div>`;
  }).join('');
  $('shop-edit-extra').querySelectorAll('.eml-host').forEach(h => {
    h._editor = createEmojiLayoutEditor(h, decoEmojiLayers(item), { mask: !!item.mask });
    const maskBox = $('shop-edit-extra').querySelector('[data-path="mask"]');
    if (maskBox) maskBox.addEventListener('change', () => h._editor.setMask(maskBox.checked));
  });
  if (type === 'music') {
    const canFiles = isOwner;   // Owner and Co-Owners only: audio, banner and animations (and deleting a song)
    const ovr = shopOverrides[shopOverrideKey(type, id)];
    const fileName = u => { try { return decodeURIComponent(String(u || '').split('?')[0].split('/').pop()) || 'file'; } catch (e) { return 'file'; } };
    $('shop-edit-extra').insertAdjacentHTML('beforeend', (canFiles
      ? `<div class="field full shop-edit-files"><label>Song audio</label>
           <div class="sef-note">Now playing: <b>${esc(fileName(item.src))}</b>${!custom ? ' (built in)' : ''}. Choose a file to replace it.${!custom ? ' If you replace a built-in song\'s audio, its screen shake and bars switch off, because they were timed to the original recording.' : ''}</div>
           <input type="file" id="shop-edit-audio-file" accept="audio/*,.mp3,.wav,.ogg,.m4a,.aac,.flac,.opus" class="music-file-input"></div>
         <div class="field full shop-edit-banner"><label>Banner (shown behind the name on its Shop card)</label><div id="shop-edit-banner-preview"></div><input type="file" id="shop-edit-banner-file" accept="image/*" class="music-file-input">${!custom && ovr && 'banner' in ovr ? '<button type="button" class="btn-secondary slim" id="shop-edit-banner-restore">Restore original</button>' : ''}</div>
         <div class="field full shop-edit-files"><label>Animations (up to ${MUSIC_MAX_ANIMATIONS}, played one after another when someone first buys it)</label>
           <div id="shop-edit-anims"></div>
           <button type="button" class="btn-secondary slim" id="shop-edit-anim-add">+ Add animation</button></div>`
      : `<div class="field full sef-locked">Only the Owner and Co-Owners can change a song's audio, banner or animations, or delete it. You can still change the name, description, price and Featured, and disable songs you added.</div>`)
      + (custom ? `<label class="shop-edit-check field full"><input type="checkbox" id="shop-edit-disabled"${item.disabled ? ' checked' : ''}> Disabled (hidden from the Shop, nobody can buy it)</label>` : ''));
    if (canFiles) {
      const refresh = () => {
        const f = $('shop-edit-banner-file').files[0];
        if (shopEditBannerUrl) { URL.revokeObjectURL(shopEditBannerUrl); shopEditBannerUrl = null; }
        if (f && f.type.startsWith('image/')) shopEditBannerUrl = URL.createObjectURL(f);
        const banner = shopEditBannerUrl || item.banner || null;
        $('shop-edit-banner-preview').innerHTML = shopItemPreviewHTML('music', { ...item, name: $('shop-edit-name').value || item.name, banner, bannerPos: shopEditBannerUrl ? null : item.bannerPos, fx: null });
      };
      $('shop-edit-banner-file').onchange = refresh;
      const restoreBtn = $('shop-edit-banner-restore');
      if (restoreBtn) restoreBtn.onclick = async () => {
        restoreBtn.disabled = true;
        try {
          // Dropping the staff override puts back the banner written in MUSIC_TRACKS (the Banners folder).
          await db.collection('config').doc('shopOverrides').set({ [shopOverrideKey(type, id)]: { banner: FieldValue.delete(), bannerPos: FieldValue.delete() } }, { merge: true });
          closeModal('shop-edit-modal');
          toast('Original banner restored.');
        } catch (e) { restoreBtn.disabled = false; toast(e.message || 'Could not restore the banner.', 'error'); }
      };
      refresh();
      // Animation rows: a name, the current video (kept unless a new file is chosen) and a remove button.
      const animWrap = $('shop-edit-anims');
      const syncAnimAdd = () => { $('shop-edit-anim-add').classList.toggle('hidden', animWrap.children.length >= MUSIC_MAX_ANIMATIONS); };
      const addAnimRow = (label, src) => {
        if (animWrap.children.length >= MUSIC_MAX_ANIMATIONS) return;
        const row = document.createElement('div');
        row.className = 'music-anim-row sef-anim-row';
        row.dataset.src = src || '';
        row.innerHTML = `<input type="text" class="fld-input music-anim-name" maxlength="20" placeholder="Name, e.g. Animation" value="${esc(label || '')}"><input type="file" class="music-anim-file" accept="video/*,.mp4,.webm,.mov"><button type="button" class="btn-secondary slim music-anim-rm" title="Remove this animation">&times;</button>
          <div class="sef-note">${src ? `Current video: <b>${esc(fileName(src))}</b>. Leave the file empty to keep it.` : 'Choose a video file.'}</div>`;
        row.querySelector('.music-anim-rm').onclick = () => { row.remove(); syncAnimAdd(); };
        animWrap.append(row); syncAnimAdd();
      };
      itemCutscenes(item).forEach(c => addAnimRow(c.label, c.src));
      $('shop-edit-anim-add').onclick = () => addAnimRow('', '');
      syncAnimAdd();
    }
  }
  $('shop-edit-delete-btn').classList.toggle('hidden', !custom || (type === 'music' && !isOwner));   // only the Owner and Co-Owners can delete a song; everyone else can only disable it
  $('shop-edit-reset-btn').classList.toggle('hidden', !!custom || !shopOverrides[shopOverrideKey(type, id)]);
  openModal('shop-edit-modal');
}

$('shop-edit-save-btn').onclick = async () => {
  if (!shopEditTarget || (!isAdmin && !isOwner)) return;
  const { type, id, isCustom } = shopEditTarget;
  const def = SHOP_EDIT_TYPES[type];
  if (isCustom && !canEditShopItem(def.custom().find(x => x.id === id))) { toast('You can not change this item.', 'error'); return; }
  const priceFeaturedOnly = !!def.priceFeaturedOnly && !isCustom;
  const name = $('shop-edit-name').value.trim();
  const desc = $('shop-edit-desc').value.trim();
  const price = parseInt($('shop-edit-price').value, 10);
  if (!name) { toast('Enter a name.'); return; }
  if (!desc) { toast('Enter a description.'); return; }
  if (!Number.isFinite(price) || price < 0) { toast('Enter a valid price.'); return; }
  const update = { name, desc, price, featured: $('shop-edit-featured').checked };
  try {
    if (type === 'music') {
      const f = $('shop-edit-banner-file') && $('shop-edit-banner-file').files[0];
      if (f && (!f.type.startsWith('image/') || f.size > MAX_FILE_MB * 1024 * 1024)) { toast(`The banner has to be an image under ${MAX_FILE_MB}MB.`, 'error'); return; }
      const canFiles = isOwner && !!$('shop-edit-anims');
      if (canFiles) {
        const audio = $('shop-edit-audio-file').files[0];
        if (audio && (!isMediaFile(audio) || (audio.type && !audio.type.startsWith('audio/') && !AUDIO_FILE_EXT.test(audio.name)))) { toast('The song has to be an audio file (mp3, wav, ogg, m4a...).', 'error'); return; }
        if (audio && audio.size > MAX_MEDIA_MB * 1024 * 1024) { toast(`The song is over ${MAX_MEDIA_MB}MB.`, 'error'); return; }
        const rows = [...$('shop-edit-anims').children].map(r => ({ label: r.querySelector('.music-anim-name').value.trim(), file: r.querySelector('.music-anim-file').files[0], src: r.dataset.src }));
        for (const [i, r] of rows.entries()) {
          if (!r.label) { toast(`Animation ${i + 1} needs a name.`); return; }
          if (!r.file && !r.src) { toast(`Animation ${i + 1} needs a video file.`); return; }
          if (r.file && (!isMediaFile(r.file) || r.file.size > MAX_MEDIA_MB * 1024 * 1024)) { toast(`Animation ${i + 1} has to be a video under ${MAX_MEDIA_MB}MB.`, 'error'); return; }
        }
        $('shop-edit-save-btn').disabled = true;
        try {
          if (f) { toast('Uploading the banner…'); update.banner = await uploadImageToCloudinary(f); update.bannerPos = null; }
          if (audio) { toast('Uploading the song…'); update.src = await uploadFileToCloudinary(audio, () => {}); }
          const cuts = [];
          for (const [i, r] of rows.entries()) {
            if (r.file) toast(`Uploading animation ${i + 1} of ${rows.length}…`);
            cuts.push({ src: r.file ? await uploadFileToCloudinary(r.file, () => {}) : r.src, label: r.label.slice(0, 20) });
          }
          const before = JSON.stringify(itemCutscenes(def.custom().find(x => x.id === id) || def.builtins.find(x => x.id === id) || {}).map(c => [c.label, c.src]));
          // A built-in song only stores what was actually changed; its original files stay as the fallback.
          if (isCustom || JSON.stringify(cuts.map(c => [c.label, c.src])) !== before) update.cutscenes = cuts;
        } finally { $('shop-edit-save-btn').disabled = false; }
      }
    }
    if (isCustom) {
      const item = def.custom().find(x => x.id === id) || {};
      $('shop-edit-extra').querySelectorAll('[data-path]').forEach(input => {
        const kind = input.dataset.type;
        let val = kind === 'checkbox' ? input.checked : kind === 'emoji-layout' ? input._editor.getLayers() : input.value;
        if (kind === 'number') val = Math.max(0, Math.min(360, parseInt(val, 10) || 0));
        const [root, idx] = input.dataset.path.split('.');
        if (idx !== undefined) {
          if (!update[root]) update[root] = [...(item[root] || [])];
          update[root][Number(idx)] = val;
        } else update[root] = val;
      });
      if (type === 'profile_frames') update.animated = !!update.glow;
      if ((type === 'decorations' || type === 'masks') && 'emojis' in update) {
        if (!update.emojis.length) { toast('Add at least one emoji.'); return; }
        update.emoji = update.emojis[0].e;
      }
      if (type === 'music') { update.disabled = !!($('shop-edit-disabled') && $('shop-edit-disabled').checked); await db.collection('config').doc('customMusic').set({ [id]: update }, { merge: true }); }
      else await db.collection(def.collection).doc(id).update(update);
    } else {
      await db.collection('config').doc('shopOverrides').set({ [shopOverrideKey(type, id)]: update }, { merge: true });
    }
    closeModal('shop-edit-modal');
    toast(`Saved "${name}".`);
  } catch (e) { toast(e.message || 'Could not save changes.', 'error'); }
};
$('shop-edit-reset-btn').onclick = async () => {
  if (!shopEditTarget || shopEditTarget.isCustom) return;
  try {
    await db.collection('config').doc('shopOverrides').set({ [shopOverrideKey(shopEditTarget.type, shopEditTarget.id)]: FieldValue.delete() }, { merge: true });
    closeModal('shop-edit-modal');
    toast('Reset to default.');
  } catch (e) { toast(e.message || 'Could not reset.', 'error'); }
};
$('shop-edit-delete-btn').onclick = () => {
  if (!shopEditTarget || !shopEditTarget.isCustom) return;
  const { type, id } = shopEditTarget;
  const def = SHOP_EDIT_TYPES[type];
  const item = def.custom().find(x => x.id === id);
  if (!canEditShopItem(item)) { toast('You can not delete this item.', 'error'); return; }
  if (type === 'music') {
    // Songs added by staff are stored in one config document. Only the Owner and Co-Owners can delete one; other staff can only disable it.
    if (!isOwner) { toast('Only the Owner and Co-Owners can delete a song. You can disable it instead.', 'error'); return; }
    confirmAction({
      title: 'Delete song', body: `Delete "${item ? item.name : 'this song'}" for good? It disappears from the Shop and from everyone who bought it, and this cannot be undone. To only hide it from the Shop, disable it instead.`, confirmLabel: 'Delete song',
      onConfirm: async () => {
        try {
          await db.collection('config').doc('customMusic').set({ [id]: FieldValue.delete() }, { merge: true });
          closeModal('shop-edit-modal');
          toast('Song deleted.');
        } catch (e) { toast(e.message || 'Could not delete the song.', 'error'); }
      },
    });
    return;
  }
  confirmAction({
    title: `Delete ${def.label}`, body: `Remove "${item ? item.name : 'this item'}" from the shop? People who bought it will lose it.`, confirmLabel: 'Delete',
    onConfirm: async () => {
      try {
        await db.collection(def.collection).doc(id).delete();
        closeModal('shop-edit-modal');
      }
      catch (e) { toast(e.message || 'Could not delete.', 'error'); }
    },
  });
};

document.querySelectorAll('.shop-mgr-tab').forEach(tab => {
  tab.onclick = () => {
    document.querySelectorAll('.shop-mgr-tab').forEach(t => t.classList.toggle('on', t === tab));
    const section = tab.dataset.shopSection;
    document.querySelectorAll('.shop-mgr-section').forEach(sec => sec.classList.toggle('hidden', !sec.dataset.shopSection.split(' ').includes(section)));
    if (section === 'masks' || section === 'decorations') setDecoCreatorKind(section === 'masks');
    if (section === 'music') updateMusicCardPreview();
  };
});

$('admin-filter-add').onclick = async () => {
  const word = ($('admin-filter-word').value || '').trim().toLowerCase();
  if (!word) { toast('Enter a word first.'); return; }
  if (filteredWords.includes(word)) { toast('That word is already filtered.'); return; }
  try {
    await db.collection('config').doc('filter').set({ words: FieldValue.arrayUnion(word) }, { merge: true });
    $('admin-filter-word').value = '';
  } catch (e) { toast('Could not add word.', 'error'); }
};
$('admin-filter-word').addEventListener('keydown', (e) => { if (e.key === 'Enter') $('admin-filter-add').click(); });

function renderAdminFilterList() {
  const wrap = $('admin-filter-list');
  const master = $('filter-master-toggle');
  master.checked = filterEnabled;
  master.disabled = !isOwner;                       // only Owner / Co-Owner can flip the master switch
  $('filter-master-title').textContent = filterEnabled ? 'Filter is on' : 'Filter is off';
  $('filter-master-note').textContent = isOwner
    ? 'Turn this off to stop filtering for everyone. Your words are kept.'
    : 'Only the Owner and Co-Owners can turn the whole filter on or off.';
  wrap.classList.toggle('filter-all-off', !filterEnabled);
  wrap.innerHTML = filteredWords.length
    ? filteredWords.slice().sort().map(w => {
        const off = disabledFilterWords.includes(w);
        return `<div class="admin-emoji-chip editable filter-chip ${off ? 'off' : ''}" data-w="${esc(w)}" role="switch" aria-checked="${!off}" tabindex="0" title="${off ? 'Off. Click to turn on' : 'On. Click to turn off'}"><span class="fc-dot"></span><span class="fc-word">${esc(w)}</span><span class="fc-state">${off ? 'Off' : 'On'}</span></div>`;
      }).join('')
    : '<div class="empty">No filtered words yet.</div>';
  wrap.querySelectorAll('.filter-chip').forEach(chip => {
    const flip = async () => {
      const w = chip.dataset.w, off = disabledFilterWords.includes(w);
      try {
        await db.collection('config').doc('filter').set({ disabledWords: off ? FieldValue.arrayRemove(w) : FieldValue.arrayUnion(w) }, { merge: true });
      } catch (e) { toast('Could not change that word.', 'error'); }
    };
    chip.onclick = flip;
    chip.onkeydown = e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); flip(); } };
  });
}
$('filter-master-toggle').onchange = async e => {
  const want = e.target.checked;
  if (!isOwner) { e.target.checked = filterEnabled; toast('Only the Owner and Co-Owners can do that.', 'error'); return; }
  try {
    await db.collection('config').doc('filter').set({ enabled: want }, { merge: true });
    toast(want ? 'Filter turned on.' : 'Filter turned off.');
  } catch (err) { e.target.checked = filterEnabled; toast('Could not change the filter.', 'error'); }
};

// The owner's "System Hub" tab and a regular admin's "Players" tab are
// mutually exclusive (only one is ever visible to a given person), so they
// share the same selected-user state and just target different containers.
function activeAdminListEl() { return isOwner ? 'system-hub-user-list' : 'admin-user-list'; }
function activeAdminSearchEl() { return isOwner ? 'system-hub-search' : 'admin-search'; }
function activeAdminActionsEl() { return isOwner ? 'system-hub-actions' : 'admin-actions'; }

async function renderAdminList() {
  const list = $(activeAdminListEl());
  if (!list) return;
  const q = ($(activeAdminSearchEl()).value || '').toLowerCase();
  list.innerHTML = '<div class="empty">Loading...</div>';
  let users = [];
  try {
    const snap = await db.collection('users').get();
    snap.forEach(d => users.push(d.data()));
  } catch (e) { list.innerHTML = '<div class="empty">Could not load users.</div>'; return; }
  users = users.filter(u => !q || u.username.toLowerCase().includes(q)).sort((a, b) => a.username.localeCompare(b.username));
  list.innerHTML = users.map(u => {
    const ban = banStatus(u);
    return `<div class="admin-row ${adminSelectedUser === u.username ? 'on' : ''}" data-u="${esc(u.username)}">
      ${avatarHTML(30, u.avatarColor, initials(u.username), null, u.avatarUrl)}
      <span class="ar-name">${esc(u.username)}</span>
      ${roleTag(u)}${ban.banned ? '<span class="ban-tag">Banned</span>' : ''}${muteStatus(u).muted ? '<span class="ban-tag mute-tag">Muted</span>' : ''}${u.terminated && u.terminated.mode === 'real' ? '<span class="ban-tag">Terminating</span>' : ''}
    </div>`;
  }).join('') || '<div class="empty">No users found.</div>';
  list.querySelectorAll('.admin-row').forEach(row => {
    row.onclick = () => { adminSelectedUser = row.dataset.u; renderAdminList(); renderAdminActions(); };
  });
  renderAdminActions();
}

async function renderAdminActions() {
  const wrap = $(activeAdminActionsEl());
  if (!wrap) return;
  if (!adminSelectedUser) { wrap.innerHTML = '<div class="empty">Select a user to manage.</div>'; return; }
  const snap = await db.collection('users').doc(adminSelectedUser).get();
  if (!snap.exists) { wrap.innerHTML = '<div class="empty">User not found.</div>'; adminSelectedUser = null; return; }
  const u = snap.data();
  if (!canManagePlatformUser(u)) {
    wrap.innerHTML = `<div class="admin-sel-head">${avatarHTML(44, u.avatarColor, initials(u.username), null, u.avatarUrl)}<div><div class="as-name">${esc(u.username)}${roleTag(u)}</div></div></div>
      <div class="empty">You can't manage a ${u.owner ? 'Owner' : 'Co-Owner'} — they outrank you.</div>`;
    return;
  }
  const ban = banStatus(u);
  queueMicrotask(() => renderCoOwnerBlock(wrap, u));
  wrap.innerHTML = `
    <div class="admin-sel-head">${avatarHTML(44, u.avatarColor, initials(u.username), null, u.avatarUrl)}<div><div class="as-name">${esc(u.username)}${roleTag(u)}</div><div class="as-sub">${ban.banned ? ('Banned — ' + esc(ban.reason)) : 'Not banned'}</div></div></div>
    <div class="admin-block">
      <div class="ab-title">Orbs — Balance: ${fmtOrbs(u.orbs)}</div>
      <div class="ab-row">
        <input id="admin-orbs-amt" type="number" min="1" placeholder="Amount" class="fld-input">
        <button class="btn-accent-inline slim" id="admin-orbs-grant">Grant</button>
        <button class="btn-secondary slim" id="admin-orbs-remove">Remove</button>
      </div>
    </div>
    <div class="admin-block">
      <div class="ab-title">Frixion Premium — ${isPremium(u) ? ('Active until ' + new Date(u.premiumUntil).toLocaleDateString()) : 'Not active'}</div>
      <div class="ab-row">
        <input id="admin-premium-days" type="number" min="1" placeholder="Days" class="fld-input">
        <button class="btn-accent-inline slim" id="admin-premium-grant">Grant</button>
        <button class="btn-secondary slim" id="admin-premium-remove">Remove</button>
      </div>
    </div>
    <div class="admin-block">
      <div class="ab-title">Mute${muteStatus(u).muted ? ' — muted' : ''}</div>
      ${muteStatus(u).muted ? `
      <div class="ab-row">
        <button class="btn-secondary slim" id="admin-unmute-btn">Unmute</button>
      </div>` : `
      <input id="admin-mute-reason" type="text" placeholder="Reason (optional)" class="fld-input" maxlength="120">
      <div class="ab-row" style="margin-top:8px">
        <button class="btn-accent-inline slim" id="admin-mute-btn">Mute</button>
      </div>`}
    </div>
    <div class="admin-block">
      <div class="ab-title">Ban${ban.banned ? ' — banned' : ''}</div>
      ${ban.banned ? `
      <div class="ab-row">
        <button class="btn-secondary slim" id="admin-unban-btn">Unban</button>
      </div>` : `
      <input id="admin-ban-reason" type="text" placeholder="Reason (optional)" class="fld-input" maxlength="120">
      <div class="ab-row" style="margin-top:8px">
        <button class="btn-danger slim" id="admin-ban-btn">Ban</button>
      </div>`}
    </div>
    ${isOwner ? `
    <div class="admin-block">
      <div class="ab-title">Operator</div>
      <div class="ab-row">
        <span class="ab-note">${u.op ? 'This user has full admin access with no password.' : 'Not an operator.'}</span>
        ${u.op
          ? `<button class="btn-secondary slim" id="admin-deop-btn">Remove Admin</button>`
          : `<button class="btn-accent-inline slim" id="admin-op-btn">Make Admin</button>`}
      </div>
    </div>
    <div class="admin-block">
      <div class="ab-title">Redirection</div>
      <div class="ab-row">
        <input id="admin-redirect-url" type="text" placeholder="https://example.com" class="fld-input">
        <button class="btn-accent-inline slim" id="admin-redirect-btn">Redirect</button>
      </div>
    </div>
    ${adminItemsBlockHTML(u)}
    <div id="admin-user-devices"></div>
    <div class="admin-block">
      <div class="ab-title">Danger Zone</div>
      <button class="btn-danger" id="admin-delete-btn">Delete Account</button>
      <button class="btn-secondary" id="admin-fake-delete-btn" style="margin-top:8px">Fake Delete (logs out)</button>
      <div class="ab-note" style="margin-top:6px;opacity:.7;font-size:12px">Delete Account sends the skull, then removes the account. Fake Delete plays the exact same thing, but only signs them out.</div>
    </div>` : ''}`;

  $('admin-orbs-grant').onclick = () => adminAdjustOrbs(u.username, 1);
  $('admin-orbs-remove').onclick = () => adminAdjustOrbs(u.username, -1);
  $('admin-premium-grant').onclick = () => adminAdjustPremium(u.username, 1);
  $('admin-premium-remove').onclick = () => adminAdjustPremium(u.username, -1);
  if (ban.banned) $('admin-unban-btn').onclick = adminUnban;
  else $('admin-ban-btn').onclick = adminBan;
  if (muteStatus(u).muted) $('admin-unmute-btn').onclick = adminUnmute;
  else $('admin-mute-btn').onclick = adminMute;
  if (isOwner) {
    if (u.op) $('admin-deop-btn').onclick = () => adminSetOp(u.username, false);
    else $('admin-op-btn').onclick = () => adminSetOp(u.username, true);
    $('admin-redirect-btn').onclick = () => adminRedirect(u.username);
    $('admin-delete-btn').onclick = adminDelete;
    $('admin-fake-delete-btn').onclick = adminFakeDelete;
    wrap.querySelectorAll('[data-rm-item]').forEach(b => { b.onclick = () => adminRemoveItem(u.username, b.dataset.field, b.dataset.id); });
    const itemSearch = wrap.querySelector('[data-items-search]');
    if (itemSearch) itemSearch.oninput = () => {
      const q = itemSearch.value.toLowerCase().trim();
      let shown = 0;
      wrap.querySelectorAll('.admin-item-row').forEach(r => { const hit = !q || r.textContent.toLowerCase().includes(q); r.hidden = !hit; if (hit) shown++; });
      wrap.querySelector('.admin-items-none').hidden = shown > 0;
    };
    loadUserDevicesBlock(u.username);
  }
}

async function adminAdjustPremium(username, sign) {
  const days = parseInt($('admin-premium-days').value || '0', 10);
  if (!days || days < 1) { toast('Enter a number of days.'); return; }
  try {
    const snap = await db.collection('users').doc(username).get();
    const u = snap.data();
    if (sign > 0) {
      const base = isPremium(u) ? u.premiumUntil : Date.now();
      await db.collection('users').doc(username).update({ premiumUntil: base + days * 86400000 });
    } else {
      const base = isPremium(u) ? u.premiumUntil : Date.now();
      const newUntil = Math.max(Date.now() - 1, base - days * 86400000);
      await db.collection('users').doc(username).update({ premiumUntil: newUntil });
    }
    toast(`${sign > 0 ? 'Granted' : 'Removed'} ${days} days of Premium ${sign > 0 ? 'to' : 'from'} ${username}.`);
    renderAdminActions();
  } catch (e) { toast('Could not update Premium.', 'error'); }
}

async function adminAdjustOrbs(username, sign) {
  const amt = parseInt($('admin-orbs-amt').value || '0', 10);
  if (!amt || amt < 1) { toast('Enter an amount.'); return; }
  try {
    await db.collection('users').doc(username).update({ orbs: FieldValue.increment(sign * amt) });
    toast(`${sign > 0 ? 'Granted' : 'Removed'} ${amt} Orbs ${sign > 0 ? 'to' : 'from'} ${username}.`);
    renderAdminActions();
  } catch (e) { toast('Could not update Orbs.', 'error'); }
}

// Only the real Owner can hand out or take away Co-Owner.
function renderCoOwnerBlock(wrap, u) {
  if (!myProfile || !myProfile.owner || u.username === myUid || u.owner) return;
  if (wrap.querySelector('#admin-coowner-block')) return;
  wrap.insertAdjacentHTML('beforeend', `
    <div class="admin-block" id="admin-coowner-block">
      <div class="ab-title">Co-Owner</div>
      <span class="ab-note">${u.coowner ? 'Can do everything you can, except manage you.' : 'Not a co-owner.'}</span>
      <div class="ab-row" style="margin-top:8px">
        <button class="${u.coowner ? 'btn-secondary' : 'btn-accent-inline'} slim" id="admin-coowner-btn">${u.coowner ? 'Remove Co-Owner' : 'Make Co-Owner'}</button>
      </div>
    </div>`);
  $('admin-coowner-btn').onclick = async () => {
    try {
      await db.collection('users').doc(u.username).update({ coowner: !u.coowner });
      toast(u.coowner ? `Removed co-owner from ${u.username}.` : `Made ${u.username} a co-owner.`);
      renderAdminList();
    } catch (e) { toast(e.message || 'Could not update co-owner.', 'error'); }
  };
}
function guardPlatformTarget(username) {
  const target = profileCache[username] || { username };
  if (!canManagePlatformUser(target)) { toast("You can't manage someone who outranks you.", 'error'); return false; }
  return true;
}
async function adminSetOp(username, val) {
  if (!isOwner) { toast('Only the owner can grant or remove admin.', 'error'); return; }
  if (!guardPlatformTarget(username)) return;
  await db.collection('users').doc(username).update({ op: val });
  if (username === myUid) { isAdmin = val; applyAdminVisibility(); }
  toast(val ? `Made ${username} an admin.` : `Removed admin from ${username}.`);
  renderAdminList();
}

async function adminBan() {
  const reason = ($('admin-ban-reason').value || '').trim() || 'No reason given';
  if (!adminSelectedUser) return;
  if (!guardPlatformTarget(adminSelectedUser)) return;
  // No timer: the ban lasts until someone presses Unban.
  await db.collection('users').doc(adminSelectedUser).update({ banned: true, banReason: reason, bannedUntil: null });
  toast(`Banned ${adminSelectedUser}.`);
  renderAdminList(); renderAdminActions();
}
// Muting follows the same hierarchy as banning: owners can act on anyone, co-owners on admins
// and members, admins on members. guardPlatformTarget() enforces it.
// Checks rank against the user's current document rather than a cached copy.
async function mayManage(username) {
  const snap = await db.collection('users').doc(username).get();
  if (!snap.exists || !canManagePlatformUser(snap.data())) { toast("You can't manage someone who outranks you.", 'error'); return false; }
  return true;
}
async function adminMute() {
  const reason = ($('admin-mute-reason').value || '').trim() || 'No reason given';
  if (!adminSelectedUser) return;
  if (!(await mayManage(adminSelectedUser))) return;
  // No timer: the mute lasts until someone presses Unmute.
  await db.collection('users').doc(adminSelectedUser).update({ mutedUntil: INDEFINITE_MUTE_UNTIL, muteReason: reason });
  toast(`Muted ${adminSelectedUser}.`);
  renderAdminList(); renderAdminActions();
}
async function adminUnmute() {
  if (!adminSelectedUser || !(await mayManage(adminSelectedUser))) return;
  await db.collection('users').doc(adminSelectedUser).update({ mutedUntil: null, muteReason: '' });
  toast(`Unmuted ${adminSelectedUser}.`);
  renderAdminList(); renderAdminActions();
}
async function adminUnban() {
  if (!adminSelectedUser) return;
  await db.collection('users').doc(adminSelectedUser).update({ banned: false, banReason: '', bannedUntil: null });
  toast(`Unbanned ${adminSelectedUser}.`);
  renderAdminList(); renderAdminActions();
}
async function adminRedirect(username) {
  if (!isOwner) { toast('Only the owner can redirect users.', 'error'); return; }
  if (!guardPlatformTarget(username)) return;
  const raw = ($('admin-redirect-url').value || '').trim();
  if (!raw) { toast('Enter a URL to redirect to.'); return; }
  const url = /^https?:\/\//i.test(raw) ? raw : 'https://' + raw;
  try {
    // The target's own client (its unsub.self listener) picks this up next
    // time it syncs and navigates itself there — there's no server push,
    // so it takes effect as soon as their client is listening/online.
    await db.collection('users').doc(username).update({ redirectUrl: url, redirectNonce: Date.now() });
    toast(`${username} will be redirected.`);
    $('admin-redirect-url').value = '';
  } catch (e) { toast(e.message || 'Could not redirect user.', 'error'); }
}
// Everything a person owns from the Shop, one row per item. Masks share a list with decorations, so rows are
// matched to a category by looking the id up in each catalog that uses that field.
function ownedShopRows(u) {
  const byField = {};
  Object.values(SHOP_CATEGORY_DEFS).forEach(def => { (byField[def.ownedField] = byField[def.ownedField] || []).push(def); });
  const rows = [];
  Object.entries(byField).forEach(([field, defs]) => {
    (u[field] || []).forEach(id => {
      const def = defs.find(d => d.catalog.some(i => i.id === id));
      const item = def && def.catalog.find(i => i.id === id);
      rows.push({ field, id, name: item ? item.name : id, label: def ? def.label : 'Removed item', equipped: defs.some(d => u[d.equipField] === id) });
    });
  });
  return rows;
}
function adminItemsBlockHTML(u) {
  const rows = ownedShopRows(u);
  return `<div class="admin-block">
      <div class="ab-title">Shop items (${rows.length})</div>
      ${rows.length ? '<input type="text" class="admin-items-search" data-items-search placeholder="Search items..." autocomplete="off" maxlength="60">' : ''}
      ${rows.length ? `<div class="admin-items-list">${rows.map(r => `<div class="admin-item-row"><span class="ai-name" title="${esc(r.name)}">${esc(r.name)}</span><span class="ai-cat">${esc(r.label)}</span>${r.equipped ? '<span class="ban-tag mute-tag">Equipped</span>' : ''}<button type="button" class="btn-secondary slim" data-rm-item data-field="${esc(r.field)}" data-id="${esc(r.id)}">Remove</button></div>`).join('')}</div>` : '<span class="ab-note">No Shop items.</span>'}
      <div class="ab-note admin-items-none" hidden>No items match.</div>
    </div>`;
}
async function adminRemoveItem(username, field, id) {
  if (!isOwner) { toast('Only the owner can remove items.', 'error'); return; }
  if (!guardPlatformTarget(username)) return;
  const defs = Object.values(SHOP_CATEGORY_DEFS).filter(d => d.ownedField === field);
  const hit = defs.map(d => d.catalog.find(i => i.id === id)).find(Boolean);
  const name = hit ? hit.name : id;
  confirmAction({
    title: 'Remove Item', body: `Remove ${name} from ${username}? It is taken off their account and unequipped. No Orbs are refunded.`, confirmLabel: 'Remove Item',
    onConfirm: async () => {
      try {
        const fresh = (await db.collection('users').doc(username).get()).data() || {};
        const patch = { [field]: FieldValue.arrayRemove(id) };
        defs.forEach(d => { if (fresh[d.equipField] === id) patch[d.equipField] = null; });
        await db.collection('users').doc(username).update(patch);
        toast(`Removed ${name} from ${username}.`);
      } catch (e) { toast(e.message || 'Could not remove that item.', 'error'); }
      renderAdminActions();
    },
  });
}

async function adminDelete() {
  if (!isOwner) { toast('Only the owner can delete accounts.', 'error'); return; }
  if (!adminSelectedUser || !guardPlatformTarget(adminSelectedUser)) return;
  const target = adminSelectedUser;
  confirmAction({
    title: 'Delete Account', body: `Permanently delete ${target}'s account? The skull comes for them first, and the account is removed when it reaches them (or the next time they sign in). This cannot be undone.`, confirmLabel: 'Delete Account',
    onConfirm: async () => {
      try {
        // Flag, don't delete: the target's own app plays the sequence and removes the account at the end.
        await db.collection('users').doc(target).update({ terminated: { mode: 'real', by: myUid, nonce: Date.now(), at: Date.now() } });
        toast(`Termination sent to ${target}. Their account is removed when it finishes.`);
      } catch (e) { toast(e.message || 'Could not delete account.', 'error'); return; }
      adminSelectedUser = null;
      renderAdminList();
    },
  });
}
// Owner-only rehearsal: identical sequence for the target, but it just signs them out.
async function adminFakeDelete() {
  if (!isOwner) { toast('Only the owner can fake delete.', 'error'); return; }
  if (!adminSelectedUser || !guardPlatformTarget(adminSelectedUser)) return;
  const target = adminSelectedUser;
  confirmAction({
    title: 'Fake Delete', body: `Play the full Account Terminated sequence for ${target}? Nothing is deleted. They are just signed out at the end.`, confirmLabel: 'Fake Delete', danger: false,
    onConfirm: async () => {
      try {
        await db.collection('users').doc(target).update({ terminated: { mode: 'fake', by: myUid, nonce: Date.now(), at: Date.now() } });
        toast(`Fake delete sent to ${target}. Their account is safe.`);
      } catch (e) { toast(e.message || 'Could not send fake delete.', 'error'); }
    },
  });
}

